INSERT INTO components (component_id, category_name, subcategory_name, name, display_name, description, region, climate_zone, spectrum_position, sort_order, base_cost_per_sqft_inr, installation_cost_per_sqft_inr, cost_confidence, cost_last_updated, cost_source_notes, expected_lifespan_years, replacement_cost_factor, major_maintenance_cycle_years, major_maintenance_cost_factor, annual_minor_maint_factor, maintenance_complexity, lifecycle_source_notes, thermal_resistance_score, acoustic_score, durability_score, moisture_resistance, fire_rating, energy_impact_modifier, accessibility_score, thermal_source_notes, max_floors_supported, min_floors_required, max_span_supported_m, incompatible_with, compatible_with, requires_component, climate_restrictions, hard_block_rule, advisory_rule, advisory_message, advisory_severity, constraint_source_notes, ai_advisory_notes, pros, cons, tooltip_detail, status, verify_flags, data_filled_by) VALUES ('EXC-001', 'Structure', 'Excavation Depth', 'excavation_600mm', '600 mm (2 ft)', 'Shallow excavation of 600mm depth. Suitable only where soil bearing capacity is confirmed adequate at this depth by soil investigation. Typically limited to soft-to-medium soils with very good bearing.', 'South India', 'Warm-Humid|Hot-Dry|Temperate|Composite', 'Basic', 1, 5, 3, 'Medium', '2024-Q1', 'Karnataka PWD SOR 2024-25 earthwork rates; normalized per sqft of footprint', 60, 0, 0, 0, 0, 'Low', 'Foundation depth is permanent - no replacement cycle', 5, 5, 5, 'Medium', 'Non-Rated', 0, 10, 'No thermal contribution.', 2, 1, 'N/A', 'G+2 or above without soil test confirmation', 'Strip foundation|Isolated footing', 'Soil bearing capacity test (SBC) confirming adequacy at 600mm', 'Not suitable for expansive (black cotton) soils or waterlogged areas without additional investigation.', 'None', 'Mandatory soil test before finalising at 600mm depth', '600mm excavation is only safe if a soil bearing capacity test confirms adequate load-bearing at this depth. Assuming shallow depth without a test is a serious structural risk.', 'Warning', 'IS 1904; NBC 2016 Part 6', 'Six hundred millimetres is the minimum excavation depth I will ever accept and only when a proper soil test confirms good bearing capacity at that level. In South India we have significant variation in soil - the red laterite soils of coastal Karnataka and parts of Tamil Nadu can be quite competent at shallow depths but black cotton soil found in parts of the Deccan and north Karnataka swells and shrinks dramatically with moisture changes and you absolutely cannot use a shallow foundation there. Before you decide on excavation depth insist on a soil bearing capacity test from a geotechnical lab - it costs Rs 8000-15000 and tells you exactly where the firm strata is. Skipping this test to save money is how houses crack within five years.', 'Lowest excavation cost|Faster foundation work|Less earthwork disposal', 'Only suitable for sites with confirmed high SBC at shallow depth|Not suitable for G+2 and above without investigation|Risk of settlement if soil weakens with water', '600mm excavation. Only for confirmed good bearing soils. Soil test mandatory before use.', 'Active', 'None', 'AI') ON CONFLICT (component_id) DO NOTHING;
INSERT INTO components (component_id, category_name, subcategory_name, name, display_name, description, region, climate_zone, spectrum_position, sort_order, base_cost_per_sqft_inr, installation_cost_per_sqft_inr, cost_confidence, cost_last_updated, cost_source_notes, expected_lifespan_years, replacement_cost_factor, major_maintenance_cycle_years, major_maintenance_cost_factor, annual_minor_maint_factor, maintenance_complexity, lifecycle_source_notes, thermal_resistance_score, acoustic_score, durability_score, moisture_resistance, fire_rating, energy_impact_modifier, accessibility_score, thermal_source_notes, max_floors_supported, min_floors_required, max_span_supported_m, incompatible_with, compatible_with, requires_component, climate_restrictions, hard_block_rule, advisory_rule, advisory_message, advisory_severity, constraint_source_notes, ai_advisory_notes, pros, cons, tooltip_detail, status, verify_flags, data_filled_by) VALUES ('EXC-002', 'Structure', 'Excavation Depth', 'excavation_900mm', '900 mm (3 ft)', 'Standard excavation depth of 900mm. Most appropriate for the majority of South India residential plots on medium-to-hard soils. This is the conventional default for G+1 to G+2 residential construction.', 'South India', 'Warm-Humid|Hot-Dry|Temperate|Composite', 'Intermediate', 2, 8, 5, 'High', '2024-Q1', 'Karnataka PWD SOR 2024-25 earthwork rates; standard residential depth; normalized per sqft', 60, 0, 0, 0, 0, 'Low', 'Foundation depth is permanent - no replacement cycle', 5, 5, 7, 'Medium', 'Non-Rated', 0, 10, 'No thermal contribution.', 3, 1, 'N/A', 'None', 'Strip foundation|Isolated footing|Plinth beam', 'Soil bearing capacity test recommended', 'May need increase in high-rainfall zones with water table within 600mm of surface.', 'None', 'None', '', '', 'IS 1904; NBC 2016 Part 6', 'Nine hundred millimetres is the standard excavation depth that most good contractors in Bangalore Chennai and Hyderabad will quote by default and it is correct for most residential plots. The logic is simple - you want to get below the zone of seasonal moisture variation which in South India is typically 600-750mm and then another 150mm into undisturbed firm strata. For a G+1 house on ordinary red soil or medium-hard murrum this depth is sufficient. Where I see contractors cut corners is when they stop at 750mm and call it 900mm - measure it yourself with a plumb line. The other issue is that most contractors excavate and backfill with loose soil rather than properly compacted material which causes settlement. Insist on proper plate compaction testing at every 150mm lift of backfill.', 'Standard depth for most South India soils|Good for G+1 to G+2 construction|Widely understood by all contractors|Economical', 'May be insufficient for black cotton soils|Needs increase for G+3 and above|Water table depth must be checked', 'Standard 900mm excavation. Suitable for most South India residential plots. Confirm water table depth.', 'Active', 'None', 'AI') ON CONFLICT (component_id) DO NOTHING;
INSERT INTO components (component_id, category_name, subcategory_name, name, display_name, description, region, climate_zone, spectrum_position, sort_order, base_cost_per_sqft_inr, installation_cost_per_sqft_inr, cost_confidence, cost_last_updated, cost_source_notes, expected_lifespan_years, replacement_cost_factor, major_maintenance_cycle_years, major_maintenance_cost_factor, annual_minor_maint_factor, maintenance_complexity, lifecycle_source_notes, thermal_resistance_score, acoustic_score, durability_score, moisture_resistance, fire_rating, energy_impact_modifier, accessibility_score, thermal_source_notes, max_floors_supported, min_floors_required, max_span_supported_m, incompatible_with, compatible_with, requires_component, climate_restrictions, hard_block_rule, advisory_rule, advisory_message, advisory_severity, constraint_source_notes, ai_advisory_notes, pros, cons, tooltip_detail, status, verify_flags, data_filled_by) VALUES ('EXC-003', 'Structure', 'Excavation Depth', 'excavation_1200mm', '1200 mm (4 ft)', 'Deep excavation of 1200mm. Required for hard rocky strata encountered at depth, areas with high water table, or G+3 and above construction. Also appropriate for black cotton soil where deeper firm strata must be reached.', 'South India', 'Warm-Humid|Hot-Dry|Temperate|Composite', 'Performance', 3, 12, 7, 'Medium', '2024-Q1', 'Karnataka PWD SOR 2024-25 deep earthwork rates; normalized per sqft', 60, 0, 0, 0, 0, 'Low', 'Foundation depth is permanent - no replacement cycle', 5, 5, 8, 'High', 'Non-Rated', 0, 10, 'No thermal contribution.', 5, 1, 'N/A', 'None', 'Strip foundation|Isolated footing|Raft foundation', 'Geotechnical soil investigation report|Dewatering pump if water table encountered', 'Essential in high water table areas and zones with seasonally waterlogged soils.', 'None', 'Dewatering required if water table encountered during excavation', 'If water seeps into excavation at this depth, a dewatering pump is mandatory before concrete is poured. Pouring concrete into a water-filled trench is a critical structural failure.', 'Warning', 'IS 1904; IS 3955; NBC 2016', 'Twelve hundred millimetres is where you end up when the soil investigation reveals that the bearing stratum is deeper than expected or when you are building G+3 and above and need the extra embedment depth for load transfer. In many parts of interior Karnataka and Andhra the topsoil is soft for the first 600-800mm and then transitions to murrum or rock - in these cases going to 1200mm puts your foundation firmly in the competent layer. The critical issue at this depth is water. If your plot has a seasonal water table within one and a half metres of surface you will hit water during excavation and you must have a dewatering pump on site before you start. Pouring foundation concrete with water in the trench is one of the most serious construction defects I know.', 'Reaches firm strata in most South India soil conditions|Suitable for G+3 and above|Good for high water table sites with dewatering|Black cotton soil management', 'Higher excavation cost and time|Dewatering may be needed|More earthwork disposal|Requires equipment for deep cuts', '1200mm deep excavation. For G+3 and above or deep bearing soils. Dewatering pump needed if water table is encountered.', 'Active', 'None', 'AI') ON CONFLICT (component_id) DO NOTHING;
INSERT INTO components (component_id, category_name, subcategory_name, name, display_name, description, region, climate_zone, spectrum_position, sort_order, base_cost_per_sqft_inr, installation_cost_per_sqft_inr, cost_confidence, cost_last_updated, cost_source_notes, expected_lifespan_years, replacement_cost_factor, major_maintenance_cycle_years, major_maintenance_cost_factor, annual_minor_maint_factor, maintenance_complexity, lifecycle_source_notes, thermal_resistance_score, acoustic_score, durability_score, moisture_resistance, fire_rating, energy_impact_modifier, accessibility_score, thermal_source_notes, max_floors_supported, min_floors_required, max_span_supported_m, incompatible_with, compatible_with, requires_component, climate_restrictions, hard_block_rule, advisory_rule, advisory_message, advisory_severity, constraint_source_notes, ai_advisory_notes, pros, cons, tooltip_detail, status, verify_flags, data_filled_by) VALUES ('EXC-004', 'Structure', 'Excavation Depth', 'excavation_1500mm', '1500 mm (5 ft)', 'Maximum standard excavation depth of 1500mm for residential construction. Required for deep bearing strata, very high water table zones, heavily loaded structures, or sites with highly compressible surface soils. Beyond this depth pile foundations are typically more economical.', 'South India', 'Warm-Humid|Hot-Dry|Temperate|Composite', 'Premium', 4, 18, 10, 'Medium', '2024-Q1', 'Karnataka PWD SOR 2024-25 deep earthwork + shoring rates; normalized per sqft', 60, 0, 0, 0, 0, 'Low', 'Foundation depth is permanent - no replacement cycle', 5, 5, 9, 'High', 'Non-Rated', 0, 10, 'No thermal contribution.', 8, 1, 'N/A', 'None', 'Raft foundation|Pile foundation|Isolated footing with plinth beam', 'Detailed geotechnical investigation report|Dewatering system|Shoring or trench support for safety', 'Mandatory in waterlogged plots and low-lying areas with high groundwater.', 'None', 'Trench safety shoring required at 1500mm depth per IS 3764', 'At 1500mm depth, excavation trench walls must be shored or battered per IS 3764 safety requirements. Unsupported vertical trenches at this depth are a collapse risk to workers.', 'Strong-Warning', 'IS 1904; IS 3764; NBC 2016', 'At fifteen hundred millimetres you are at the limit of practical hand excavation and into territory where you need to seriously consider whether a pile foundation would be more economical. The main situations where I specify this depth are waterlogged plots near lakes or rivers in Bangalore and Chennai where the seasonal water table is high and you need to get well below it before encountering firm soil. At this depth you have mandatory safety requirements - IS 3764 requires either shoring the trench walls or battering them at a safe angle because unsupported vertical walls at 1.5m can collapse and kill workers. Always have dewatering in place before excavation begins and pour concrete the same day you reach formation level - do not leave an open 1.5m trench overnight.', 'Reaches deepest firm strata|Best for heavily loaded structures|Essential for waterlogged plots|Maximum foundation stability', 'Highest excavation cost|Mandatory shoring for worker safety|Dewatering essential|Consider pile foundation as alternative', '1500mm deep excavation. Maximum standard residential depth. Trench shoring mandatory. Consider piles as alternative.', 'Active', 'None', 'AI') ON CONFLICT (component_id) DO NOTHING;
INSERT INTO components (component_id, category_name, subcategory_name, name, display_name, description, region, climate_zone, spectrum_position, sort_order, base_cost_per_sqft_inr, installation_cost_per_sqft_inr, cost_confidence, cost_last_updated, cost_source_notes, expected_lifespan_years, replacement_cost_factor, major_maintenance_cycle_years, major_maintenance_cost_factor, annual_minor_maint_factor, maintenance_complexity, lifecycle_source_notes, thermal_resistance_score, acoustic_score, durability_score, moisture_resistance, fire_rating, energy_impact_modifier, accessibility_score, thermal_source_notes, max_floors_supported, min_floors_required, max_span_supported_m, incompatible_with, compatible_with, requires_component, climate_restrictions, hard_block_rule, advisory_rule, advisory_message, advisory_severity, constraint_source_notes, ai_advisory_notes, pros, cons, tooltip_detail, status, verify_flags, data_filled_by) VALUES ('CONC-001', 'Structure', 'Concrete Mix', 'concrete_m15_pcc', 'M15 — Plain Cement Concrete (PCC)', 'M15 grade concrete (1:2:4 nominal mix, 15 N/mm² characteristic strength). Used exclusively for PCC applications - levelling courses, walkways, and lean concrete below foundations. NOT suitable for reinforced structural elements.', 'South India', 'Warm-Humid|Hot-Dry|Temperate|Composite', 'Basic', 1, 40, 20, 'High', '2024-Q1', 'CPWD DSR 2023 concrete items; Karnataka PWD SOR 2024-25; normalized per sqft of built-up area', 50, 1, 25, 0.3, 0, 'Low', 'IS 456; BIS concrete durability data', 5, 8, 5, 'Medium', 'Class A', 0, 10, 'High thermal mass - stores and releases heat. Requires insulation for comfort.', 1, 1, 'N/A', 'RCC structural elements|Beams|Columns|Slabs with reinforcement', 'Lean concrete below foundations|Flooring base course|Walkways|Plinth protection', 'None', 'None', 'NOT for use in reinforced structural elements - beams columns or slabs. PCC use only.', 'None', '', '', 'IS 456:2000; NBC 2016 Part 6', 'M15 is a PCC mix and using it for any reinforced element is a serious structural error that I see happen when clients try to save money on concrete grade. The nominal mix 1:2:4 gives 15 N/mm2 characteristic strength which is simply not enough for the steel to bond to properly and the element will fail under load. M15 has its place - it is the correct choice for the lean concrete layer you pour below your foundations to create a clean working surface and for non-structural walkways and plinth protection aprons. For anything that has steel in it you need M20 minimum. The other common mistake is using tap water mixed with river sand that has too much clay - always use measured water and check your sand quality. In coastal zones even M15 PCC needs proper curing for 14 days minimum or it will be porous and absorb moisture.', 'Lowest concrete cost|Adequate for non-structural PCC applications|Wide contractor familiarity', 'NOT suitable for RCC elements - structural failure risk|Lower durability than higher grades|Not suitable for exposed or aggressive environments', 'M15 PCC only. Never use for reinforced beams, columns or slabs. For lean concrete and non-structural uses only.', 'Active', 'None', 'AI') ON CONFLICT (component_id) DO NOTHING;
INSERT INTO components (component_id, category_name, subcategory_name, name, display_name, description, region, climate_zone, spectrum_position, sort_order, base_cost_per_sqft_inr, installation_cost_per_sqft_inr, cost_confidence, cost_last_updated, cost_source_notes, expected_lifespan_years, replacement_cost_factor, major_maintenance_cycle_years, major_maintenance_cost_factor, annual_minor_maint_factor, maintenance_complexity, lifecycle_source_notes, thermal_resistance_score, acoustic_score, durability_score, moisture_resistance, fire_rating, energy_impact_modifier, accessibility_score, thermal_source_notes, max_floors_supported, min_floors_required, max_span_supported_m, incompatible_with, compatible_with, requires_component, climate_restrictions, hard_block_rule, advisory_rule, advisory_message, advisory_severity, constraint_source_notes, ai_advisory_notes, pros, cons, tooltip_detail, status, verify_flags, data_filled_by) VALUES ('CONC-002', 'Structure', 'Concrete Mix', 'concrete_m20_standard_rcc', 'M20 — Standard RCC', 'M20 grade concrete (1:1.5:3 nominal mix, 20 N/mm² characteristic strength). Standard grade for all RCC elements in residential construction up to G+2. Most common choice for foundations, slabs, beams and columns in South India.', 'South India', 'Warm-Humid|Hot-Dry|Temperate|Composite', 'Intermediate', 2, 52, 25, 'High', '2024-Q1', 'CPWD DSR 2023; Karnataka PWD SOR 2024-25 RCC items; Bangalore market rate 2024', 60, 1, 30, 0.2, 0, 'Low', 'IS 456; BIS concrete durability for moderate exposure', 5, 8, 7, 'Medium', 'Class A', 0, 10, 'High thermal mass. Roof slab at M20 requires weathering course or insulation.', 3, 1, '4.5', 'G+3 and above without structural engineer approval|Seismic Zone IV-V without upgrade', 'Strip foundation|Isolated footing|RCC roof slab|Beams|Columns up to G+2', 'Fe500 or Fe500D TMT steel|Vibrator for compaction|14-day curing', 'In coastal zones (Mangalore, Chennai, Kochi) upgrade to M25 for better chloride resistance.', 'None', 'Use M25 in coastal zones or seismic zones III-IV for better durability', 'M20 in coastal areas has reduced durability due to chloride ingress. Consider M25 for any plot within 10km of the sea or in seismic zones III-IV.', 'Warning', 'IS 456:2000; ECBC 2017; NBC 2016', 'M20 is the workhorse of South India residential construction and for a G+1 or G+2 house on a normal plot it is the correct and adequate choice. The most important thing about M20 is not the grade itself but how it is made and cured on site. I have seen beautifully designed structures fail because the contractor added extra water to the mix to make it flow easier - every additional litre of water per bag of cement reduces the final strength by about 15 percent. Always insist on a fixed water-cement ratio and use a vibrator for compaction. The second most important thing is curing - M20 needs a minimum of 14 days of continuous wet curing. Covering with jute bags and keeping them wet morning and evening is not optional. A poorly cured M20 slab will have strength closer to M12 and will crack within two monsoons.', 'Standard grade for all residential RCC up to G+2|Wide contractor knowledge|Good durability for most South India conditions|Economical', 'Insufficient for G+3 and above without engineer review|Reduced chloride resistance in coastal zones|Quality highly dependent on site mixing discipline', 'M20 standard RCC for G+1-G+2. Most common residential grade. Curing for 14 days mandatory. Consider M25 for coastal plots.', 'Active', 'None', 'AI') ON CONFLICT (component_id) DO NOTHING;
INSERT INTO components (component_id, category_name, subcategory_name, name, display_name, description, region, climate_zone, spectrum_position, sort_order, base_cost_per_sqft_inr, installation_cost_per_sqft_inr, cost_confidence, cost_last_updated, cost_source_notes, expected_lifespan_years, replacement_cost_factor, major_maintenance_cycle_years, major_maintenance_cost_factor, annual_minor_maint_factor, maintenance_complexity, lifecycle_source_notes, thermal_resistance_score, acoustic_score, durability_score, moisture_resistance, fire_rating, energy_impact_modifier, accessibility_score, thermal_source_notes, max_floors_supported, min_floors_required, max_span_supported_m, incompatible_with, compatible_with, requires_component, climate_restrictions, hard_block_rule, advisory_rule, advisory_message, advisory_severity, constraint_source_notes, ai_advisory_notes, pros, cons, tooltip_detail, status, verify_flags, data_filled_by) VALUES ('CONC-003', 'Structure', 'Concrete Mix', 'concrete_m25_high_strength', 'M25 — High Strength RCC', 'M25 grade concrete (design mix, 25 N/mm² characteristic strength). Required for G+3 and above residential construction and for all structural elements in seismic zones III and IV. Better durability and chloride resistance than M20.', 'South India', 'Warm-Humid|Hot-Dry|Temperate|Composite', 'Performance', 3, 62, 28, 'High', '2024-Q1', 'CPWD DSR 2023; Karnataka PWD SOR 2024-25; design mix premium over M20', 70, 1, 35, 0.15, 0, 'Low', 'IS 456; BIS concrete durability for severe exposure', 5, 8, 8, 'High', 'Class A', 0, 10, 'Higher density than M20 - slightly better thermal mass performance.', 6, 1, '6', 'None', 'All structural systems|Seismic Zone III-IV construction', 'Design mix from RMC plant or certified batching|Fe500D TMT steel|Vibrator|21-day curing', 'Recommended for all coastal construction within 10km of sea. Mandatory for seismic zones III-IV.', 'None', 'Design mix from RMC plant strongly recommended over site batching for M25', 'M25 should ideally be supplied as Ready Mix Concrete (RMC) with a delivery challan showing the mix design. Site batching of M25 is unreliable without proper equipment and calibrated measures.', 'Warning', 'IS 456:2000; IS 10262; NBC 2016', 'M25 is where I draw the line for G+3 construction and coastal plots. The strength increase from M20 to M25 costs roughly 15-20 percent more but gives you significantly better protection against the two biggest concrete problems in South India - carbonation and chloride ingress from sea air and coastal humidity. The important thing about M25 is that it really should come from a Ready Mix Concrete plant because site batching at this grade without calibrated equipment and a proper mix design is unreliable. A poorly batched M25 can actually be weaker than a well-batched M20. Get the RMC delivery challan showing the mix design and slump value and insist on a vibrator for every pour. In seismic zones III and IV M25 with Fe500D steel is the minimum I will put my name on.', 'Required grade for G+3 and above|Better durability in coastal and humid conditions|IS recommended for seismic zones III-IV|Higher strength allows smaller member sizes', 'Higher cost than M20|Site batching unreliable - RMC plant recommended|Requires design mix not nominal mix', 'M25 for G+3+, coastal plots, and seismic zones III-IV. Use RMC plant supply for reliable quality.', 'Active', 'None', 'AI') ON CONFLICT (component_id) DO NOTHING;
INSERT INTO components (component_id, category_name, subcategory_name, name, display_name, description, region, climate_zone, spectrum_position, sort_order, base_cost_per_sqft_inr, installation_cost_per_sqft_inr, cost_confidence, cost_last_updated, cost_source_notes, expected_lifespan_years, replacement_cost_factor, major_maintenance_cycle_years, major_maintenance_cost_factor, annual_minor_maint_factor, maintenance_complexity, lifecycle_source_notes, thermal_resistance_score, acoustic_score, durability_score, moisture_resistance, fire_rating, energy_impact_modifier, accessibility_score, thermal_source_notes, max_floors_supported, min_floors_required, max_span_supported_m, incompatible_with, compatible_with, requires_component, climate_restrictions, hard_block_rule, advisory_rule, advisory_message, advisory_severity, constraint_source_notes, ai_advisory_notes, pros, cons, tooltip_detail, status, verify_flags, data_filled_by) VALUES ('CONC-004', 'Structure', 'Concrete Mix', 'concrete_m30_structural_premium', 'M30 — Structural Premium', 'M30 grade concrete (design mix, 30 N/mm² characteristic strength). Required for G+4 and above, heavily loaded transfer structures, prestressed elements, and construction in seismic zone V. Exclusively from RMC plant supply.', 'South India', 'Warm-Humid|Hot-Dry|Temperate|Composite', 'Premium', 4, 75, 32, 'Medium', '2024-Q1', 'RMC plant rates Bangalore/Hyderabad/Chennai 2024; M30 premium over M25; normalized per sqft', 75, 1, 40, 0.1, 0, 'Low', 'IS 456; high-strength concrete durability data', 5, 8, 10, 'Very High', 'Class A', 0, 10, 'Dense concrete - very high thermal mass.', 10, 1, '8', 'None', 'All structural systems|Prestressed elements|Heavy commercial construction', 'Certified RMC plant with IS 4926 compliance|Fe500D or Fe550 TMT steel|Pump delivery for upper floors|28-day curing', 'None', 'None', 'RMC plant supply mandatory - site batching not acceptable for M30', 'M30 cannot be reliably produced by site batching. A certified RMC plant with a validated mix design is mandatory. Request the mix design report and delivery challan for every truck.', 'Strong-Warning', 'IS 456:2000; IS 10262; IS 4926', 'M30 is the grade I specify for G+4 residential buildings heavy transfer slabs over commercial spaces and seismic zone V construction. For most private residential construction on a plot in Bangalore or Chennai G+3 on M25 is sufficient and M30 is overkill that adds unnecessary cost. But if your structural engineer has specified M30 there is a reason - do not ask him to reduce the grade to save money. The absolute rule with M30 is that it must come from an RMC plant. There is no practical way to batch M30 reliably on site without a weigh batcher and calibrated equipment. Always request the mix design report from the RMC plant and check that the delivery challan matches the specified slump and water-cement ratio.', 'Maximum strength for tall structures|Seismic zone V compliance|Best durability and longevity|Smallest structural member sizes', 'Highest concrete cost|RMC plant supply mandatory|Requires pump placement for upper floors|Not needed for typical residential construction', 'M30 for G+4+, seismic zone V, heavy loads. RMC plant supply mandatory. Not needed for typical residential construction.', 'Active', 'None', 'AI') ON CONFLICT (component_id) DO NOTHING;
INSERT INTO components (component_id, category_name, subcategory_name, name, display_name, description, region, climate_zone, spectrum_position, sort_order, base_cost_per_sqft_inr, installation_cost_per_sqft_inr, cost_confidence, cost_last_updated, cost_source_notes, expected_lifespan_years, replacement_cost_factor, major_maintenance_cycle_years, major_maintenance_cost_factor, annual_minor_maint_factor, maintenance_complexity, lifecycle_source_notes, thermal_resistance_score, acoustic_score, durability_score, moisture_resistance, fire_rating, energy_impact_modifier, accessibility_score, thermal_source_notes, max_floors_supported, min_floors_required, max_span_supported_m, incompatible_with, compatible_with, requires_component, climate_restrictions, hard_block_rule, advisory_rule, advisory_message, advisory_severity, constraint_source_notes, ai_advisory_notes, pros, cons, tooltip_detail, status, verify_flags, data_filled_by) VALUES ('STEEL-001', 'Structure', 'Steel Grade', 'steel_fe415', 'Fe 415 TMT Steel', 'Fe 415 grade TMT (Thermo-Mechanically Treated) reinforcement bars per IS 1786. Older BIS standard with 415 N/mm² yield strength. Still available but largely superseded by Fe 500 in modern construction.', 'South India', 'Warm-Humid|Hot-Dry|Temperate|Composite', 'Basic', 1, 28, 8, 'Medium', '2024-Q1', 'Steel market rate South India 2024; Fe415 is rare - estimate based on Fe500 minus 5%; normalized per sqft', 60, 0, 0, 0, 0, 'Low', 'IS 1786; embedded steel lifespan = structure lifespan if no corrosion', 5, 5, 6, 'Medium', 'Class A', 0, 10, 'No thermal contribution as embedded reinforcement.', 3, 1, '4', 'G+3 and above without engineer review|Seismic zones III-V', 'M15 PCC|M20 RCC|Low-rise residential up to G+2', 'IS 1786 BIS certification mark on bars|Mill test certificate', 'In coastal zones corrosion protection (epoxy-coated bars or stainless) recommended.', 'None', 'Fe415 is largely obsolete - confirm availability and BIS mark before specifying', 'Fe415 has been largely phased out in favour of Fe500. Verify that BIS-certified Fe415 is available from your steel supplier before specifying it.', 'Warning', 'IS 1786:2008; NBC 2016', 'Fe415 is essentially legacy steel that you will struggle to find from reputable mills today. Most major producers have moved to Fe500 as their standard grade. The only reason to consider Fe415 is if you are matching existing construction in a renovation or extension project. For new construction there is no practical benefit over Fe500 - Fe500 gives you higher strength which means either stronger members for the same amount of steel or the same strength with less steel weight. If your contractor quotes you Fe415 ask him to show you the BIS certification mark on the bundle tag because there is a real risk of getting substandard steel labelled as Fe415 from small operators. Always insist on a mill test certificate from the manufacturer.', 'Available for legacy/matching work|Lower yield stress - slightly more ductile than Fe500 in old designs', 'Largely obsolete - hard to source certified material|Lower strength than Fe500|Requires more steel by weight for same structural performance|Not recommended for seismic zones', 'Fe415 is obsolete. Hard to source with BIS certification. Use Fe500 or Fe500D for all new construction.', 'Active', 'None', 'AI') ON CONFLICT (component_id) DO NOTHING;
INSERT INTO components (component_id, category_name, subcategory_name, name, display_name, description, region, climate_zone, spectrum_position, sort_order, base_cost_per_sqft_inr, installation_cost_per_sqft_inr, cost_confidence, cost_last_updated, cost_source_notes, expected_lifespan_years, replacement_cost_factor, major_maintenance_cycle_years, major_maintenance_cost_factor, annual_minor_maint_factor, maintenance_complexity, lifecycle_source_notes, thermal_resistance_score, acoustic_score, durability_score, moisture_resistance, fire_rating, energy_impact_modifier, accessibility_score, thermal_source_notes, max_floors_supported, min_floors_required, max_span_supported_m, incompatible_with, compatible_with, requires_component, climate_restrictions, hard_block_rule, advisory_rule, advisory_message, advisory_severity, constraint_source_notes, ai_advisory_notes, pros, cons, tooltip_detail, status, verify_flags, data_filled_by) VALUES ('STEEL-002', 'Structure', 'Steel Grade', 'steel_fe500', 'Fe 500 TMT Steel', 'Fe 500 grade TMT reinforcement bars per IS 1786. Current BIS standard with 500 N/mm² yield strength. Most widely used grade for residential construction in South India. Good strength-to-cost ratio.', 'South India', 'Warm-Humid|Hot-Dry|Temperate|Composite', 'Intermediate', 2, 32, 8, 'High', '2024-Q1', 'JSW/Tata/SAIL steel prices South India 2024; Fe500 standard grade; normalized per sqft built-up area', 60, 0, 0, 0, 0, 'Low', 'IS 1786; embedded steel lifespan = structure lifespan if no corrosion', 5, 5, 8, 'Medium', 'Class A', 0, 10, 'No thermal contribution as embedded reinforcement.', 4, 1, '5', 'None', 'M20 and above concrete|All residential structural systems', 'IS 1786 BIS certification mark|Mill test certificate from manufacturer', 'In coastal zones within 5km of sea consider epoxy-coated Fe500 or upgrade to Fe500D.', 'None', 'Always check BIS certification mark on every bar bundle', 'Significant quantities of uncertified or mislabelled steel circulate in South India markets. Check the BIS certification mark and the rolling marks on the bar surface. Insist on a mill test certificate.', 'Warning', 'IS 1786:2008; NBC 2016', 'Fe500 is what I specify for the vast majority of residential projects and it is the right choice for G+1 to G+3 construction. The 500 N/mm2 yield strength means you need about 17 percent less steel by weight compared to Fe415 for the same structural performance which partially offsets the slightly higher per-tonne cost. The quality issue I cannot emphasise enough is the proliferation of fake or substandard steel in South India markets. I have tested bars from local dealers that failed at 350 N/mm2 while being sold as Fe500. The protection against this is simple - buy only from authorised distributors of major mills like Tata Tiscon SAIL JSW or RINL and insist on the mill test certificate. Check the BIS certification mark and the raised letters on the bar itself which encode the manufacturer and grade. Never buy steel without these marks regardless of the price advantage.', 'Current BIS standard - widely available|Good strength for residential construction|Better value than Fe415 (less weight for same strength)|Major mill products well certified', 'Fake/substandard steel common in market - buy from authorised dealers only|Not recommended for seismic zones III-IV (use Fe500D)|Moderate ductility compared to Fe500D', 'Fe500 standard grade for all residential construction. Buy from authorised dealer only - fake steel is common. Mill test certificate mandatory.', 'Active', 'None', 'AI') ON CONFLICT (component_id) DO NOTHING;
INSERT INTO components (component_id, category_name, subcategory_name, name, display_name, description, region, climate_zone, spectrum_position, sort_order, base_cost_per_sqft_inr, installation_cost_per_sqft_inr, cost_confidence, cost_last_updated, cost_source_notes, expected_lifespan_years, replacement_cost_factor, major_maintenance_cycle_years, major_maintenance_cost_factor, annual_minor_maint_factor, maintenance_complexity, lifecycle_source_notes, thermal_resistance_score, acoustic_score, durability_score, moisture_resistance, fire_rating, energy_impact_modifier, accessibility_score, thermal_source_notes, max_floors_supported, min_floors_required, max_span_supported_m, incompatible_with, compatible_with, requires_component, climate_restrictions, hard_block_rule, advisory_rule, advisory_message, advisory_severity, constraint_source_notes, ai_advisory_notes, pros, cons, tooltip_detail, status, verify_flags, data_filled_by) VALUES ('STEEL-003', 'Structure', 'Steel Grade', 'steel_fe500d_ductile', 'Fe 500D — Ductile Grade', 'Fe 500D grade TMT bars per IS 1786. Same 500 N/mm² yield strength as Fe500 but with enhanced ductility (higher elongation at failure) critical for seismic performance. The D suffix denotes ductile. Recommended for all seismic zone III and IV construction.', 'South India', 'Warm-Humid|Hot-Dry|Temperate|Composite', 'Performance', 3, 35, 9, 'High', '2024-Q1', 'JSW/Tata Tiscon Fe500D premium over Fe500; South India market 2024; normalized per sqft', 60, 0, 0, 0, 0, 'Low', 'IS 1786; IS 13920 seismic ductility requirements', 5, 5, 9, 'Medium', 'Class A', 0, 10, 'No thermal contribution as embedded reinforcement.', 6, 1, '6', 'None', 'M20 and above concrete|All structural systems|Seismic zone III-IV construction', 'IS 1786 BIS certification mark with D designation|Mill test certificate showing UTS/YS ratio and elongation', 'None', 'None', 'Verify D grade marking on bars - plain Fe500 is sometimes supplied instead', 'Confirm the D grade designation on both the mill test certificate and the bar marking. Some suppliers substitute plain Fe500 for Fe500D. The bar rolling marks should include the D designation.', 'Warning', 'IS 1786:2008; IS 13920:2016; NBC 2016', 'Fe500D is my default specification for any new residential construction in South India and the cost premium over plain Fe500 is minimal - typically 3-5 percent per tonne. The reason to always choose the D grade is ductility. In an earthquake the energy is dissipated through controlled plastic deformation of the steel. Plain Fe500 can be brittle at failure whereas Fe500D has the higher elongation specified in IS 13920 which means it bends before it breaks giving occupants critical seconds to exit. Most of Karnataka is in seismic zone II to III and parts of the Western Ghats coast are zone III - this is not a theoretical risk. The practical issue is verification - always check that the mill test certificate shows the UTS/YS ratio above 1.25 and elongation above 16 percent as specified in IS 1786 for the D grade. These numbers are what make it seismically ductile.', 'Enhanced ductility critical for seismic performance|IS 13920 compliant for earthquake zones|Same strength as Fe500 with better failure behaviour|Minimal cost premium over Fe500', 'Slightly higher cost than plain Fe500|Must verify D grade marking - substitution risk|Not widely stocked at all small dealers', 'Fe500D ductile grade. Recommended for all South India construction. Verify D marking on bars and mill certificate. Small cost premium over Fe500.', 'Active', 'None', 'AI') ON CONFLICT (component_id) DO NOTHING;
INSERT INTO components (component_id, category_name, subcategory_name, name, display_name, description, region, climate_zone, spectrum_position, sort_order, base_cost_per_sqft_inr, installation_cost_per_sqft_inr, cost_confidence, cost_last_updated, cost_source_notes, expected_lifespan_years, replacement_cost_factor, major_maintenance_cycle_years, major_maintenance_cost_factor, annual_minor_maint_factor, maintenance_complexity, lifecycle_source_notes, thermal_resistance_score, acoustic_score, durability_score, moisture_resistance, fire_rating, energy_impact_modifier, accessibility_score, thermal_source_notes, max_floors_supported, min_floors_required, max_span_supported_m, incompatible_with, compatible_with, requires_component, climate_restrictions, hard_block_rule, advisory_rule, advisory_message, advisory_severity, constraint_source_notes, ai_advisory_notes, pros, cons, tooltip_detail, status, verify_flags, data_filled_by) VALUES ('STEEL-004', 'Structure', 'Steel Grade', 'steel_fe550', 'Fe 550 — High Strength', 'Fe 550 grade TMT bars per IS 1786. 550 N/mm² yield strength - the highest standard grade for residential use. Allows reduction in steel quantity by approximately 10% compared to Fe500. For G+4 and above, seismic zone IV-V, and heavily loaded structures.', 'South India', 'Warm-Humid|Hot-Dry|Temperate|Composite', 'Premium', 4, 40, 10, 'Medium', '2024-Q1', 'SAIL/RINL Fe550 market rate South India 2024; normalized per sqft', 60, 0, 0, 0, 0, 'Low', 'IS 1786; high-strength steel performance data', 5, 5, 10, 'Medium', 'Class A', 0, 10, 'No thermal contribution as embedded reinforcement.', 10, 1, '8', 'None', 'M25 and above concrete|G+4 and above structures|Heavy commercial construction', 'IS 1786 BIS certification mark|Structural engineer design approval|RMC M25+ concrete', 'None', 'None', 'Only specify when structural engineer has designed for Fe550 strength - not a drop-in replacement for Fe500', 'Fe550 changes the structural design - bar diameters and quantities will be different from an Fe500 design. Only use when your structural engineer has specifically designed for this grade.', 'Warning', 'IS 1786:2008; NBC 2016', 'Fe550 is specified by structural engineers for tall residential buildings and heavily loaded transfer structures where the higher yield strength allows a meaningful reduction in steel quantity and therefore construction cost at scale. For a typical 30x40 or 40x60 plot G+2 or G+3 house the cost saving does not justify the reduced availability and the need for a specific structural redesign. If your structural engineer has specified Fe550 it is because the member sizes or loading genuinely benefit from the higher grade - do not ask him to downgrade to Fe500 to save a few rupees because the design will need to be reworked. The availability of genuinely certified Fe550 is more limited than Fe500 so insist on major mill supply with test certificates.', 'Highest standard residential grade - maximum structural efficiency|Allows smaller member sizes for same load|Best for G+4+ and heavily loaded structures', 'Must be specifically designed for - not a drop-in replacement|Less widely available than Fe500/Fe500D|Higher cost|Requires M25+ concrete to realise full benefit', 'Fe550 high strength for G+4+ and heavily loaded structures. Must be specifically designed for. Not a direct substitute for Fe500.', 'Active', 'None', 'AI') ON CONFLICT (component_id) DO NOTHING;
INSERT INTO components (component_id, category_name, subcategory_name, name, display_name, description, region, climate_zone, spectrum_position, sort_order, base_cost_per_sqft_inr, installation_cost_per_sqft_inr, cost_confidence, cost_last_updated, cost_source_notes, expected_lifespan_years, replacement_cost_factor, major_maintenance_cycle_years, major_maintenance_cost_factor, annual_minor_maint_factor, maintenance_complexity, lifecycle_source_notes, thermal_resistance_score, acoustic_score, durability_score, moisture_resistance, fire_rating, energy_impact_modifier, accessibility_score, thermal_source_notes, max_floors_supported, min_floors_required, max_span_supported_m, incompatible_with, compatible_with, requires_component, climate_restrictions, hard_block_rule, advisory_rule, advisory_message, advisory_severity, constraint_source_notes, ai_advisory_notes, pros, cons, tooltip_detail, status, verify_flags, data_filled_by) VALUES ('DPC-001', 'Structure', 'Damp Proof Course', 'dpc_cement_mortar', 'Cement Mortar DPC (1:3)', 'Damp Proof Course using 20mm thick cement mortar in 1:3 ratio (cement:sand) applied at plinth level. Standard economical DPC method widely used across South India for residential construction.', 'South India', 'Warm-Humid|Hot-Dry|Temperate|Composite', 'Basic', 1, 3, 2, 'High', '2024-Q1', 'Karnataka PWD SOR 2024-25 plastering rates; DPC application normalized per sqft of wall footprint', 20, 0.8, 20, 0.8, 0, 'Low', 'IS 3067; cement mortar DPC typical lifespan 15-25 years', 5, 5, 6, 'Medium', 'Class A', 0, 10, 'No significant thermal contribution.', 20, 1, 'N/A', 'None', 'All wall systems|All foundation types', 'Cement OPC 43 or 53 grade|Clean river sand|Proper curing for 7 days', 'In very high rainfall areas (above 2500mm annual) or flood-prone plots upgrade to bituminous felt or polymer membrane.', 'None', 'Apply while base concrete is green - not on dry hardened surface', 'Cement mortar DPC must be applied while the base concrete below is still slightly green (within 24-48 hours of pour) for good bond. Application on a dry dusty surface fails within a few years.', 'Warning', 'IS 3067; IS 2212', 'Cement mortar DPC is the standard choice for most residential construction in Karnataka and Tamil Nadu and it works adequately when applied correctly. The most common failure I see is contractors applying it on a dusty dry surface days after the base concrete has cured - the mortar then has no bond and peels away within a few monsoons allowing moisture to wick up the wall. The DPC must go down while the concrete below is still slightly green and the surface must be wetted and cleaned of dust before application. The 1:3 ratio is important - contractors sometimes use 1:4 or 1:5 to save cement and the result is a porous layer that does not stop moisture. For plots in normal rain zones with no flooding risk cement mortar DPC is the correct and economical choice.', 'Lowest cost|Widely understood by all masons|Adequate for most South India plots|Easy repair if damaged', 'Shorter lifespan than bituminous or polymer options|Less effective in flood-prone areas|Requires correct application timing for good bond|Degrades if repeatedly saturated', 'Standard cement mortar DPC. Apply on green concrete within 48 hours. Use 1:3 ratio only. Adequate for most residential plots.', 'Active', 'None', 'AI') ON CONFLICT (component_id) DO NOTHING;
INSERT INTO components (component_id, category_name, subcategory_name, name, display_name, description, region, climate_zone, spectrum_position, sort_order, base_cost_per_sqft_inr, installation_cost_per_sqft_inr, cost_confidence, cost_last_updated, cost_source_notes, expected_lifespan_years, replacement_cost_factor, major_maintenance_cycle_years, major_maintenance_cost_factor, annual_minor_maint_factor, maintenance_complexity, lifecycle_source_notes, thermal_resistance_score, acoustic_score, durability_score, moisture_resistance, fire_rating, energy_impact_modifier, accessibility_score, thermal_source_notes, max_floors_supported, min_floors_required, max_span_supported_m, incompatible_with, compatible_with, requires_component, climate_restrictions, hard_block_rule, advisory_rule, advisory_message, advisory_severity, constraint_source_notes, ai_advisory_notes, pros, cons, tooltip_detail, status, verify_flags, data_filled_by) VALUES ('DPC-002', 'Structure', 'Damp Proof Course', 'dpc_bituminous_felt', 'Bituminous Felt DPC', 'Damp Proof Course using bitumen-impregnated hessian felt (Type 1 or Type 2 per IS 1322) sandwiched between cement mortar beds at plinth level. Better moisture barrier than plain cement mortar, moderate cost.', 'South India', 'Warm-Humid|Hot-Dry|Temperate|Composite', 'Intermediate', 2, 8, 4, 'High', '2024-Q1', 'IS 1322 bitumen felt material cost; contractor application rate; Karnataka PWD SOR 2024-25 reference', 30, 0.6, 30, 0.6, 0, 'Low', 'IS 1322; bitumen felt lifespan 25-35 years in embedded condition', 5, 5, 7, 'High', 'Class B', 0, 10, 'No significant thermal contribution.', 20, 1, 'N/A', 'None', 'All wall systems|All foundation types', 'IS 1322 Type 1 or Type 2 bitumen felt|Hot bitumen or cold bitumen adhesive|Cement mortar bed above and below', 'Good choice for high rainfall areas. For flood-prone plots with regular inundation upgrade to polymer membrane.', 'None', 'Overlap felt sheets by minimum 100mm at joints', 'Bituminous felt sheets must overlap by minimum 100mm at all joints and the joint must be sealed with hot or cold bitumen adhesive. Gaps at joints create moisture entry points that defeat the DPC purpose.', 'Warning', 'IS 1322; IS 3067', 'Bituminous felt DPC is a meaningful upgrade over plain cement mortar and the cost difference is modest - maybe Rs 5-8 per sqft of wall length. The felt creates a genuine continuous impermeable barrier that cement mortar cannot match. The key to installation is overlapping the sheets by at least 100mm at every joint and sealing with bitumen adhesive because any gap will be found by capillary moisture within a few years. I recommend this option for any plot in a coastal or high-rainfall zone or where the finished floor level is less than 600mm above external ground. The typical lifespan is 25-35 years in embedded condition which covers most of the useful life of the building.', 'Better moisture barrier than cement mortar|30-year lifespan|Moderate cost|Good for high-rainfall zones', 'Higher cost than cement mortar DPC|Joint lapping and sealing critical|Not suitable for regularly flooded plots|Some fire rating reduction vs cement only', 'Bituminous felt DPC. Better than cement mortar. Overlap sheets 100mm minimum and seal joints with bitumen. Good for high-rainfall zones.', 'Active', 'None', 'AI') ON CONFLICT (component_id) DO NOTHING;
INSERT INTO components (component_id, category_name, subcategory_name, name, display_name, description, region, climate_zone, spectrum_position, sort_order, base_cost_per_sqft_inr, installation_cost_per_sqft_inr, cost_confidence, cost_last_updated, cost_source_notes, expected_lifespan_years, replacement_cost_factor, major_maintenance_cycle_years, major_maintenance_cost_factor, annual_minor_maint_factor, maintenance_complexity, lifecycle_source_notes, thermal_resistance_score, acoustic_score, durability_score, moisture_resistance, fire_rating, energy_impact_modifier, accessibility_score, thermal_source_notes, max_floors_supported, min_floors_required, max_span_supported_m, incompatible_with, compatible_with, requires_component, climate_restrictions, hard_block_rule, advisory_rule, advisory_message, advisory_severity, constraint_source_notes, ai_advisory_notes, pros, cons, tooltip_detail, status, verify_flags, data_filled_by) VALUES ('DPC-003', 'Structure', 'Damp Proof Course', 'dpc_polymer_membrane', 'Polymer-Modified Membrane DPC', 'High-performance DPC using polymer-modified bitumen membrane (torch-applied or self-adhesive) at plinth level. Best moisture resistance available. Recommended for flood-prone plots, waterlogged sites, and premium construction.', 'South India', 'Warm-Humid|Hot-Dry|Temperate|Composite', 'Premium', 3, 18, 8, 'Medium', '2024-Q1', 'STP/Fosroc/Pidilite polymer DPC membrane rates South India 2024; torch-applied; normalized per sqft of wall length', 40, 0.5, 40, 0.5, 0, 'Low', 'Polymer membrane DPC manufacturer warranty 15-25 years; practical lifespan 35-50 years embedded', 5, 5, 9, 'Very High', 'Class B', 0, 10, 'No significant thermal contribution.', 20, 1, 'N/A', 'None', 'All wall systems|All foundation types|Basement construction', 'IS 16210 compliant polymer modified bitumen membrane|Torch or heat gun for application|Primer coat on concrete surface|Trained waterproofing applicator', 'Essential for flood-prone plots. Best choice for plots adjacent to lakes or rivers or in low-lying areas.', 'None', 'Trained applicator required - torch-applied membrane needs certified installer', 'Torch-applied polymer membranes require a trained and experienced installer. Incorrect torch application causes membrane burning or inadequate bonding. Use a manufacturer-certified applicator.', 'Warning', 'IS 16210; manufacturer installation guidelines', 'Polymer modified membranes are the premium choice for DPC and for any plot that has even a moderate flood or waterlogging risk they are worth every rupee. The torch-applied APP or SBS membranes from brands like STP Fosroc or Pidilite create a seamless monolithic barrier that is genuinely impermeable and has flexibility to handle minor structural movement without cracking. The critical requirement is a trained applicator - this is not something an ordinary mason can do. The torch application temperature must be correct and the membrane must be fully bonded with no air bubbles or the moisture will find the void. For premium construction or any plot in a low-lying area I specify polymer membrane DPC automatically. The extra cost over cement mortar DPC is recovered in the first monsoon when your neighbours have rising damp and you do not.', 'Best moisture resistance available|40-year lifespan|Essential for flood-prone plots|Handles minor structural movement without cracking|Seamless application', 'Highest DPC cost|Requires trained torch applicator|Cannot be done by ordinary mason|Primer coat required before application', 'Polymer membrane DPC. Best protection available. Torch-applied by certified installer. Essential for flood-prone or low-lying plots.', 'Active', 'None', 'AI') ON CONFLICT (component_id) DO NOTHING;
INSERT INTO components (component_id, category_name, subcategory_name, name, display_name, description, region, climate_zone, spectrum_position, sort_order, base_cost_per_sqft_inr, installation_cost_per_sqft_inr, cost_confidence, cost_last_updated, cost_source_notes, expected_lifespan_years, replacement_cost_factor, major_maintenance_cycle_years, major_maintenance_cost_factor, annual_minor_maint_factor, maintenance_complexity, lifecycle_source_notes, thermal_resistance_score, acoustic_score, durability_score, moisture_resistance, fire_rating, energy_impact_modifier, accessibility_score, thermal_source_notes, max_floors_supported, min_floors_required, max_span_supported_m, incompatible_with, compatible_with, requires_component, climate_restrictions, hard_block_rule, advisory_rule, advisory_message, advisory_severity, constraint_source_notes, ai_advisory_notes, pros, cons, tooltip_detail, status, verify_flags, data_filled_by) VALUES ('PLINTH-001', 'Structure', 'Plinth Height', 'plinth_450mm', '450 mm (1.5 ft)', 'Plinth height of 450mm above external ground level. Suitable for gently sloped or well-drained level plots with no flooding history. Minimum typically allowed by most South India municipal codes.', 'South India', 'Warm-Humid|Hot-Dry|Temperate|Composite', 'Basic', 1, 8, 5, 'High', '2024-Q1', 'Karnataka PWD SOR 2024-25 filling and masonry rates; normalized per sqft of footprint', 60, 0, 0, 0, 0, 'Low', 'Permanent structural element - no replacement cycle', 5, 5, 6, 'Low', 'Class A', 0, 10, 'No thermal contribution.', 20, 1, 'N/A', 'None', 'All structural systems', 'None', 'Not recommended for high rainfall zones above 1500mm annual precipitation or low-lying areas.', 'None', 'Verify no flooding history in last 20 years before accepting 450mm plinth', '450mm plinth is only safe if the plot has confirmed good drainage and no flooding history. Check with neighbours and local records about waterlogging during heavy monsoon events.', 'Warning', 'NBC 2016; Local municipal building regulations', 'Four fifty millimetres is the bare minimum I would accept for a plinth and only in very specific conditions - a plot with excellent drainage on gently sloping terrain in a city like Bangalore where the surrounding streets are well above the finished road level. In most South India contexts this height is too low. The problem is not the average monsoon but the extreme monsoon - in 2022 and 2015 Bangalore had rainfall events that flooded areas that had never flooded before and houses with 450mm plinths took water in while 600mm plinths were safe. Before accepting this height walk around your plot during heavy rain and check the drainage direction and ask your neighbours about the worst flooding they have seen.', 'Lowest construction cost|Easiest access - fewer steps|Minimises filling material quantity', 'Vulnerable to even moderate flooding|Not suitable for low-lying or high-rainfall areas|Difficult to raise later without major work', '450mm plinth - minimum height. Only for well-drained level plots with confirmed no flooding history.', 'Active', 'None', 'AI') ON CONFLICT (component_id) DO NOTHING;
INSERT INTO components (component_id, category_name, subcategory_name, name, display_name, description, region, climate_zone, spectrum_position, sort_order, base_cost_per_sqft_inr, installation_cost_per_sqft_inr, cost_confidence, cost_last_updated, cost_source_notes, expected_lifespan_years, replacement_cost_factor, major_maintenance_cycle_years, major_maintenance_cost_factor, annual_minor_maint_factor, maintenance_complexity, lifecycle_source_notes, thermal_resistance_score, acoustic_score, durability_score, moisture_resistance, fire_rating, energy_impact_modifier, accessibility_score, thermal_source_notes, max_floors_supported, min_floors_required, max_span_supported_m, incompatible_with, compatible_with, requires_component, climate_restrictions, hard_block_rule, advisory_rule, advisory_message, advisory_severity, constraint_source_notes, ai_advisory_notes, pros, cons, tooltip_detail, status, verify_flags, data_filled_by) VALUES ('PLINTH-002', 'Structure', 'Plinth Height', 'plinth_600mm', '600 mm (2 ft)', 'Standard plinth height of 600mm above external ground level. Most common specification across Karnataka and Tamil Nadu for residential construction. Provides adequate protection against normal monsoon runoff and minor surface flooding.', 'South India', 'Warm-Humid|Hot-Dry|Temperate|Composite', 'Intermediate', 2, 12, 7, 'High', '2024-Q1', 'Karnataka PWD SOR 2024-25; standard residential specification; normalized per sqft', 60, 0, 0, 0, 0, 'Low', 'Permanent structural element - no replacement cycle', 5, 5, 7, 'Medium', 'Class A', 0, 9, 'No thermal contribution.', 20, 1, 'N/A', 'None', 'All structural systems', 'None', 'Consider 750mm for high-rainfall zones above 2000mm annual precipitation.', 'None', 'None', '', '', 'NBC 2016; BBMP/TNPCB building bylaws', 'Six hundred millimetres is the standard I specify for most residential plots in Bangalore Chennai and Hyderabad and it is the right default choice for any plot in a normal residential layout with good surrounding infrastructure. Two feet of clearance above external ground provides good protection against the sheet flow you get during a heavy monsoon hour. The vastu consideration is real - traditional Indian architecture always raised the plinth to symbolically separate the sacred interior from the external ground and practically to keep out insects and moisture. From a purely practical standpoint the 600mm plinth also gives you a useful visual base to the building and allows the DPC to function properly. The only reason to go lower is site access for elderly residents.', 'Standard height for most South India conditions|Good monsoon protection|Acceptable by most municipal codes|Wide contractor familiarity', 'Insufficient for flood-prone or low-lying plots|Creates access step for elderly/wheelchair users|More filling material than 450mm', '600mm standard plinth. Best default for most South India plots. Upgrade to 750mm for high rainfall or low-lying areas.', 'Active', 'None', 'AI') ON CONFLICT (component_id) DO NOTHING;
INSERT INTO components (component_id, category_name, subcategory_name, name, display_name, description, region, climate_zone, spectrum_position, sort_order, base_cost_per_sqft_inr, installation_cost_per_sqft_inr, cost_confidence, cost_last_updated, cost_source_notes, expected_lifespan_years, replacement_cost_factor, major_maintenance_cycle_years, major_maintenance_cost_factor, annual_minor_maint_factor, maintenance_complexity, lifecycle_source_notes, thermal_resistance_score, acoustic_score, durability_score, moisture_resistance, fire_rating, energy_impact_modifier, accessibility_score, thermal_source_notes, max_floors_supported, min_floors_required, max_span_supported_m, incompatible_with, compatible_with, requires_component, climate_restrictions, hard_block_rule, advisory_rule, advisory_message, advisory_severity, constraint_source_notes, ai_advisory_notes, pros, cons, tooltip_detail, status, verify_flags, data_filled_by) VALUES ('PLINTH-003', 'Structure', 'Plinth Height', 'plinth_750mm', '750 mm (2.5 ft)', 'Elevated plinth of 750mm above external ground level. Recommended for flood-prone areas, low-lying plots, and zones with annual rainfall above 2000mm. Also specified for plots adjacent to water bodies or in areas with poor municipal drainage.', 'South India', 'Warm-Humid|Hot-Dry|Temperate|Composite', 'Performance', 3, 16, 9, 'High', '2024-Q1', 'Karnataka PWD SOR 2024-25; elevated plinth filling and masonry; normalized per sqft', 60, 0, 0, 0, 0, 'Low', 'Permanent structural element - no replacement cycle', 5, 5, 8, 'High', 'Class A', 0, 8, 'No thermal contribution.', 20, 1, 'N/A', 'None', 'All structural systems', 'Well-compacted filling material|Steps or ramp for access', 'Recommended for plots in Kerala, coastal Karnataka and coastal Tamil Nadu where annual rainfall exceeds 2000mm.', 'None', 'Provide steps or access ramp - 750mm requires at least 3 steps at entry', 'At 750mm plinth height, at least 3 steps are required at entry points. Design adequate landing areas for safety and consider a ramp for elderly residents.', 'Warning', 'NBC 2016; IS 3764 accessibility', 'Seven fifty millimetres is my recommendation for any plot that shows even a hint of flooding risk or is in a high-rainfall coastal zone. The extra 150mm over the standard 600mm costs very little in absolute terms - maybe Rs 4-5 per sqft of footprint more - but gives you meaningful additional protection against that once-in-ten-years extreme rainfall event. I specifically recommend this for plots in Mangalore Udupi Kochi and the Kerala coast where heavy rain events routinely put 400-500mm of rain down in 24 hours and urban drainage systems cannot handle it. The access steps are a real consideration - three steps at 250mm each means you need a proper landing design. Include a ramp for elderly household members.', 'Good protection against moderate flooding events|Recommended for coastal and high-rainfall zones|Better vastu compliance - elevated dignified entry|Reduces termite and insect access', 'Requires 3+ entry steps - access challenge for elderly|More filling material and cost than 600mm|Taller compound wall needed at boundary', '750mm elevated plinth. Recommended for coastal, high-rainfall zones and low-lying plots. Plan 3 access steps and ramp for elderly.', 'Active', 'None', 'AI') ON CONFLICT (component_id) DO NOTHING;
INSERT INTO components (component_id, category_name, subcategory_name, name, display_name, description, region, climate_zone, spectrum_position, sort_order, base_cost_per_sqft_inr, installation_cost_per_sqft_inr, cost_confidence, cost_last_updated, cost_source_notes, expected_lifespan_years, replacement_cost_factor, major_maintenance_cycle_years, major_maintenance_cost_factor, annual_minor_maint_factor, maintenance_complexity, lifecycle_source_notes, thermal_resistance_score, acoustic_score, durability_score, moisture_resistance, fire_rating, energy_impact_modifier, accessibility_score, thermal_source_notes, max_floors_supported, min_floors_required, max_span_supported_m, incompatible_with, compatible_with, requires_component, climate_restrictions, hard_block_rule, advisory_rule, advisory_message, advisory_severity, constraint_source_notes, ai_advisory_notes, pros, cons, tooltip_detail, status, verify_flags, data_filled_by) VALUES ('PLINTH-004', 'Structure', 'Plinth Height', 'plinth_900mm', '900 mm (3 ft)', 'High plinth of 900mm above external ground level. Required for heavily flood-prone plots, low-lying land near lakes or rivers, or areas with documented extreme flooding history. Maximum practical plinth height for residential construction.', 'South India', 'Warm-Humid|Temperate', 'Premium', 4, 22, 12, 'Medium', '2024-Q1', 'Karnataka PWD SOR 2024-25; high plinth filling and masonry; normalized per sqft', 60, 0, 0, 0, 0, 'Low', 'Permanent structural element - no replacement cycle', 5, 5, 9, 'Very High', 'Class A', 0, 6, 'No thermal contribution.', 20, 1, 'N/A', 'None', 'All structural systems', 'Well-compacted filling in 150mm lifts with plate compaction|Steps minimum 4|Ramp for wheelchair or elderly access', 'Primarily relevant for high-rainfall coastal zones and flood-prone areas.', 'None', 'Mandatory ramp or step with handrail at all entry points for 900mm plinth', 'At 900mm (3 feet) a minimum of 4 steps are required. A proper handrail and preferably a ramp are mandatory for safety and elderly access. Design this into the site plan.', 'Strong-Warning', 'NBC 2016; IS 3764', 'Nine hundred millimetres is the maximum practical plinth height for residential construction and I specify it only when the flooding risk is clearly documented and severe - plots adjacent to Bangalore lakes that overflowed in the 2022 floods plots near Chennai rivers in the Adyar basin or low-lying Kerala coastal plots with historical inundation. The practical challenge is access - four steps at 225mm is a significant climb and you absolutely must design a ramp for any elderly household member or future mobility needs. The compaction of filling material at this height is critical - if you fill loosely to 900mm and do not compact in 150mm lifts with a plate compactor the filling will settle over the first two monsoons and you will have a floor that slopes toward the walls causing serious dampness issues.', 'Maximum flood protection for high-risk sites|Essential for documented flood-prone plots|Reduces all ground-borne moisture and pest risk', 'Highest cost and filling material|Mandatory ramp for elderly access|Significant access steps|Compaction quality critical to prevent settlement', '900mm maximum residential plinth. Only for documented flood-prone plots. Mandatory ramp for elderly. Compaction in 150mm lifts essential.', 'Active', 'None', 'AI') ON CONFLICT (component_id) DO NOTHING;
INSERT INTO components (component_id, category_name, subcategory_name, name, display_name, description, region, climate_zone, spectrum_position, sort_order, base_cost_per_sqft_inr, installation_cost_per_sqft_inr, cost_confidence, cost_last_updated, cost_source_notes, expected_lifespan_years, replacement_cost_factor, major_maintenance_cycle_years, major_maintenance_cost_factor, annual_minor_maint_factor, maintenance_complexity, lifecycle_source_notes, thermal_resistance_score, acoustic_score, durability_score, moisture_resistance, fire_rating, energy_impact_modifier, accessibility_score, thermal_source_notes, max_floors_supported, min_floors_required, max_span_supported_m, incompatible_with, compatible_with, requires_component, climate_restrictions, hard_block_rule, advisory_rule, advisory_message, advisory_severity, constraint_source_notes, ai_advisory_notes, pros, cons, tooltip_detail, status, verify_flags, data_filled_by) VALUES ('PFILL-001', 'Structure', 'Plinth Filling', 'plinth_fill_murrum', 'Murrum / Laterite Filling', 'Plinth filling using locally sourced murrum (decomposed rock) or laterite material. Available across Karnataka, Tamil Nadu and parts of Andhra Pradesh. Good compaction characteristics, economical, and widely used for residential plinth filling.', 'South India', 'Warm-Humid|Hot-Dry|Temperate|Composite', 'Basic', 1, 4, 3, 'High', '2024-Q1', 'Local murrum supply South India 2024; transport within 30km; compaction labor; normalized per sqft of plinth area', 60, 0, 0, 0, 0, 'Low', 'Permanent fill - no replacement cycle if properly compacted', 5, 5, 7, 'Medium', 'Non-Rated', 0, 10, 'No thermal contribution.', 20, 1, 'N/A', 'None', 'All foundation and plinth systems', 'Plate compactor|Water for compaction moisture|Compaction test every 300mm lift', 'In waterlogged areas murrum can become soft when saturated - consider quarry dust or sand for better drainage.', 'None', 'Compact in 150mm layers with plate compactor - not by hand tamping alone', 'Plinth filling must be compacted in maximum 150mm layers using a plate compactor. Hand tamping alone does not achieve adequate compaction and leads to floor settlement.', 'Strong-Warning', 'IS 1892; NBC 2016 Part 6', 'Murrum filling is the right choice for most Karnataka projects because it is the natural decomposed rock material from the same laterite geology and it compacts extremely well when wet. The key word is compaction - I have seen more floor settlement and cracking from badly compacted plinth filling than from any other cause. The fill must go in at maximum 150mm layers and each layer must be compacted with a plate compactor and wetted to optimum moisture content. I always insist on a field density test at every 300mm of fill height before moving to the next layer. The contractor who says plate compaction is not needed and hand tamping is fine is cutting corners - do not accept it. The cost of a plate compactor rental is trivial compared to the cost of relaying a settled floor.', 'Most economical filling material|Locally available across South India|Good compaction characteristics|Adequate for most residential plinth filling', 'Can become soft when waterlogged|Requires proper compaction in layers|Transport cost if site far from source|Not ideal for poorly drained sites', 'Murrum/laterite plinth filling. Economical and widely available. Compact in 150mm lifts with plate compactor - critical to prevent settlement.', 'Active', 'None', 'AI') ON CONFLICT (component_id) DO NOTHING;
INSERT INTO components (component_id, category_name, subcategory_name, name, display_name, description, region, climate_zone, spectrum_position, sort_order, base_cost_per_sqft_inr, installation_cost_per_sqft_inr, cost_confidence, cost_last_updated, cost_source_notes, expected_lifespan_years, replacement_cost_factor, major_maintenance_cycle_years, major_maintenance_cost_factor, annual_minor_maint_factor, maintenance_complexity, lifecycle_source_notes, thermal_resistance_score, acoustic_score, durability_score, moisture_resistance, fire_rating, energy_impact_modifier, accessibility_score, thermal_source_notes, max_floors_supported, min_floors_required, max_span_supported_m, incompatible_with, compatible_with, requires_component, climate_restrictions, hard_block_rule, advisory_rule, advisory_message, advisory_severity, constraint_source_notes, ai_advisory_notes, pros, cons, tooltip_detail, status, verify_flags, data_filled_by) VALUES ('PFILL-002', 'Structure', 'Plinth Filling', 'plinth_fill_river_sand', 'River Sand Filling', 'Plinth filling using clean river sand (or M-sand). Easier to compact than murrum, drains well, and provides a stable base. Higher cost than murrum due to transport and scarcity. Good choice for areas where good murrum is not locally available.', 'South India', 'Warm-Humid|Hot-Dry|Temperate|Composite', 'Intermediate', 2, 7, 4, 'Medium', '2024-Q1', 'River sand market rate South India 2024 (scarcity premium); M-sand alternative rate; normalized per sqft', 60, 0, 0, 0, 0, 'Low', 'Permanent fill - no replacement cycle if properly compacted', 5, 5, 7, 'High', 'Non-Rated', 0, 10, 'No thermal contribution.', 20, 1, 'N/A', 'None', 'All foundation and plinth systems', 'Plate compactor|Clean sand free of organic material|Moisture control during compaction', 'Sand filling settles faster in high-rainfall zones if not well compacted.', 'None', 'Use clean washed sand - organic or silty sand compacts poorly and causes settlement', 'River sand filling must be clean and free of organic material or silt. Test by squeezing a wet handful - if it leaves mud stains it has too much clay/silt and will settle.', 'Warning', 'IS 1892; Karnataka Sand Mining Policy', 'River sand filling is more expensive than murrum because of the ongoing sand scarcity in Karnataka and Tamil Nadu due to mining restrictions. In areas where murrum is not available it is a good second choice because sand compacts well and drains better than clay-heavy murrum. The important caveat is the sand quality - Karnataka has a significant market for inferior silty sand that passes as river sand but has too much clay content. Squeeze a wet handful tightly and look at the residue on your palm - genuine clean river sand leaves almost no stain whereas silty sand leaves a muddy deposit. Clean manufactured sand (M-sand) from a reputable plant is actually a better and more consistent alternative to river sand for plinth filling and I often prefer it. Compact in 150mm layers with the plate compactor as with murrum.', 'Good drainage characteristics|Easy to compact|Better drainage than murrum in waterlogged areas|M-sand substitute widely available', 'Higher cost than murrum due to scarcity|Quality variable - silt content must be checked|Environmental concern with river sand extraction|Requires clean material free of organics', 'River sand plinth filling. Check quality - reject silty sand. M-sand is a good alternative. Compact in 150mm lifts.', 'Active', 'None', 'AI') ON CONFLICT (component_id) DO NOTHING;
INSERT INTO components (component_id, category_name, subcategory_name, name, display_name, description, region, climate_zone, spectrum_position, sort_order, base_cost_per_sqft_inr, installation_cost_per_sqft_inr, cost_confidence, cost_last_updated, cost_source_notes, expected_lifespan_years, replacement_cost_factor, major_maintenance_cycle_years, major_maintenance_cost_factor, annual_minor_maint_factor, maintenance_complexity, lifecycle_source_notes, thermal_resistance_score, acoustic_score, durability_score, moisture_resistance, fire_rating, energy_impact_modifier, accessibility_score, thermal_source_notes, max_floors_supported, min_floors_required, max_span_supported_m, incompatible_with, compatible_with, requires_component, climate_restrictions, hard_block_rule, advisory_rule, advisory_message, advisory_severity, constraint_source_notes, ai_advisory_notes, pros, cons, tooltip_detail, status, verify_flags, data_filled_by) VALUES ('PFILL-003', 'Structure', 'Plinth Filling', 'plinth_fill_quarry_dust', 'Quarry Dust (M-Sand) Filling', 'Plinth filling using quarry dust or manufactured sand (M-sand) from stone crushing. Widely available in Karnataka and Tamil Nadu from stone quarries. Good drainage, controlled gradation, and consistent quality. Increasingly preferred over river sand due to availability and cost.', 'South India', 'Warm-Humid|Hot-Dry|Temperate|Composite', 'Performance', 3, 6, 4, 'High', '2024-Q1', 'Quarry dust market rate Karnataka/Tamil Nadu 2024; widely available near stone quarries; normalized per sqft', 60, 0, 0, 0, 0, 'Low', 'Permanent fill - no replacement cycle if properly compacted', 5, 5, 8, 'High', 'Non-Rated', 0, 10, 'No thermal contribution.', 20, 1, 'N/A', 'None', 'All foundation and plinth systems', 'Plate compactor|Water for compaction|IS 383 compliant M-sand from certified plant', 'None', 'None', 'Source from IS 383 certified plant - not all quarry dust has consistent gradation', 'Quarry dust gradation varies significantly between suppliers. Source from a plant certified to IS 383 for consistent particle size. Poorly graded quarry dust with too many fines can compact poorly.', 'Warning', 'IS 1892; IS 383 M-sand specification', 'Quarry dust and manufactured M-sand have become my preferred plinth filling material for Karnataka projects because the supply is consistent independent of monsoon-linked river sand availability and the government has been regulating river sand mining heavily. A good IS 383 certified M-sand from a reputable plant has controlled gradation which means it compacts predictably and drains well. The downside is that not all quarry dust operations are equal - some produce dust with too many fine particles that behave more like silt and compact poorly. Always ask for the IS 383 certificate from the M-sand plant. The compaction procedure is the same as for murrum - 150mm layers, plate compactor, optimum moisture. The cost is typically between murrum and river sand making it an excellent middle ground.', 'Widely available across Karnataka and Tamil Nadu|Consistent quality from certified plants|Good drainage|No environmental mining restrictions|Good compaction characteristics', 'Quality varies between suppliers - IS 383 certification needed|Dust can be a nuisance on site|Some fine particle content can affect compaction if poorly graded', 'Quarry dust/M-sand filling. Best availability in Karnataka. Source from IS 383 certified plant. Compact in 150mm lifts.', 'Active', 'None', 'AI') ON CONFLICT (component_id) DO NOTHING;
INSERT INTO components (component_id, category_name, subcategory_name, name, display_name, description, region, climate_zone, spectrum_position, sort_order, base_cost_per_sqft_inr, installation_cost_per_sqft_inr, cost_confidence, cost_last_updated, cost_source_notes, expected_lifespan_years, replacement_cost_factor, major_maintenance_cycle_years, major_maintenance_cost_factor, annual_minor_maint_factor, maintenance_complexity, lifecycle_source_notes, thermal_resistance_score, acoustic_score, durability_score, moisture_resistance, fire_rating, energy_impact_modifier, accessibility_score, thermal_source_notes, max_floors_supported, min_floors_required, max_span_supported_m, incompatible_with, compatible_with, requires_component, climate_restrictions, hard_block_rule, advisory_rule, advisory_message, advisory_severity, constraint_source_notes, ai_advisory_notes, pros, cons, tooltip_detail, status, verify_flags, data_filled_by) VALUES ('UWT-001', 'Systems', 'Underground Water Tank', 'no_underground_tank', 'No Underground Sump', 'No underground water storage sump. Relies entirely on municipal water supply or overhead tank fed directly from direct supply. Only viable if municipal supply is continuous, reliable and of adequate pressure throughout the day.', 'South India', 'Warm-Humid|Hot-Dry|Temperate|Composite', 'Basic', 1, 0, 0, 'High', '2024-Q1', 'No capital cost', 0, 0, 0, 0, 0, 'Low', 'No sump - no lifecycle', 5, 5, 5, 'Medium', 'Non-Rated', 0, 10, 'No thermal contribution.', 20, 1, 'N/A', 'None', 'All structural systems', 'Reliable continuous municipal water supply|Direct supply pressure adequate for overhead tank fill', 'Not recommended anywhere in South India outside premium gated communities with assured 24/7 supply.', 'None', 'Not recommended unless municipal supply is confirmed as 24/7 continuous and reliable', 'No underground sump is a significant risk in most South India cities. BBMP supplies water for 30-45 minutes twice daily in most areas. Without a sump there is no buffer for supply interruptions or tanker water.', 'Strong-Warning', 'BWSSB/CMWSSB/HMWSSB supply data', 'I have never recommended building without an underground sump in any South India location outside a very small number of premium gated communities that have their own borewell and treatment plant with 24-hour supply. In the real world BBMP supplies water for 30-45 minutes twice a day on average and many areas of Bangalore get water on alternate days. Without a sump there is simply no storage buffer. When supply comes you need to be able to capture it all. When supply fails you need reserves. A house without a sump is completely dependent on water tankers when supply is disrupted and tanker water in Bangalore costs Rs 800-1200 per load. The sump is non-negotiable infrastructure for 95 percent of South India plots.', 'Zero upfront cost|No space consumption below ground', 'Not viable in 95% of South India locations|No buffer for supply interruption|Cannot store tanker water|Completely dependent on continuous municipal supply', 'No sump. Only viable with confirmed 24/7 continuous municipal supply. Not recommended for most South India plots.', 'Active', 'None', 'AI') ON CONFLICT (component_id) DO NOTHING;
INSERT INTO components (component_id, category_name, subcategory_name, name, display_name, description, region, climate_zone, spectrum_position, sort_order, base_cost_per_sqft_inr, installation_cost_per_sqft_inr, cost_confidence, cost_last_updated, cost_source_notes, expected_lifespan_years, replacement_cost_factor, major_maintenance_cycle_years, major_maintenance_cost_factor, annual_minor_maint_factor, maintenance_complexity, lifecycle_source_notes, thermal_resistance_score, acoustic_score, durability_score, moisture_resistance, fire_rating, energy_impact_modifier, accessibility_score, thermal_source_notes, max_floors_supported, min_floors_required, max_span_supported_m, incompatible_with, compatible_with, requires_component, climate_restrictions, hard_block_rule, advisory_rule, advisory_message, advisory_severity, constraint_source_notes, ai_advisory_notes, pros, cons, tooltip_detail, status, verify_flags, data_filled_by) VALUES ('UWT-002', 'Systems', 'Underground Water Tank', 'sump_plastic_sintex', 'Pre-Moulded Plastic Sump (Sintex)', 'Factory-manufactured polyethylene or FRP underground water tank. Sintex and similar brands offer 2000-10000 litre capacity below-ground tanks. Quick installation, low cost, but shorter lifespan than RCC. Good for smaller plots or budget-constrained construction.', 'South India', 'Warm-Humid|Hot-Dry|Temperate|Composite', 'Intermediate', 2, 5, 3, 'High', '2024-Q1', 'Sintex/Penguin underground sump market rate 2024; 5000L standard residential; normalized per sqft', 15, 0.7, 5, 0.1, 0.005, 'Low', 'Sintex underground tank rated lifespan 15 years; UV and pressure degradation', 5, 5, 5, 'High', 'Non-Rated', 0, 10, 'No thermal contribution.', 20, 1, 'N/A', 'None', 'All structural systems', 'Excavation to tank dimensions|Sand bedding below tank|Concrete collar around top|Pump and motor', 'In high water table areas the empty plastic tank can float upward. Ensure concrete collar anchoring.', 'None', 'Concrete collar anchoring mandatory in high water table plots to prevent flotation', 'An empty plastic sump in a high water table area can float upward displacing the ground above. A reinforced concrete collar anchoring the tank is mandatory in such locations.', 'Warning', 'Sintex installation guidelines; IS 12592', 'The plastic Sintex-style sump is the quick economical solution and it works fine for plots where budget is tight and long-term planning is flexible. The honest limitation is lifespan - the polyethylene material degrades with UV exposure at the exposed top and the tank walls can deform under soil pressure over 10-15 years. I see significant deformation in Sintex underground sumps older than 12 years particularly in sandy soils where the tank has more freedom to move. For a house you plan to live in for 20-30 years I recommend the RCC sump as the first choice. But for a rental property or a budget build where a sump replacement in 15 years is acceptable the plastic sump is a valid choice and the installation is straightforward taking one or two days versus a week for RCC.', 'Low cost|Fast installation - 1-2 days|Factory manufactured - no quality variation|Easy to clean through manhole|Good for budget construction', '15-year lifespan - replacement needed|Can deform under soil pressure|Risk of flotation in high water table|Cannot be expanded later|Less volume per cost than RCC', 'Plastic Sintex sump. 15-year lifespan. Anchor with concrete collar in high water table areas. Good budget option.', 'Active', 'None', 'AI') ON CONFLICT (component_id) DO NOTHING;
INSERT INTO components (component_id, category_name, subcategory_name, name, display_name, description, region, climate_zone, spectrum_position, sort_order, base_cost_per_sqft_inr, installation_cost_per_sqft_inr, cost_confidence, cost_last_updated, cost_source_notes, expected_lifespan_years, replacement_cost_factor, major_maintenance_cycle_years, major_maintenance_cost_factor, annual_minor_maint_factor, maintenance_complexity, lifecycle_source_notes, thermal_resistance_score, acoustic_score, durability_score, moisture_resistance, fire_rating, energy_impact_modifier, accessibility_score, thermal_source_notes, max_floors_supported, min_floors_required, max_span_supported_m, incompatible_with, compatible_with, requires_component, climate_restrictions, hard_block_rule, advisory_rule, advisory_message, advisory_severity, constraint_source_notes, ai_advisory_notes, pros, cons, tooltip_detail, status, verify_flags, data_filled_by) VALUES ('UWT-003', 'Systems', 'Underground Water Tank', 'sump_ferro_cement', 'Ferro-Cement Sump', 'Underground water sump constructed using ferro-cement technology (thin cement mortar over wire mesh layers). Lighter than RCC, faster construction, and moderate cost. Lifespan of 20-30 years. Common in Kerala and Tamil Nadu.', 'South India', 'Warm-Humid|Hot-Dry|Temperate|Composite', 'Performance', 3, 10, 6, 'Medium', '2024-Q1', 'Ferro-cement sump contractor rates Tamil Nadu/Kerala 2024; normalized per sqft', 25, 0.6, 10, 0.15, 0.005, 'Medium', 'ACI 549; ferro-cement water tank performance data; 20-30 year typical lifespan', 5, 5, 7, 'High', 'Non-Rated', 0, 10, 'No thermal contribution.', 20, 1, 'N/A', 'None', 'All structural systems', 'Galvanised wire mesh layers|Cement mortar with waterproofing admixture|Skilled ferro-cement mason|Bitumen coating on exterior|Pump and motor', 'In high water table areas additional exterior waterproofing critical to prevent seepage into tank.', 'None', 'Bitumen exterior coating mandatory to prevent groundwater contamination of stored water', 'Ferro-cement sump exterior must be coated with bitumen or cementitious waterproofing. Without this groundwater can seep through the thin shell contaminating stored drinking water.', 'Warning', 'ACI 549; IS 6509 ferro-cement practice', 'Ferro-cement sumps are popular in Tamil Nadu and Kerala because there is a tradition of skilled ferro-cement workers there who can produce a good quality tank at lower cost than RCC. The technology is sound - the thin cement mortar over multiple layers of wire mesh produces a strong waterproof shell. The main vulnerability is the exterior - the thin shell needs good bitumen coating on the outside to prevent groundwater from seeping in through the porous mortar and contaminating the stored water. The quality is very dependent on the skill of the mason particularly in the mortar application consistency. If you can find a good experienced ferro-cement mason and you are on a moderate budget this is a better choice than the Sintex plastic tank for longevity.', 'Better lifespan than plastic sump|Lighter than RCC - faster construction|Lower cost than RCC sump|Custom shapes possible|Good choice for Kerala/Tamil Nadu where skilled workers available', 'Skill-dependent quality|Exterior waterproofing mandatory|Shorter lifespan than RCC|Less available in Karnataka', 'Ferro-cement sump. 25-year lifespan. Exterior bitumen coating mandatory. Quality depends on mason skill.', 'Active', 'None', 'AI') ON CONFLICT (component_id) DO NOTHING;
INSERT INTO components (component_id, category_name, subcategory_name, name, display_name, description, region, climate_zone, spectrum_position, sort_order, base_cost_per_sqft_inr, installation_cost_per_sqft_inr, cost_confidence, cost_last_updated, cost_source_notes, expected_lifespan_years, replacement_cost_factor, major_maintenance_cycle_years, major_maintenance_cost_factor, annual_minor_maint_factor, maintenance_complexity, lifecycle_source_notes, thermal_resistance_score, acoustic_score, durability_score, moisture_resistance, fire_rating, energy_impact_modifier, accessibility_score, thermal_source_notes, max_floors_supported, min_floors_required, max_span_supported_m, incompatible_with, compatible_with, requires_component, climate_restrictions, hard_block_rule, advisory_rule, advisory_message, advisory_severity, constraint_source_notes, ai_advisory_notes, pros, cons, tooltip_detail, status, verify_flags, data_filled_by) VALUES ('UWT-004', 'Systems', 'Underground Water Tank', 'sump_rcc_insitu', 'RCC Sump (In-Situ Cast)', 'Underground water sump cast in-situ using M20/M25 reinforced cement concrete with waterproofing admixture. Highest durability, 40+ year lifespan. Standard premium specification for residential construction. Typically 5000-15000 litres capacity.', 'South India', 'Warm-Humid|Hot-Dry|Temperate|Composite', 'Premium', 4, 18, 12, 'High', '2024-Q1', 'RCC sump construction Bangalore/Chennai contractor rates 2024; M20 concrete + steel + waterproofing admixture; normalized per sqft', 45, 0.5, 15, 0.08, 0.005, 'Low', 'IS 3370 water-retaining structures; RCC sump lifespan data', 5, 5, 9, 'Very High', 'Non-Rated', 0, 10, 'No thermal contribution.', 20, 1, 'N/A', 'None', 'All structural systems', 'M20 or M25 concrete with waterproofing admixture (Fosroc/STP)|Fe500 steel reinforcement|Pump and motor|Manhole cover (CI)|Ventilation pipe', 'None', 'None', 'Waterproofing admixture mandatory in concrete mix - do not skip', 'RCC sump concrete must include a waterproofing admixture (Crystalline type - Krystol or Xypex preferred) in the mix. This is a water-retaining structure and ordinary RCC will develop hairline cracks that allow water to seep through the slab.', 'Warning', 'IS 3370; IS 456; waterproofing admixture manufacturer guidelines', 'The RCC sump is the first thing I specify and the last thing I am willing to compromise on for any house that the owner plans to live in. A properly built RCC sump with waterproofing admixture in the mix will outlast the house itself. The critical points are the waterproofing admixture - use a crystalline type like Krystol or Xypex added to the concrete mix not a surface coating - and the steel coverage. IS 3370 requires 40mm clear cover for water-retaining structures which is more than the 25mm used for normal structural work because the reinforcement in a sump is exposed to water on one side and soil on the other. I also always specify a CI manhole cover with lock and a ventilation pipe because an unventilated sump can develop anaerobic conditions. Get the sump built before the ground floor slab is cast because accessing the sump location after is very difficult.', '40+ year lifespan - outlasts the building|No risk of flotation or deformation|Can be built to any size|Highest water quality protection|Zero maintenance once correctly built', 'Highest cost|Takes 5-7 days to construct|Must be built before ground floor slab is cast|Requires waterproofing admixture and correct steel coverage', 'RCC sump. Best choice for 40+ year lifespan. Waterproofing admixture mandatory. Build before ground floor slab is cast.', 'Active', 'None', 'AI') ON CONFLICT (component_id) DO NOTHING;
INSERT INTO components (component_id, category_name, subcategory_name, name, display_name, description, region, climate_zone, spectrum_position, sort_order, base_cost_per_sqft_inr, installation_cost_per_sqft_inr, cost_confidence, cost_last_updated, cost_source_notes, expected_lifespan_years, replacement_cost_factor, major_maintenance_cycle_years, major_maintenance_cost_factor, annual_minor_maint_factor, maintenance_complexity, lifecycle_source_notes, thermal_resistance_score, acoustic_score, durability_score, moisture_resistance, fire_rating, energy_impact_modifier, accessibility_score, thermal_source_notes, max_floors_supported, min_floors_required, max_span_supported_m, incompatible_with, compatible_with, requires_component, climate_restrictions, hard_block_rule, advisory_rule, advisory_message, advisory_severity, constraint_source_notes, ai_advisory_notes, pros, cons, tooltip_detail, status, verify_flags, data_filled_by) VALUES ('WCFG-001', 'Envelope', 'Wall Configuration', 'wall_single_wythe', 'Single Wythe Wall', 'Standard single thickness wall construction. One layer of masonry units (brick, AAC, or block) bonded with mortar. The most common wall configuration in South India residential construction. Economical and adequate for inland locations with moderate thermal requirements.', 'South India', 'Warm-Humid|Hot-Dry|Temperate|Composite', 'Basic', 1, 0, 0, 'High', '2024-Q1', 'Configuration modifier - base cost in wall material selection', 50, 1, 20, 0.05, 0.005, 'Low', 'Wall configuration lifespan equals wall material lifespan', 4, 5, 7, 'Medium', 'Class A', -0.05, 10, 'Single masonry layer. Moderate thermal mass. Higher heat transmission than cavity configurations.', 6, 1, 'N/A', 'None', 'All masonry wall materials|RCC frame structures', 'Wall material (B2 selection)|Appropriate mortar (B4 selection)', 'Not recommended for coastal zones within 5km of sea without additional waterproofing.', 'None', 'None', '', '', 'NBC 2016; ECBC 2017', 'Single wythe is the standard for the vast majority of residential buildings across South India and it is the correct choice for most situations. The thermal performance depends almost entirely on the wall material chosen in B2 - an AAC block single wythe performs significantly better than a solid clay brick single wythe. Where single wythe walls become inadequate is in very hot coastal zones like Chennai south or Andhra coast where the combination of high temperatures and salt-laden humid air drives serious heat gain through thin walls. For those locations cavity or insulated configurations make a real difference. For typical Bangalore or Mysore residential construction single wythe is the right call.', 'Most economical configuration|Widest contractor familiarity|Standard for most South India conditions|Adequate thermal performance with modern wall materials', 'Lower thermal performance than cavity configurations|Not suitable for high-heat coastal zones|Less acoustic performance than cavity walls', 'Standard single wythe wall. Correct for most South India inland residential. Performance depends on wall material choice.', 'Active', 'None', 'AI') ON CONFLICT (component_id) DO NOTHING;
INSERT INTO components (component_id, category_name, subcategory_name, name, display_name, description, region, climate_zone, spectrum_position, sort_order, base_cost_per_sqft_inr, installation_cost_per_sqft_inr, cost_confidence, cost_last_updated, cost_source_notes, expected_lifespan_years, replacement_cost_factor, major_maintenance_cycle_years, major_maintenance_cost_factor, annual_minor_maint_factor, maintenance_complexity, lifecycle_source_notes, thermal_resistance_score, acoustic_score, durability_score, moisture_resistance, fire_rating, energy_impact_modifier, accessibility_score, thermal_source_notes, max_floors_supported, min_floors_required, max_span_supported_m, incompatible_with, compatible_with, requires_component, climate_restrictions, hard_block_rule, advisory_rule, advisory_message, advisory_severity, constraint_source_notes, ai_advisory_notes, pros, cons, tooltip_detail, status, verify_flags, data_filled_by) VALUES ('WCFG-002', 'Envelope', 'Wall Configuration', 'wall_cavity', 'Cavity Wall (Air Gap)', 'Double-leaf wall construction with an air gap (50-75mm) between two masonry wythes tied with wall ties. The trapped air significantly reduces heat transmission and provides a moisture break. Recommended for coastal zones, high-humidity regions, and premium thermal performance.', 'South India', 'Warm-Humid|Hot-Dry|Temperate|Composite', 'Performance', 2, 15, 8, 'Medium', '2024-Q1', 'Additional masonry and wall tie cost over single wythe; Karnataka PWD SOR 2024-25 reference; normalized per sqft', 50, 1, 20, 0.05, 0.005, 'Medium', 'Cavity wall lifespan equals wall material lifespan; cavity must remain clear', 7, 7, 8, 'High', 'Class A', 0.15, 10, 'Air cavity significantly reduces heat transmission. U-value reduction 25-35% vs single wythe. ECBC 2017.', 4, 1, 'N/A', 'None', 'Brick masonry|AAC block|RCC frame structures', 'Stainless steel or galvanised wall ties at 900mm centres|Cavity fill weep holes at base|Cavity clear of mortar droppings', 'Strongly recommended for coastal zones within 20km of sea. High value in Warm-Humid and Hot-Dry climates.', 'None', 'Cavity must be kept clean of mortar droppings during construction to maintain air gap function', 'The cavity air gap loses its thermal benefit if filled with mortar droppings during construction. A clean cavity board or cover must be used during each masonry course and removed to clean the cavity. Inspect cavity with endoscope before closing the wall.', 'Warning', 'NBC 2016; IS 1905; ECBC 2017', 'Cavity walls are standard practice in the UK and Singapore for good reasons and I strongly recommend them for any construction within 20 kilometres of the South India coast or in zones with high humidity and heat gain. The 50-75mm air gap reduces heat transmission through the wall by 25-35 percent compared to single wythe which translates directly into lower air conditioning loads. The other benefit in coastal areas is the moisture break - salt moisture that penetrates the outer leaf cannot cross the air gap to the inner leaf preventing efflorescence and spalling on internal surfaces. The contractor must use a clean cavity board at each course and pull it up clean to remove mortar droppings. If mortar droppings fill the cavity you get thermal bridging through the solid mortar path and the benefit is lost. This is not difficult to do properly but many contractors are not familiar with the technique and need supervision.', '25-35% reduction in heat gain vs single wythe|Moisture break for coastal areas|Better acoustic performance|Reduced AC loads over building life', 'Higher cost than single wythe|Thicker wall reduces internal floor area|Cavity must be kept clean during construction - supervision needed|Wall tie corrosion over time', 'Cavity wall with air gap. Best for coastal zones and high-humidity areas. Keep cavity clean of mortar droppings during construction.', 'Active', 'None', 'AI') ON CONFLICT (component_id) DO NOTHING;
INSERT INTO components (component_id, category_name, subcategory_name, name, display_name, description, region, climate_zone, spectrum_position, sort_order, base_cost_per_sqft_inr, installation_cost_per_sqft_inr, cost_confidence, cost_last_updated, cost_source_notes, expected_lifespan_years, replacement_cost_factor, major_maintenance_cycle_years, major_maintenance_cost_factor, annual_minor_maint_factor, maintenance_complexity, lifecycle_source_notes, thermal_resistance_score, acoustic_score, durability_score, moisture_resistance, fire_rating, energy_impact_modifier, accessibility_score, thermal_source_notes, max_floors_supported, min_floors_required, max_span_supported_m, incompatible_with, compatible_with, requires_component, climate_restrictions, hard_block_rule, advisory_rule, advisory_message, advisory_severity, constraint_source_notes, ai_advisory_notes, pros, cons, tooltip_detail, status, verify_flags, data_filled_by) VALUES ('WCFG-003', 'Envelope', 'Wall Configuration', 'wall_insulated_cavity', 'Insulated Cavity Wall', 'Cavity wall with the air gap partially or fully filled with rigid insulation board (EPS, XPS or Glasswool). Provides maximum thermal resistance. Premium configuration for passive cooling and energy-efficient construction targeting ECBC or IGBC compliance.', 'South India', 'Hot-Dry|Warm-Humid', 'Premium', 3, 28, 12, 'Medium', '2024-Q1', 'Cavity wall cost plus EPS/XPS board fill; Bangalore insulation contractor rates 2024; normalized per sqft', 40, 0.8, 25, 0.1, 0.005, 'Medium', 'Insulation material lifespan 25-40 years embedded in cavity; outer masonry lifespan 50 years', 9, 8, 8, 'High', 'Class B', 0.25, 10, 'Insulated cavity reduces wall U-value to ECBC compliant levels. 40-50% heat gain reduction vs single wythe.', 4, 1, 'N/A', 'None', 'Brick masonry|RCC frame structures|IGBC Green Homes compliance', 'EPS or XPS rigid insulation boards (50mm)|Stainless steel wall ties|Vapour barrier where required|Specialist insulation contractor', 'Highest value in Hot-Dry zones (Andhra, Telangana, interior Tamil Nadu). Good value in Warm-Humid coastal zones.', 'None', 'Use closed-cell insulation (XPS or EPS) not open-cell in humid climates', 'In Warm-Humid zones only use closed-cell insulation (XPS or EPS) in the cavity. Open-cell materials like Glasswool can absorb moisture in humid conditions reducing effectiveness and creating mould risk.', 'Warning', 'ECBC 2017; IS 3792; IS 4671', 'Insulated cavity walls are the specification I recommend for premium energy-efficient homes targeting IGBC Green Homes rating or ECBC compliance because they genuinely deliver passive cooling performance. The combination of the outer masonry thermal mass with the insulation core and the inner masonry leaf produces a wall assembly that keeps indoor temperatures significantly more stable through the day. In a hot-dry zone like Hyderabad or interior Tamil Nadu this can reduce air conditioning run hours by 15-20 percent annually. The installation requires care with the insulation board placement and vapour barrier depending on the climate zone. Use XPS or EPS boards in humid zones - never Glasswool in the cavity because it absorbs moisture and loses its insulating value. This configuration is most cost-effective for houses above 2500 sqft where the AC savings over the building life justify the premium.', 'Highest thermal performance - 40-50% heat gain reduction|ECBC and IGBC compliance pathway|Significant AC cost savings over building life|Best acoustic performance', 'Highest cost wall configuration|Thicker wall reduces floor area|Requires specialist installation|Insulation material replacement after 25-40 years|Fire rating slightly reduced', 'Insulated cavity wall. Premium thermal performance. Use XPS/EPS boards only in humid zones - not Glasswool. Best for IGBC/ECBC compliance.', 'Active', 'None', 'AI') ON CONFLICT (component_id) DO NOTHING;
INSERT INTO components (component_id, category_name, subcategory_name, name, display_name, description, region, climate_zone, spectrum_position, sort_order, base_cost_per_sqft_inr, installation_cost_per_sqft_inr, cost_confidence, cost_last_updated, cost_source_notes, expected_lifespan_years, replacement_cost_factor, major_maintenance_cycle_years, major_maintenance_cost_factor, annual_minor_maint_factor, maintenance_complexity, lifecycle_source_notes, thermal_resistance_score, acoustic_score, durability_score, moisture_resistance, fire_rating, energy_impact_modifier, accessibility_score, thermal_source_notes, max_floors_supported, min_floors_required, max_span_supported_m, incompatible_with, compatible_with, requires_component, climate_restrictions, hard_block_rule, advisory_rule, advisory_message, advisory_severity, constraint_source_notes, ai_advisory_notes, pros, cons, tooltip_detail, status, verify_flags, data_filled_by) VALUES ('MORT-001', 'Structure', 'Mortar Type', 'mortar_cement_1_6', 'Cement Mortar 1:6', 'Standard cement mortar in 1:6 ratio (1 part cement to 6 parts sand). Most common masonry mortar for residential construction. Adequate strength for non-load-bearing walls and general brick/block laying.', 'South India', 'Warm-Humid|Hot-Dry|Temperate|Composite', 'Basic', 1, 4, 3, 'High', '2024-Q1', 'Karnataka PWD SOR 2024-25 masonry mortar rates; normalized per sqft of wall area', 40, 0.3, 20, 0.1, 0.005, 'Low', 'IS 2250; mortar joint lifespan in protected masonry 30-50 years', 5, 5, 6, 'Medium', 'Class A', 0, 10, 'No significant thermal contribution beyond wall material.', 6, 1, 'N/A', 'AAC block walls (use thin-bed mortar instead)', 'Clay brick|Fly ash brick|Hollow concrete block|Stone masonry', 'OPC 43 or 53 cement|Clean river sand or M-sand|Water measured by ratio', 'In coastal zones add waterproofing admixture to mortar to reduce salt penetration.', 'None', 'Do not use 1:6 mortar for AAC blocks - use thin-bed mortar for AAC', 'AAC (Autoclaved Aerated Concrete) blocks require thin-bed mortar of 3-5mm thickness, not standard 1:6 cement mortar. Using thick mortar with AAC defeats the thermal advantage of the block.', 'Warning', 'IS 2250; IS 6452', 'Cement mortar 1:6 is the backbone of South India construction and most masons know how to prepare and use it correctly. The key quality control issue is the sand. River sand with excessive silt or clay weakens the mortar significantly - test by making a ball of wet sand and squeezing it: if it crumbles cleanly it is good quality, if it leaves mud it has too much clay. The other issue is water-cement ratio: adding extra water to make the mortar flow easily reduces strength. Mix it to a stiff consistency that holds its shape on the trowel. For AAC block walls you must switch to thin-bed adhesive mortar instead of this mix - the standard 1:6 mortar bed at 10-15mm thickness creates thermal bridges across the fine-cell AAC structure and eliminates most of the thermal benefit.', 'Most economical mortar|Widest contractor familiarity|Adequate for all common masonry units except AAC|Good workability', 'Not suitable for AAC blocks|Weaker than 1:4 mix|Quality depends on sand quality|Degrades faster in high-moisture conditions', 'Standard 1:6 mortar. Use for all masonry except AAC blocks. Sand quality critical - reject silty sand.', 'Active', 'None', 'AI') ON CONFLICT (component_id) DO NOTHING;
INSERT INTO components (component_id, category_name, subcategory_name, name, display_name, description, region, climate_zone, spectrum_position, sort_order, base_cost_per_sqft_inr, installation_cost_per_sqft_inr, cost_confidence, cost_last_updated, cost_source_notes, expected_lifespan_years, replacement_cost_factor, major_maintenance_cycle_years, major_maintenance_cost_factor, annual_minor_maint_factor, maintenance_complexity, lifecycle_source_notes, thermal_resistance_score, acoustic_score, durability_score, moisture_resistance, fire_rating, energy_impact_modifier, accessibility_score, thermal_source_notes, max_floors_supported, min_floors_required, max_span_supported_m, incompatible_with, compatible_with, requires_component, climate_restrictions, hard_block_rule, advisory_rule, advisory_message, advisory_severity, constraint_source_notes, ai_advisory_notes, pros, cons, tooltip_detail, status, verify_flags, data_filled_by) VALUES ('MORT-002', 'Structure', 'Mortar Type', 'mortar_cement_1_4', 'Cement Mortar 1:4 (Stronger Mix)', 'Stronger cement mortar in 1:4 ratio (1 part cement to 4 parts sand). Used for load-bearing walls, exposed locations, parapet walls, and areas subject to water or structural stress. Higher cement content improves strength and durability.', 'South India', 'Warm-Humid|Hot-Dry|Temperate|Composite', 'Intermediate', 2, 5, 3, 'High', '2024-Q1', 'Karnataka PWD SOR 2024-25 masonry rates; 1:4 mix cement premium; normalized per sqft', 50, 0.3, 25, 0.08, 0.003, 'Low', 'IS 2250; stronger mortar lifespan data', 5, 5, 7, 'Medium', 'Class A', 0, 10, 'No significant thermal contribution beyond wall material.', 6, 1, 'N/A', 'AAC block walls', 'Load-bearing brick masonry|Exposed parapet walls|Water tank masonry|Retaining walls', 'OPC 53 grade cement preferred|Clean sand|Measured water', 'Use in all coastal and high-rainfall areas for exterior wall courses.', 'None', 'None', '', '', 'IS 2250; IS 1905 load-bearing masonry', 'The 1:4 mortar is my specification for all load-bearing courses, parapet walls, and any masonry that is exposed to weathering or structural load. The additional cement content meaningfully improves compressive strength and reduces water permeability. At the site level the practical difference is visible - 1:4 mortar is stiffer and harder to work with which is why masons often try to use 1:6 everywhere to make their job easier. For load-bearing walls specify 1:4 and check that the contractor is actually making the correct ratio by watching the batching. A simple check is measuring the proportions by volume using a standard gauge box. The additional cost is trivial compared to the structural importance.', 'Higher strength for load-bearing applications|Better durability and moisture resistance than 1:6|Appropriate for exposed locations and parapet walls|Modest cost premium', 'Stiffer mix - slightly harder to work|Higher cement cost than 1:6|Not needed for non-load-bearing interior walls|Still not suitable for AAC blocks', '1:4 stronger mortar for load-bearing walls and exposed locations. Use OPC 53 cement. Check contractor is batching correctly.', 'Active', 'None', 'AI') ON CONFLICT (component_id) DO NOTHING;
INSERT INTO components (component_id, category_name, subcategory_name, name, display_name, description, region, climate_zone, spectrum_position, sort_order, base_cost_per_sqft_inr, installation_cost_per_sqft_inr, cost_confidence, cost_last_updated, cost_source_notes, expected_lifespan_years, replacement_cost_factor, major_maintenance_cycle_years, major_maintenance_cost_factor, annual_minor_maint_factor, maintenance_complexity, lifecycle_source_notes, thermal_resistance_score, acoustic_score, durability_score, moisture_resistance, fire_rating, energy_impact_modifier, accessibility_score, thermal_source_notes, max_floors_supported, min_floors_required, max_span_supported_m, incompatible_with, compatible_with, requires_component, climate_restrictions, hard_block_rule, advisory_rule, advisory_message, advisory_severity, constraint_source_notes, ai_advisory_notes, pros, cons, tooltip_detail, status, verify_flags, data_filled_by) VALUES ('MORT-003', 'Structure', 'Mortar Type', 'mortar_thin_bed_aac', 'Thin-Bed Mortar (for AAC Blocks)', 'Specialist thin-bed adhesive mortar for AAC (Autoclaved Aerated Concrete) block laying. Applied 3-5mm thick versus 10-15mm for standard mortar. Reduces thermal bridging across block joints, key to realising AAC thermal performance. Brands: Ytong Multipor, Weber, Ultratech.', 'South India', 'Warm-Humid|Hot-Dry|Temperate|Composite', 'Performance', 3, 9, 4, 'High', '2024-Q1', 'Ytong/Weber thin-bed mortar market rate South India 2024; normalized per sqft of AAC wall area', 50, 0.2, 30, 0.05, 0.002, 'Low', 'DIN 18550; AAC thin-bed mortar performance data', 7, 6, 8, 'Medium', 'Class A', 0.1, 10, '3-5mm bed reduces thermal bridging at joints by 60-70% versus standard mortar. Key to AAC thermal performance.', 6, 1, 'N/A', 'Clay brick|Fly ash brick|Hollow concrete block|Any non-AAC masonry unit', 'AAC block (Ytong|Aerocon|Magicrete|Ultratech)', 'Notched trowel for uniform bed thickness|AAC block system from same manufacturer|Water measured per bag instructions', 'None', 'Only use with AAC blocks. Do not use on clay brick or other masonry - bond will fail.', 'None', '', '', 'AAC manufacturer installation guidelines; DIN 18550', 'Thin-bed mortar is non-negotiable if you choose AAC blocks. The entire thermal performance advantage of AAC - the lightweight aerated concrete that acts as a natural insulator - is dramatically reduced if you use standard 10-15mm cement mortar at the joints because the mortar has a much higher conductivity than the AAC block and creates a thermal bypass path at every course. Thin-bed adhesive mortar at 3-5mm thickness reduces this joint thermal bridging by 60-70 percent. Buy the mortar from the same manufacturer as your AAC blocks because the adhesive is formulated for the specific block porosity and surface texture. Use the manufacturer-supplied notched trowel to ensure consistent 3-5mm bed thickness. The cost is higher per bag than cement mortar but you use far less material because of the thin application.', 'Essential for AAC thermal performance - eliminates joint thermal bridging|Faster laying than standard mortar|Precise 3-5mm joint reduces material consumption|Manufacturer system warranty when used correctly', 'More expensive per sqft than cement mortar|Only works with AAC - wrong choice for other masonry|Requires notched trowel and trained mason|AAC first course levelling critical before thin-bed can be used', 'Thin-bed mortar for AAC blocks only. 3-5mm joint essential for AAC thermal performance. Buy from same manufacturer as blocks.', 'Active', 'None', 'AI') ON CONFLICT (component_id) DO NOTHING;
INSERT INTO components (component_id, category_name, subcategory_name, name, display_name, description, region, climate_zone, spectrum_position, sort_order, base_cost_per_sqft_inr, installation_cost_per_sqft_inr, cost_confidence, cost_last_updated, cost_source_notes, expected_lifespan_years, replacement_cost_factor, major_maintenance_cycle_years, major_maintenance_cost_factor, annual_minor_maint_factor, maintenance_complexity, lifecycle_source_notes, thermal_resistance_score, acoustic_score, durability_score, moisture_resistance, fire_rating, energy_impact_modifier, accessibility_score, thermal_source_notes, max_floors_supported, min_floors_required, max_span_supported_m, incompatible_with, compatible_with, requires_component, climate_restrictions, hard_block_rule, advisory_rule, advisory_message, advisory_severity, constraint_source_notes, ai_advisory_notes, pros, cons, tooltip_detail, status, verify_flags, data_filled_by) VALUES ('MORT-004', 'Structure', 'Mortar Type', 'mortar_polymer_modified', 'Polymer-Modified Mortar', 'Cement mortar with polymer additive (SBR latex or acrylic polymer) mixed in. Better adhesion, flexibility, and water resistance than plain cement mortar. Used for stone cladding, exterior exposed masonry, and areas subject to movement or severe weather.', 'South India', 'Warm-Humid|Hot-Dry|Temperate|Composite', 'Premium', 4, 14, 5, 'Medium', '2024-Q1', 'SBR latex polymer additive cost; Fosroc/Pidilite/STP market rate 2024; normalized per sqft', 50, 0.2, 25, 0.05, 0.002, 'Low', 'BS EN 998-2; polymer mortar performance data', 5, 5, 9, 'High', 'Class A', 0, 10, 'No significant thermal contribution beyond wall material.', 6, 1, 'N/A', 'None', 'Stone cladding|Exterior exposed masonry|High-movement joints|Coastal construction', 'SBR latex or acrylic polymer (Fosroc Renderoc|Pidilite Dr Fixit)|OPC cement|Clean sand', 'Recommended for all coastal construction and high-rainfall zones above 2000mm annual.', 'None', 'Mix polymer additive at manufacturer-specified ratio - do not reduce to save cost', 'Polymer-modified mortar only achieves its performance benefit at the correct polymer-to-cement ratio specified by the manufacturer. Reducing the polymer dose to save cost produces ordinary mortar with higher cost.', 'Warning', 'BS EN 998-2; manufacturer product data sheets', 'Polymer-modified mortar is the specification for stone cladding jobs and any exterior masonry in coastal zones where the combination of salt moisture and thermal cycling requires greater adhesion and flexibility than standard cement mortar can provide. The polymer additive improves tensile bond strength by 50-100 percent over plain mortar and adds flexibility that prevents cracking at movement joints. The critical quality control issue is the polymer dosage - the temptation to reduce the additive quantity to save money is real and the result is a mortar with slightly better than ordinary performance at significantly higher cost, which defeats the purpose. I measure the polymer quantity by bucket and add it before the mixing water so both I and the contractor can see the correct dose has been used.', 'Best adhesion for stone cladding and exposed masonry|Flexible - resists cracking at movement|Higher moisture resistance|Essential for coastal construction|Long service life', 'Highest mortar cost|Polymer dosage must be correctly maintained|Not needed for interior protected masonry|Requires correct mixing sequence', 'Polymer-modified mortar for stone cladding and coastal exposed masonry. Maintain correct polymer dosage - do not reduce to save cost.', 'Active', 'None', 'AI') ON CONFLICT (component_id) DO NOTHING;
INSERT INTO components (component_id, category_name, subcategory_name, name, display_name, description, region, climate_zone, spectrum_position, sort_order, base_cost_per_sqft_inr, installation_cost_per_sqft_inr, cost_confidence, cost_last_updated, cost_source_notes, expected_lifespan_years, replacement_cost_factor, major_maintenance_cycle_years, major_maintenance_cost_factor, annual_minor_maint_factor, maintenance_complexity, lifecycle_source_notes, thermal_resistance_score, acoustic_score, durability_score, moisture_resistance, fire_rating, energy_impact_modifier, accessibility_score, thermal_source_notes, max_floors_supported, min_floors_required, max_span_supported_m, incompatible_with, compatible_with, requires_component, climate_restrictions, hard_block_rule, advisory_rule, advisory_message, advisory_severity, constraint_source_notes, ai_advisory_notes, pros, cons, tooltip_detail, status, verify_flags, data_filled_by) VALUES ('LINT-001', 'Envelope', 'Lintel & Sunshade', 'lintel_rcc_only', 'RCC Lintel Only', 'Standard RCC lintel beam above all window and door openings. Structural minimum requirement - transfers load around openings to adjacent wall panels. No solar shading element included.', 'South India', 'Warm-Humid|Hot-Dry|Temperate|Composite', 'Basic', 1, 5, 3, 'High', '2024-Q1', 'Karnataka PWD SOR 2024-25 RCC lintel rates; normalized per sqft of built-up area', 60, 0, 0, 0, 0, 'Low', 'RCC lintel permanent structural element - same lifespan as structure', 5, 5, 8, 'Medium', 'Class A', -0.05, 10, 'No solar shading. Windows receive full direct solar radiation. Increases cooling load.', 20, 1, 'N/A', 'None', 'All wall systems', 'M20 concrete|Fe500 steel|Formwork', 'Not recommended as sole treatment in Hot-Dry or Warm-Humid climates - solar shading via chajja strongly advised.', 'None', 'Add chajja (sunshade) for south and west facing windows in all South India climates', 'South and west facing windows without a chajja receive direct afternoon sun. This can increase indoor temperatures by 3-5°C and significantly increases AC loads in South Indian conditions.', 'Warning', 'IS 875 Part 3; ECBC 2017', 'RCC lintel is the structural minimum and every opening needs one regardless of what else you decide. But stopping at the lintel without a chajja in South India is a missed opportunity that you will pay for in AC bills for the life of the house. A window without a chajja on the south or west face in Bangalore receives approximately 4 hours of direct afternoon sun in summer. The glass conducts this heat directly into the living space. A 750mm chajja projection above the window blocks this direct sun while allowing diffuse daylight in. The payback on the additional chajja cost through AC savings is typically 4-6 years. I only accept lintel-only when the opening faces north where there is no direct solar gain problem.', 'Lowest cost|Structural minimum requirement|Standard contractor knowledge', 'No solar protection - maximum solar heat gain through windows|Higher cooling loads especially on west and south faces|Not recommended for energy-conscious design in South India', 'RCC lintel only. No solar shading. Add chajja for south and west facing windows to reduce cooling loads.', 'Active', 'None', 'AI') ON CONFLICT (component_id) DO NOTHING;
INSERT INTO components (component_id, category_name, subcategory_name, name, display_name, description, region, climate_zone, spectrum_position, sort_order, base_cost_per_sqft_inr, installation_cost_per_sqft_inr, cost_confidence, cost_last_updated, cost_source_notes, expected_lifespan_years, replacement_cost_factor, major_maintenance_cycle_years, major_maintenance_cost_factor, annual_minor_maint_factor, maintenance_complexity, lifecycle_source_notes, thermal_resistance_score, acoustic_score, durability_score, moisture_resistance, fire_rating, energy_impact_modifier, accessibility_score, thermal_source_notes, max_floors_supported, min_floors_required, max_span_supported_m, incompatible_with, compatible_with, requires_component, climate_restrictions, hard_block_rule, advisory_rule, advisory_message, advisory_severity, constraint_source_notes, ai_advisory_notes, pros, cons, tooltip_detail, status, verify_flags, data_filled_by) VALUES ('LINT-002', 'Envelope', 'Lintel & Sunshade', 'lintel_with_chajja', 'Lintel + Sunshade (Chajja)', 'RCC lintel beam with integral or separately cast chajja (sunshade) projecting 450-750mm above the window. Reduces direct solar radiation through glass on south and west faces. Standard recommended specification for South India construction.', 'South India', 'Warm-Humid|Hot-Dry|Temperate|Composite', 'Intermediate', 2, 10, 6, 'High', '2024-Q1', 'Karnataka PWD SOR 2024-25 RCC lintel + chajja rates; 600mm projection standard; normalized per sqft', 60, 0, 0, 0, 0.002, 'Low', 'RCC chajja permanent element - same lifespan as structure with minimal maintenance', 6, 5, 8, 'High', 'Class A', 0.1, 10, '600mm chajja projection blocks direct summer sun on south face. Reduces solar heat gain by 15-25% for south-facing windows.', 20, 1, 'N/A', 'None', 'All wall systems|All window types', 'M20 concrete|Fe500 steel|Waterproofing on top surface of chajja|Drip groove at tip', 'Recommended for all South India climates. Most important for south and west facing openings.', 'None', 'Drip groove at chajja tip mandatory to prevent water tracking back under chajja to wall', 'A chajja without a drip groove (notch) at the tip will allow rain water to track back along the soffit to the wall surface causing dampness and staining below the opening.', 'Warning', 'IS 875 Part 3; ECBC 2017; NBC 2016', 'The chajja is one of the most cost-effective passive cooling elements in South India architecture and it has been used for centuries for exactly this reason. A 600mm projection above a south-facing window blocks the high summer sun angle completely while allowing diffuse skylight in through the full window. The detail that every contractor gets wrong is the drip groove - you need a 10-15mm V-groove cut on the underside of the chajja approximately 50mm from the tip so that rain water hitting the top of the chajja drips cleanly to the ground rather than tracking back along the soffit and staining the wall below the window. Also waterproof the top surface of the chajja with two coats of polymer cementitious waterproofing because it is a horizontal slab fully exposed to rain and the standing water will penetrate unprotected concrete and cause spalling within 5-10 years.', '15-25% solar heat gain reduction on south/west faces|Protects window from direct rain reducing weathering|Traditional South India climate-appropriate design|Good payback through reduced AC loads|Permanent no-maintenance element', 'Additional cost over lintel only|Slightly increases shadow on garden in winter|Poor installation common - enforce drip groove and waterproofing|Wrong orientation gives little benefit', 'Lintel + chajja sunshade. Standard South India specification. Drip groove mandatory. Waterproof top surface.', 'Active', 'None', 'AI') ON CONFLICT (component_id) DO NOTHING;
INSERT INTO components (component_id, category_name, subcategory_name, name, display_name, description, region, climate_zone, spectrum_position, sort_order, base_cost_per_sqft_inr, installation_cost_per_sqft_inr, cost_confidence, cost_last_updated, cost_source_notes, expected_lifespan_years, replacement_cost_factor, major_maintenance_cycle_years, major_maintenance_cost_factor, annual_minor_maint_factor, maintenance_complexity, lifecycle_source_notes, thermal_resistance_score, acoustic_score, durability_score, moisture_resistance, fire_rating, energy_impact_modifier, accessibility_score, thermal_source_notes, max_floors_supported, min_floors_required, max_span_supported_m, incompatible_with, compatible_with, requires_component, climate_restrictions, hard_block_rule, advisory_rule, advisory_message, advisory_severity, constraint_source_notes, ai_advisory_notes, pros, cons, tooltip_detail, status, verify_flags, data_filled_by) VALUES ('LINT-003', 'Envelope', 'Lintel & Sunshade', 'lintel_band_deep_chajja', 'Band Beam + Deep Extended Chajja', 'Continuous horizontal RCC band beam at sill or lintel level combined with extended 900mm+ chajja projection. Provides maximum solar shading, structural rigidity, and a distinctive horizontal banding aesthetic. Used in energy-efficient and architect-designed construction.', 'South India', 'Hot-Dry|Warm-Humid', 'Premium', 3, 18, 10, 'Medium', '2024-Q1', 'RCC band beam + extended chajja contractor rates Bangalore 2024; normalized per sqft', 60, 0, 0, 0, 0.002, 'Low', 'RCC band and chajja permanent element - lifespan equals structure', 8, 5, 9, 'High', 'Class A', 0.2, 10, '900mm+ chajja eliminates direct solar gain through windows in all South India latitudes for 80% of daylight hours in summer. Best passive cooling element for facades.', 20, 1, 'N/A', 'None', 'All wall systems|Energy-efficient design|IGBC Green Homes compliance', 'M20+ concrete|Fe500D steel|Waterproofing on chajja top|Drip groove|Structural engineer approval for cantilever', 'Highest value in Hot-Dry zones. Also very effective in Warm-Humid coastal zones.', 'None', 'Structural engineer must verify cantilever design for deep chajja projection beyond 750mm', 'A chajja projecting more than 750mm requires structural engineer verification of the cantilever design, reinforcement sizing, and connection to the band beam. Do not rely on rule of thumb for projections beyond this.', 'Warning', 'IS 456; IS 875 Part 3; ECBC 2017', 'The continuous band beam with deep chajja is the element I specify for any architect-designed energy-efficient house in South India and it serves double duty - structural and environmental. As a structural element the continuous band beam ties the masonry together at window lintel level significantly improving seismic performance of the wall by creating a stiff horizontal diaphragm. As an environmental element a 900mm+ chajja projection essentially eliminates direct solar gain through the window for most of the day in summer at South India latitudes between 8 and 18 degrees north. The shade angle calculation confirms that a 900mm projection on a wall at 12 degrees north latitude blocks the sun for approximately 8 out of 10 hours of peak summer radiation. The structural engineer must verify the cantilever design for projections beyond 750mm - the reinforcement at the root of the chajja carries high bending moment and this is not something to leave to the contractor to figure out.', 'Maximum solar shading - eliminates direct solar gain|Structural benefit of continuous band beam|Improved seismic performance|Distinctive horizontal banding aesthetic|Best passive cooling element available|IGBC and ECBC compliance pathway', 'Highest cost|Structural engineer design required for deep projection|Reduces visible sky from inside|Some perceived loss of view through window|More complex formwork', 'Band beam + 900mm+ chajja. Maximum solar protection. Structural engineer required for cantilever. Best passive cooling element.', 'Active', 'None', 'AI') ON CONFLICT (component_id) DO NOTHING;
INSERT INTO components (component_id, category_name, subcategory_name, name, display_name, description, region, climate_zone, spectrum_position, sort_order, base_cost_per_sqft_inr, installation_cost_per_sqft_inr, cost_confidence, cost_last_updated, cost_source_notes, expected_lifespan_years, replacement_cost_factor, major_maintenance_cycle_years, major_maintenance_cost_factor, annual_minor_maint_factor, maintenance_complexity, lifecycle_source_notes, thermal_resistance_score, acoustic_score, durability_score, moisture_resistance, fire_rating, energy_impact_modifier, accessibility_score, thermal_source_notes, max_floors_supported, min_floors_required, max_span_supported_m, incompatible_with, compatible_with, requires_component, climate_restrictions, hard_block_rule, advisory_rule, advisory_message, advisory_severity, constraint_source_notes, ai_advisory_notes, pros, cons, tooltip_detail, status, verify_flags, data_filled_by) VALUES ('PARA-001', 'Envelope', 'Parapet', 'parapet_brick_masonry', 'Brick Masonry Parapet', 'Traditional brick masonry parapet wall at roof edge, typically 600-900mm high, plastered and painted. Economical, durable, and maintenance-free. Most common parapet in South India residential construction.', 'South India', 'Warm-Humid|Hot-Dry|Temperate|Composite', 'Basic', 1, 6, 4, 'High', '2024-Q1', 'Karnataka PWD SOR 2024-25 parapet masonry rates; normalized per sqft of roof perimeter per metre height', 40, 0.5, 15, 0.15, 0.01, 'Low', 'IS 1905; masonry parapet lifespan data', 5, 5, 7, 'Medium', 'Class A', 0, 10, 'Parapet provides minimal thermal benefit but shades roof edge.', 20, 1, 'N/A', 'None', 'Flat RCC roof|All roof systems with flat section', 'Coping slab or coping tile on top of parapet|Waterproofing at parapet-roof junction|Movement joint at parapet-roof slab connection', 'In high-rainfall zones coping slab with 40mm overhang essential to prevent water ingress at parapet base.', 'None', 'Coping slab with drip groove mandatory on top of parapet and waterproofing at parapet-slab junction', 'The junction between parapet and roof slab is the most common source of roof leaks in South India. This junction must have flexible waterproofing that can accommodate thermal movement and the parapet top must have a coping slab with drip groove.', 'Strong-Warning', 'IS 1905; NBC 2016', 'Brick masonry parapets are the default and they work well when two critical details are done correctly. First the coping - the top of the parapet is fully exposed to sun and rain and must have a RCC or stone coping slab with a 40mm overhang and drip groove on each side to prevent water from running down the parapet face and soaking into the joint between parapet and roof. Second the junction waterproofing - the right angle between the parapet base and the roof slab is under high thermal stress and cracks within a few years without a flexible waterproofing membrane that bridges this joint with a 150mm fillet. Both details are routinely skipped by contractors and both cause the majority of roof leaks I am called to investigate. Specify these details clearly in your drawings and check that they are done.', 'Most economical parapet|Maintenance-free once plastered|Familiar to all masons|Privacy screen function', 'Junction waterproofing critical - often poorly done|Coping slab detail important|Adds dead load to roof slab|Blocks rooftop views', 'Brick parapet. Coping slab and parapet-slab junction waterproofing are critical details - most common source of roof leaks.', 'Active', 'None', 'AI') ON CONFLICT (component_id) DO NOTHING;
INSERT INTO components (component_id, category_name, subcategory_name, name, display_name, description, region, climate_zone, spectrum_position, sort_order, base_cost_per_sqft_inr, installation_cost_per_sqft_inr, cost_confidence, cost_last_updated, cost_source_notes, expected_lifespan_years, replacement_cost_factor, major_maintenance_cycle_years, major_maintenance_cost_factor, annual_minor_maint_factor, maintenance_complexity, lifecycle_source_notes, thermal_resistance_score, acoustic_score, durability_score, moisture_resistance, fire_rating, energy_impact_modifier, accessibility_score, thermal_source_notes, max_floors_supported, min_floors_required, max_span_supported_m, incompatible_with, compatible_with, requires_component, climate_restrictions, hard_block_rule, advisory_rule, advisory_message, advisory_severity, constraint_source_notes, ai_advisory_notes, pros, cons, tooltip_detail, status, verify_flags, data_filled_by) VALUES ('PARA-002', 'Envelope', 'Parapet', 'parapet_rcc', 'RCC Parapet', 'Reinforced concrete parapet cast as continuation of roof slab edge. Stronger and more durable than brick masonry parapet. Better resistance to seismic loads and wind. Standard for premium construction and multi-storey buildings.', 'South India', 'Warm-Humid|Hot-Dry|Temperate|Composite', 'Intermediate', 2, 10, 6, 'High', '2024-Q1', 'RCC parapet contractor rates Bangalore/Chennai 2024; normalized per sqft of roof perimeter', 60, 0.3, 25, 0.08, 0.005, 'Low', 'IS 456; RCC parapet lifespan equals structure', 5, 5, 9, 'High', 'Class A', 0, 10, 'Dense RCC parapet has high thermal mass - minor benefit.', 20, 1, 'N/A', 'None', 'Flat RCC roof|All roof systems with flat section', 'M20 concrete|Fe500 steel|Waterproofing at parapet-slab junction|Expansion joint at corners', 'None', 'None', 'Expansion joint at parapet corners and mid-span mandatory to prevent cracking', 'RCC parapets experience significant thermal expansion and must have expansion joints at corners and at not more than 6m spacing. Without these joints cracks develop at the corners within 2-3 monsoon seasons.', 'Warning', 'IS 456; NBC 2016', 'RCC parapets are my specification for premium construction because they are monolithic with the roof slab edge making waterproofing at the junction far easier to achieve than with brick masonry which has an inherent bond line at the slab surface. The critical detail that is almost universally skipped is the expansion joint. An RCC parapet running 10-15 metres without an expansion joint will crack at the corners every time because concrete expands and contracts significantly with the 40-50 degree temperature swings a Bangalore or Chennai roof experiences between winter night and summer afternoon. Place a 10-12mm expansion joint with flexible sealant at every corner and at mid-span of runs longer than 6 metres. Waterproof the junction between parapet and roof with the same treatment as the rest of the roof - this is now a seamless concrete joint rather than a brick-to-slab interface which is a significant advantage.', 'Stronger than brick parapet|Better seismic and wind resistance|Monolithic with roof slab - easier waterproofing|60-year lifespan|Clean modern aesthetic', 'Higher cost than brick parapet|Expansion joints at corners mandatory|More complex formwork|Cracking at corners if expansion joints omitted', 'RCC parapet. Stronger and more durable. Expansion joints at corners mandatory. Monolithic waterproofing advantage over brick.', 'Active', 'None', 'AI') ON CONFLICT (component_id) DO NOTHING;
INSERT INTO components (component_id, category_name, subcategory_name, name, display_name, description, region, climate_zone, spectrum_position, sort_order, base_cost_per_sqft_inr, installation_cost_per_sqft_inr, cost_confidence, cost_last_updated, cost_source_notes, expected_lifespan_years, replacement_cost_factor, major_maintenance_cycle_years, major_maintenance_cost_factor, annual_minor_maint_factor, maintenance_complexity, lifecycle_source_notes, thermal_resistance_score, acoustic_score, durability_score, moisture_resistance, fire_rating, energy_impact_modifier, accessibility_score, thermal_source_notes, max_floors_supported, min_floors_required, max_span_supported_m, incompatible_with, compatible_with, requires_component, climate_restrictions, hard_block_rule, advisory_rule, advisory_message, advisory_severity, constraint_source_notes, ai_advisory_notes, pros, cons, tooltip_detail, status, verify_flags, data_filled_by) VALUES ('PARA-003', 'Envelope', 'Parapet', 'parapet_metal_railing', 'Metal Railing (Open Parapet)', 'Fabricated metal railing at roof edge instead of solid masonry parapet. MS or stainless steel posts with horizontal rails or glass infill. Open and modern aesthetic. Requires RCC edge beam as base. Standard for contemporary and architect-designed construction.', 'South India', 'Warm-Humid|Hot-Dry|Temperate|Composite', 'Performance', 3, 14, 7, 'Medium', '2024-Q1', 'MS railing fabrication rates Bangalore 2024; powder coat finish; normalized per sqft of roof perimeter', 25, 0.8, 8, 0.3, 0.02, 'Medium', 'MS railing coating lifespan 8-12 years; SS railing 25+ years', 5, 3, 6, 'Medium', 'Class A', 0, 10, 'Open railing allows free air circulation over roof - minor cooling benefit.', 20, 1, 'N/A', 'None', 'Flat RCC roof|RCC edge beam|Contemporary architecture', 'RCC edge beam at roof perimeter (mandatory structural base)|MS or SS posts with anchor bolts into edge beam|Powder coat or galvanising for MS|Edge waterproofing detail', 'In coastal zones within 5km of sea use 316-grade stainless steel only - MS railings corrode within 5 years in salt air.', 'None', 'Use SS 316 railing within 10km of coastline - MS corrodes in salt air within 5 years', 'MS railings in coastal zones corrode rapidly due to salt air. Use 316-grade stainless steel for any railing within 10km of the coast. The cost premium over MS is significant but replacement cost is far higher.', 'Warning', 'NBC 2016 Section 2 safety; IS 1161 structural tubes', 'Metal railings give a contemporary open look and are popular in architect-designed homes but they require much more maintenance than solid parapets. Powder-coated MS railing starts to show corrosion at the welds and base plates within 5-8 years in a typical South India climate and needs repainting. In coastal areas it is useless within 3 years unless you use marine-grade 316 stainless steel which is very expensive. The structural base is critical - the railing posts must anchor into a properly designed RCC edge beam not just drilled into the roof slab. I also always require a solid masonry kickboard at the base minimum 200mm high because the open railing allows objects to slide off the roof edge which is a serious safety hazard especially for children. If you choose this aesthetic understand the ongoing maintenance commitment - it is not a set-and-forget specification.', 'Open modern aesthetic|Better natural ventilation over roof|Clear views from rooftop|Lighter than solid parapet', 'Highest maintenance requirement - repainting every 5-8 years|Corrosion in coastal zones - SS 316 required|Less privacy than solid parapet|Objects can fall through - safety concern|RCC edge beam mandatory', 'Metal railing parapet. Modern aesthetic but highest maintenance. Use SS 316 near coast. RCC edge beam mandatory base.', 'Active', 'None', 'AI') ON CONFLICT (component_id) DO NOTHING;
INSERT INTO components (component_id, category_name, subcategory_name, name, display_name, description, region, climate_zone, spectrum_position, sort_order, base_cost_per_sqft_inr, installation_cost_per_sqft_inr, cost_confidence, cost_last_updated, cost_source_notes, expected_lifespan_years, replacement_cost_factor, major_maintenance_cycle_years, major_maintenance_cost_factor, annual_minor_maint_factor, maintenance_complexity, lifecycle_source_notes, thermal_resistance_score, acoustic_score, durability_score, moisture_resistance, fire_rating, energy_impact_modifier, accessibility_score, thermal_source_notes, max_floors_supported, min_floors_required, max_span_supported_m, incompatible_with, compatible_with, requires_component, climate_restrictions, hard_block_rule, advisory_rule, advisory_message, advisory_severity, constraint_source_notes, ai_advisory_notes, pros, cons, tooltip_detail, status, verify_flags, data_filled_by) VALUES ('CTOP-001', 'Finishes', 'Kitchen Countertop', 'countertop_ceramic_tile', 'Ceramic Tile Countertop', 'Kitchen countertop finished with ceramic or vitrified tiles on a masonry or concrete base. Economical option with wide variety of colours and patterns. Grout joints require regular maintenance to prevent staining and bacterial growth.', 'South India', 'Warm-Humid|Hot-Dry|Temperate|Composite', 'Basic', 1, 25, 10, 'High', '2024-Q1', 'Tile + masonry base + epoxy grout contractor rates Bangalore 2024; normalized per sqft of countertop area', 15, 0.7, 5, 0.15, 0.02, 'Medium', 'Tile countertop lifespan limited by grout staining and tile edge chipping', 5, 5, 5, 'Medium', 'Class A', 0, 10, 'No thermal contribution.', 20, 1, 'N/A', 'None', 'All kitchen configurations', 'Vitrified tiles (anti-bacterial glaze preferred)|Epoxy grout (not regular cement grout)|Masonry or concrete base|Edge tiles or trim', 'None', 'None', 'Use epoxy grout not cement grout - cement grout stains permanently within 1-2 years', 'Standard cement grout on kitchen countertop joints absorbs oil and food stains permanently within one to two years. Use only epoxy grout for kitchen countertop tile joints.', 'Warning', 'Tile manufacturer guidelines', 'Tile countertops are the economy option and they come with the caveat that grout maintenance is an ongoing commitment. The most critical choice is the grout - if the contractor uses standard cement grout on your kitchen counter it will be permanently stained with oil and turmeric within one monsoon season. Insist on epoxy grout which is more expensive but is stain-proof and non-porous. The other issue is edge tiles which chip over time especially at corners. A preferable detail is a bull-nose edge tile or a stainless steel edge trim that protects the vulnerable tile corner. For a rental property or a budget build where replacement is planned within 15 years the tile counter is a pragmatic choice. For your own home I would push towards granite.', 'Lowest cost|Wide colour and pattern range|Easy local repair of damaged tiles|Adequate for rental or budget builds', 'Grout joints stain and harbour bacteria|Tile edges chip at corners|Shorter lifespan than stone or quartz|Cement grout must be replaced with epoxy grout|Not ideal for high-use kitchens', 'Tile countertop. Use epoxy grout only - cement grout stains permanently. Vitrified tile preferred over ceramic.', 'Active', 'None', 'AI') ON CONFLICT (component_id) DO NOTHING;
INSERT INTO components (component_id, category_name, subcategory_name, name, display_name, description, region, climate_zone, spectrum_position, sort_order, base_cost_per_sqft_inr, installation_cost_per_sqft_inr, cost_confidence, cost_last_updated, cost_source_notes, expected_lifespan_years, replacement_cost_factor, major_maintenance_cycle_years, major_maintenance_cost_factor, annual_minor_maint_factor, maintenance_complexity, lifecycle_source_notes, thermal_resistance_score, acoustic_score, durability_score, moisture_resistance, fire_rating, energy_impact_modifier, accessibility_score, thermal_source_notes, max_floors_supported, min_floors_required, max_span_supported_m, incompatible_with, compatible_with, requires_component, climate_restrictions, hard_block_rule, advisory_rule, advisory_message, advisory_severity, constraint_source_notes, ai_advisory_notes, pros, cons, tooltip_detail, status, verify_flags, data_filled_by) VALUES ('CTOP-002', 'Finishes', 'Kitchen Countertop', 'countertop_granite', 'Granite Countertop', 'Natural granite stone slab countertop, typically 18-20mm thick. Most popular premium kitchen countertop in South India. Extremely durable, heat-resistant, and hygienic when sealed. Available in a wide range of South Indian granite varieties at competitive prices.', 'South India', 'Warm-Humid|Hot-Dry|Temperate|Composite', 'Intermediate', 2, 55, 18, 'High', '2024-Q1', 'South India granite market rate 2024; Indian granite varieties; polished 18mm slab; normalized per sqft', 30, 0.6, 10, 0.05, 0.005, 'Low', 'Granite countertop lasts 25-30+ years with proper sealing; sealing required every 2-3 years', 5, 5, 9, 'High', 'Class A', 0, 10, 'High thermal mass - stays cool. Good for South India kitchens.', 20, 1, 'N/A', 'None', 'All kitchen configurations', 'Granite sealer (applied before and after installation)|Stainless steel sink cutout|Silicone sealant at wall joint|RCC or masonry counter base', 'None', 'None', 'Seal granite before installation and after installation - unsealed granite absorbs oil stains', 'Unsealed granite absorbs oil and turmeric stains readily. Apply stone sealer before installation and after installation when dry. Reseal every 2-3 years.', 'Warning', 'Natural Stone Institute sealing guidelines', 'Granite is my recommendation for the vast majority of South India kitchen countertops and the reason is simple - it is extremely hard wearing heat resistant and the price of good quality Indian granite is very competitive because we quarry it right here in Karnataka Tamil Nadu and Andhra. A Krishna White or Steel Grey or Tan Brown granite counter will last 25-30 years with minimal maintenance. The important detail is sealing - all granite must be sealed before it goes in and again after installation because unsealed granite will absorb turmeric and cooking oil stains. Apply the sealer let it penetrate and wipe off the excess. Reseal every 2-3 years. The other thing to insist on is that the underside of the granite is properly supported - unsupported granite over sink cutouts more than 400mm wide can crack. Your fabricator should provide stainless steel or granite support bars.', 'Best durability for South India use - 30 year lifespan|Heat resistant|Competitive price for Indian granite varieties|Hygienic when sealed|Wide range of South India granite patterns|Adds property value', 'Requires sealing every 2-3 years|Heavy - counter structure must be adequate|Cracks if unsupported over large cutouts|Porous if unsealed', 'Granite countertop. Best value for South India. Seal before and after installation. Reseal every 2-3 years.', 'Active', 'None', 'AI') ON CONFLICT (component_id) DO NOTHING;
INSERT INTO components (component_id, category_name, subcategory_name, name, display_name, description, region, climate_zone, spectrum_position, sort_order, base_cost_per_sqft_inr, installation_cost_per_sqft_inr, cost_confidence, cost_last_updated, cost_source_notes, expected_lifespan_years, replacement_cost_factor, major_maintenance_cycle_years, major_maintenance_cost_factor, annual_minor_maint_factor, maintenance_complexity, lifecycle_source_notes, thermal_resistance_score, acoustic_score, durability_score, moisture_resistance, fire_rating, energy_impact_modifier, accessibility_score, thermal_source_notes, max_floors_supported, min_floors_required, max_span_supported_m, incompatible_with, compatible_with, requires_component, climate_restrictions, hard_block_rule, advisory_rule, advisory_message, advisory_severity, constraint_source_notes, ai_advisory_notes, pros, cons, tooltip_detail, status, verify_flags, data_filled_by) VALUES ('CTOP-003', 'Finishes', 'Kitchen Countertop', 'countertop_solid_surface', 'Solid Surface (Corian/HI-MACS)', 'Homogeneous acrylic or polyester solid surface material (Corian, HI-MACS, Staron). Non-porous, seamless at joints, and surface scratches can be sanded out. Good for island countertops and modern aesthetic. Moderate heat resistance - requires trivets.', 'South India', 'Warm-Humid|Hot-Dry|Temperate|Composite', 'Performance', 3, 90, 22, 'Medium', '2024-Q1', 'Corian/HI-MACS dealer rates Bangalore/Chennai 2024; thermoforming + install; normalized per sqft', 20, 0.7, 10, 0.1, 0.01, 'Medium', 'Solid surface lifespan 15-25 years; surface renewal possible by sanding', 5, 5, 7, 'Very High', 'Class B', 0, 10, 'No thermal contribution.', 20, 1, 'N/A', 'None', 'All kitchen configurations|Island countertops|Modern minimalist kitchens', 'Certified solid surface fabricator|Trivet policy for hot pans|Special adhesive for seams', 'None', 'None', 'Always use trivets for hot pans - solid surface has lower heat resistance than granite', 'Solid surface materials have a maximum continuous heat exposure of around 175°C. Direct contact with hot cookware can cause whitening or warping. Always use trivets or hot pads.', 'Warning', 'Corian/HI-MACS product technical data', 'Solid surface is the right choice when you want a seamless countertop particularly for island kitchens where an integrated undermount sink without a joint is aesthetically important and hygienic. The non-porous nature means zero maintenance for stains - just wipe down. The limitation that most clients do not realise until they have it installed is the heat sensitivity. In a South India kitchen where you are handling a pressure cooker or kadai you must always use a trivet. A single contact with a hot stainless steel vessel can cause permanent whitening of the surface. The surface scratch renewal feature is real - a certified fabricator can sand out surface marks with an orbital sander and bring it back to new condition which is genuinely useful after 8-10 years of use.', 'Seamless non-porous surface - no staining|Integrated sink possible with no visible joint|Surface scratches sandable - renewable|Modern minimal aesthetic|Easy to clean', 'Lower heat resistance than granite - trivets mandatory|Higher cost than granite|Certified fabricator required for good seams|Shorter lifespan than granite|Repair requires specialist', 'Solid surface countertop. Non-porous and seamless. Always use trivets - lower heat resistance than granite.', 'Active', 'None', 'AI') ON CONFLICT (component_id) DO NOTHING;
INSERT INTO components (component_id, category_name, subcategory_name, name, display_name, description, region, climate_zone, spectrum_position, sort_order, base_cost_per_sqft_inr, installation_cost_per_sqft_inr, cost_confidence, cost_last_updated, cost_source_notes, expected_lifespan_years, replacement_cost_factor, major_maintenance_cycle_years, major_maintenance_cost_factor, annual_minor_maint_factor, maintenance_complexity, lifecycle_source_notes, thermal_resistance_score, acoustic_score, durability_score, moisture_resistance, fire_rating, energy_impact_modifier, accessibility_score, thermal_source_notes, max_floors_supported, min_floors_required, max_span_supported_m, incompatible_with, compatible_with, requires_component, climate_restrictions, hard_block_rule, advisory_rule, advisory_message, advisory_severity, constraint_source_notes, ai_advisory_notes, pros, cons, tooltip_detail, status, verify_flags, data_filled_by) VALUES ('CTOP-004', 'Finishes', 'Kitchen Countertop', 'countertop_engineered_quartz', 'Engineered Quartz (Silestone/Caesarstone)', 'Engineered stone countertop made from 90-95% quartz crystals bound with polymer resin. Non-porous, consistent colour, extremely hard, and does not require sealing. Premium choice combining stone durability with consistent aesthetics.', 'South India', 'Warm-Humid|Hot-Dry|Temperate|Composite', 'Premium', 4, 120, 28, 'Medium', '2024-Q1', 'Silestone/Caesarstone/Quantra dealer rates South India 2024; normalized per sqft', 25, 0.6, 15, 0.03, 0.003, 'Low', 'Quartz countertop manufacturer lifespan data; 20-25 year typical lifespan', 5, 5, 10, 'Very High', 'Class B', 0, 10, 'No thermal contribution.', 20, 1, 'N/A', 'None', 'All kitchen configurations|Modern premium kitchens', 'Certified fabricator with water-jet cutter|Trivet policy for hot pans|Silicone at wall joint', 'None', 'None', 'Trivets required - engineered quartz is heat sensitive despite high hardness', 'Despite being harder than granite engineered quartz is sensitive to high heat due to the polymer resin binder. Thermal shock from hot cookware can cause cracking or discolouration. Always use trivets.', 'Warning', 'Quartz manufacturer technical data', 'Engineered quartz is the premium choice I recommend when the client wants zero maintenance and consistent aesthetics because unlike natural granite it requires no sealing and has completely consistent colour and pattern without the natural variation of stone. The 90+ percent quartz content makes it the hardest countertop material available and it is completely non-porous so there is literally nothing to maintain beyond wiping it down. The limitation shared with solid surface is heat sensitivity - the polymer resin that binds the quartz crystals can crack or discolour under thermal shock from a hot kadai. This is a significant limitation in a South Indian kitchen where high-temperature cooking is standard. Always use trivets. The price premium over granite is substantial but for a client who wants a showpiece kitchen that remains pristine with zero maintenance effort it is justified.', 'Hardest countertop material available|Zero maintenance - no sealing required|Completely non-porous|Consistent colour and pattern|Best stain resistance|25-year lifespan', 'Highest cost|Heat sensitive - trivets mandatory|Not suitable for direct contact with Indian high-heat cooking|Certified fabricator required|Heavier than solid surface', 'Engineered quartz. Hardest and lowest maintenance. Heat sensitive - trivets mandatory for Indian cooking. Premium cost.', 'Active', 'None', 'AI') ON CONFLICT (component_id) DO NOTHING;
INSERT INTO components (component_id, category_name, subcategory_name, name, display_name, description, region, climate_zone, spectrum_position, sort_order, base_cost_per_sqft_inr, installation_cost_per_sqft_inr, cost_confidence, cost_last_updated, cost_source_notes, expected_lifespan_years, replacement_cost_factor, major_maintenance_cycle_years, major_maintenance_cost_factor, annual_minor_maint_factor, maintenance_complexity, lifecycle_source_notes, thermal_resistance_score, acoustic_score, durability_score, moisture_resistance, fire_rating, energy_impact_modifier, accessibility_score, thermal_source_notes, max_floors_supported, min_floors_required, max_span_supported_m, incompatible_with, compatible_with, requires_component, climate_restrictions, hard_block_rule, advisory_rule, advisory_message, advisory_severity, constraint_source_notes, ai_advisory_notes, pros, cons, tooltip_detail, status, verify_flags, data_filled_by) VALUES ('BATH-001', 'Finishes', 'Bathroom Fixtures', 'bath_economy_grade', 'Economy Grade Fixtures', 'Economy-tier sanitaryware and bathroom fittings. Brands: Hindware Ace series, Cera Standard, Johnson Tiles economy range. Basic functionality with adequate quality for rental properties or budget builds. CP fittings (taps, showers) from Indian economy range.', 'South India', 'Warm-Humid|Hot-Dry|Temperate|Composite', 'Basic', 1, 12, 6, 'High', '2024-Q1', 'Economy sanitaryware market rate South India 2024; normalized per sqft of bathroom area', 10, 0.8, 5, 0.2, 0.03, 'Medium', 'Economy fixtures typical lifespan 8-12 years before replacement or major maintenance', 5, 5, 5, 'Medium', 'Non-Rated', 0, 7, 'No thermal contribution.', 20, 1, 'N/A', 'None', 'All bathroom configurations', 'IS 2556 compliant sanitaryware|IS 1795 compliant CP fittings', 'None', 'None', 'Check BIS mark on CP fittings - uncertified economy fittings fail within 2-3 years', 'Many economy-grade CP fittings lack BIS certification and use thin chrome plating that peels within 2-3 years. Always check for IS 1795 BIS mark on taps and showers.', 'Warning', 'IS 2556; IS 1795', 'Economy fixtures make sense for rental properties and budget builds where replacement every 8-10 years is factored into the financial model. The critical quality filter even at economy grade is the BIS mark on CP fittings - taps showers and shower heads from uncertified manufacturers use chrome plating that is 2-3 microns thick versus the 8+ microns required by IS 1795 and it peels within two monsoon seasons leaving corroded brass exposed. This is particularly visible in South India where the chlorinated municipal water attacks thin plating aggressively. Stick to Hindware Cera or Parryware economy range which are certified even at entry level. For a house you plan to live in for 20 years the mid-range fixtures are worth the extra outlay.', 'Lowest cost|Adequate for rental properties|Wide availability|Reasonable functionality for basic use', '8-10 year lifespan|CP fittings prone to peeling if uncertified|Less water-efficient|Limited design options|Not recommended for owner-occupied homes', 'Economy fixtures for rental/budget builds. Check BIS mark on CP fittings. 8-10 year lifespan.', 'Active', 'None', 'AI') ON CONFLICT (component_id) DO NOTHING;
INSERT INTO components (component_id, category_name, subcategory_name, name, display_name, description, region, climate_zone, spectrum_position, sort_order, base_cost_per_sqft_inr, installation_cost_per_sqft_inr, cost_confidence, cost_last_updated, cost_source_notes, expected_lifespan_years, replacement_cost_factor, major_maintenance_cycle_years, major_maintenance_cost_factor, annual_minor_maint_factor, maintenance_complexity, lifecycle_source_notes, thermal_resistance_score, acoustic_score, durability_score, moisture_resistance, fire_rating, energy_impact_modifier, accessibility_score, thermal_source_notes, max_floors_supported, min_floors_required, max_span_supported_m, incompatible_with, compatible_with, requires_component, climate_restrictions, hard_block_rule, advisory_rule, advisory_message, advisory_severity, constraint_source_notes, ai_advisory_notes, pros, cons, tooltip_detail, status, verify_flags, data_filled_by) VALUES ('BATH-002', 'Finishes', 'Bathroom Fixtures', 'bath_mid_range_grade', 'Mid-Range Grade Fixtures', 'Mid-range sanitaryware and bathroom fittings. Brands: Jaquar Solo/Opal series, Parryware T-Connect, Hindware Italian Collection, Cera Prima. Good quality, water-efficient, and better aesthetics. Suitable for owner-occupied residential construction.', 'South India', 'Warm-Humid|Hot-Dry|Temperate|Composite', 'Intermediate', 2, 25, 10, 'High', '2024-Q1', 'Jaquar/Parryware mid-range dealer rates South India 2024; normalized per sqft of bathroom area', 20, 0.6, 10, 0.1, 0.015, 'Low', 'Mid-range fixture lifespan 15-20 years with normal maintenance', 5, 5, 7, 'High', 'Non-Rated', 0.05, 8, 'No thermal contribution.', 20, 1, 'N/A', 'None', 'All bathroom configurations', 'IS 2556 sanitaryware|IS 1795 CP fittings|WELS water efficiency label preferred', 'None', 'None', 'None', '', '', 'IS 2556; IS 1795; BIS certification', 'Mid-range from Jaquar or Parryware is my standard recommendation for any owner-occupied home in South India. Jaquar in particular has excellent quality control at their mid-range Solo and Opal series and the CP fittings use proper 8-10 micron chrome plating that holds up well in South India water conditions. The water efficiency is meaningfully better than economy grade - Jaquar mid-range taps typically have aerators that restrict flow to 6 litres per minute versus 12+ for economy grade which makes a real difference in water bills over 20 years. The aesthetic quality is also significantly better with more consistent colour glazing on the sanitaryware. This is the range where you get genuinely good quality without paying the premium brand surcharge.', 'Good quality for 20-year lifespan|Water-efficient CP fittings|BIS certified|Better aesthetics than economy|Jaquar/Parryware service network across South India|Best value tier', 'Higher cost than economy|Not as durable as premium brands|Service required every 10 years', 'Mid-range fixtures - best value for owner-occupied homes. Jaquar/Parryware recommended. 20-year lifespan.', 'Active', 'None', 'AI') ON CONFLICT (component_id) DO NOTHING;
INSERT INTO components (component_id, category_name, subcategory_name, name, display_name, description, region, climate_zone, spectrum_position, sort_order, base_cost_per_sqft_inr, installation_cost_per_sqft_inr, cost_confidence, cost_last_updated, cost_source_notes, expected_lifespan_years, replacement_cost_factor, major_maintenance_cycle_years, major_maintenance_cost_factor, annual_minor_maint_factor, maintenance_complexity, lifecycle_source_notes, thermal_resistance_score, acoustic_score, durability_score, moisture_resistance, fire_rating, energy_impact_modifier, accessibility_score, thermal_source_notes, max_floors_supported, min_floors_required, max_span_supported_m, incompatible_with, compatible_with, requires_component, climate_restrictions, hard_block_rule, advisory_rule, advisory_message, advisory_severity, constraint_source_notes, ai_advisory_notes, pros, cons, tooltip_detail, status, verify_flags, data_filled_by) VALUES ('BATH-003', 'Finishes', 'Bathroom Fixtures', 'bath_premium_grade', 'Premium Grade Fixtures', 'Premium sanitaryware and bathroom fittings. Brands: Kohler, TOTO, Duravit, Grohe, American Standard. Highest build quality, water efficiency, and aesthetic design. Concealed cistern systems, wall-hung WCs, rain showers. For premium construction and luxury bathrooms.', 'South India', 'Warm-Humid|Hot-Dry|Temperate|Composite', 'Premium', 3, 60, 18, 'Medium', '2024-Q1', 'Kohler/TOTO/Duravit dealer rates Bangalore/Chennai 2024; normalized per sqft of bathroom area', 25, 0.5, 15, 0.05, 0.008, 'Low', 'Premium fixture lifespan 20-30 years; spare parts availability key', 5, 5, 9, 'Very High', 'Non-Rated', 0.1, 9, 'No thermal contribution.', 20, 1, 'N/A', 'None', 'All bathroom configurations|Premium and luxury residential construction', 'Trained plumber familiar with brand-specific installation|Concealed cistern framing if wall-hung WC|Manufacturer-specified accessories', 'None', 'None', 'Verify local service and spare parts availability before specifying niche international brands', 'Some international premium brands have limited service network in Tier 2 South India cities. Verify that the brand has authorised service and spare parts availability in your city before specifying.', 'Warning', 'Manufacturer warranty terms', 'Premium fixtures from Kohler or TOTO are genuinely excellent products with build quality that is meaningfully superior to mid-range. The glazing quality on Kohler and TOTO sanitaryware is better which means less staining and easier cleaning over 20+ years. The TOTO Washlet integrated bidet-seat is a particularly good product for South India given the water usage habits and hygiene preferences. The concern I raise with clients is service - Kohler has a reasonable service network in Bangalore Chennai and Hyderabad but if you are building in a Tier 2 city like Mysore or Trichy confirm that a certified service technician and spare parts are available locally before you commit. A concealed cistern that needs a specific TOTO part from Mumbai with a 2-week lead time is a significant inconvenience.', 'Highest quality and durability|Best water efficiency ratings|Superior aesthetics|25+ year lifespan|Advanced features (concealed cisterns, wall-hung WC, integrated bidets)', 'Highest cost|Service and spare parts availability must be verified locally|Wall-hung WC requires frame installation|Over-specified for most residential builds', 'Premium fixtures (Kohler/TOTO/Duravit). 25+ year lifespan. Verify local service network before specifying.', 'Active', 'None', 'AI') ON CONFLICT (component_id) DO NOTHING;
INSERT INTO components (component_id, category_name, subcategory_name, name, display_name, description, region, climate_zone, spectrum_position, sort_order, base_cost_per_sqft_inr, installation_cost_per_sqft_inr, cost_confidence, cost_last_updated, cost_source_notes, expected_lifespan_years, replacement_cost_factor, major_maintenance_cycle_years, major_maintenance_cost_factor, annual_minor_maint_factor, maintenance_complexity, lifecycle_source_notes, thermal_resistance_score, acoustic_score, durability_score, moisture_resistance, fire_rating, energy_impact_modifier, accessibility_score, thermal_source_notes, max_floors_supported, min_floors_required, max_span_supported_m, incompatible_with, compatible_with, requires_component, climate_restrictions, hard_block_rule, advisory_rule, advisory_message, advisory_severity, constraint_source_notes, ai_advisory_notes, pros, cons, tooltip_detail, status, verify_flags, data_filled_by) VALUES ('ELOAD-001', 'Systems', 'Electrical Load', 'load_5kw_single_phase', '5 kW Single Phase', '5 kW single phase BESCOM/TNEB service connection. Adequate for 1-2 BHK apartments or small houses with basic appliances, no air conditioning or minimal ceiling fan + 1 small AC.', 'South India', 'Warm-Humid|Hot-Dry|Temperate|Composite', 'Basic', 1, 8, 5, 'High', '2024-Q1', 'Electrical contractor rate; panel + wiring + connection charges normalized per sqft', 25, 0.5, 10, 0.1, 0.005, 'Low', 'Electrical system lifespan 20-30 years with proper maintenance', 5, 5, 7, 'Medium', 'Class A', 0, 10, 'No thermal contribution.', 20, 1, 'N/A', '3-phase appliances|Multiple ACs|EV charging', 'Residential 1-2BHK|Basic appliance load', '25A main MCB|4-6 way distribution board|2.5 sqmm copper wiring', 'None', 'None', 'Upgrade to 3-phase if more than 2 ACs planned at any point in future', 'Single phase 5kW is severely limited. Any future addition of a second AC or EV charging will require a costly panel upgrade and BESCOM/TNEB re-connection process.', 'Warning', 'BESCOM/TNEB service connection regulations; IS 732', 'A 5 kW single phase connection is genuinely undersized for any 3 BHK house in South India in 2024. Even if you only have one split AC today you will add more within 5-10 years as climate gets hotter. A 1.5 ton AC alone draws 1.5-2 kW so two ACs plus a refrigerator plus a washing machine plus kitchen appliances easily exceeds 5 kW simultaneously. When you trip the main MCB repeatedly because of load you will have to apply for a load extension from BESCOM which involves significant paperwork fees and delays. Upgrading to three phase from the start costs Rs 15000-25000 more now versus Rs 80000-150000 for a connection upgrade later including the BESCOM application fee wiring changes and transformer load addition. Spend the money now.', 'Lowest connection cost|Adequate for very basic 1-2 BHK|Simple single phase wiring', 'Insufficient for most 3 BHK residences with AC|Cannot add EV charging|Costly upgrade later|Trips frequently under load|Not future-ready', '5kW single phase. Only for small 1-2 BHK with minimal AC. Upgrade cost is 5x later - invest in 3-phase now.', 'Active', 'None', 'AI') ON CONFLICT (component_id) DO NOTHING;
INSERT INTO components (component_id, category_name, subcategory_name, name, display_name, description, region, climate_zone, spectrum_position, sort_order, base_cost_per_sqft_inr, installation_cost_per_sqft_inr, cost_confidence, cost_last_updated, cost_source_notes, expected_lifespan_years, replacement_cost_factor, major_maintenance_cycle_years, major_maintenance_cost_factor, annual_minor_maint_factor, maintenance_complexity, lifecycle_source_notes, thermal_resistance_score, acoustic_score, durability_score, moisture_resistance, fire_rating, energy_impact_modifier, accessibility_score, thermal_source_notes, max_floors_supported, min_floors_required, max_span_supported_m, incompatible_with, compatible_with, requires_component, climate_restrictions, hard_block_rule, advisory_rule, advisory_message, advisory_severity, constraint_source_notes, ai_advisory_notes, pros, cons, tooltip_detail, status, verify_flags, data_filled_by) VALUES ('ELOAD-002', 'Systems', 'Electrical Load', 'load_10kw_three_phase', '10 kW Three Phase', '10 kW three phase BESCOM/TNEB service connection. Standard for 3 BHK residential with 2-3 split ACs, all household appliances, washing machine, water heater. Three phase allows balanced load distribution and supports larger individual appliances.', 'South India', 'Warm-Humid|Hot-Dry|Temperate|Composite', 'Intermediate', 2, 14, 8, 'High', '2024-Q1', 'Three phase BESCOM connection charges; electrician rates; normalized per sqft', 25, 0.5, 10, 0.08, 0.005, 'Low', 'Electrical system lifespan 20-30 years', 5, 5, 8, 'Medium', 'Class A', 0, 10, 'No thermal contribution.', 20, 1, 'N/A', 'None', '3 BHK residential|2-3 split ACs|All standard appliances', '3-phase 40A main RCCB|12-16 way distribution board|4 sqmm copper wiring on AC circuits|Earth leakage protection', 'None', 'None', 'Plan conduit provision for future EV charging circuit even if not installing charger now', 'Laying an empty conduit from the DB to the parking area during construction costs Rs 500. Adding an EV charging circuit later without pre-laid conduit costs Rs 8000-15000 including wall chasing.', 'Warning', 'BESCOM/TNEB regulations; IS 732; NBC 2016', 'Ten kilowatts three phase is the right specification for the standard 3-4 BHK South India home and most BESCOM consumers in residential layouts have this connection. Three phase means you can balance the AC loads across the three phases which prevents the voltage sag you get on a single phase circuit when multiple large loads are running simultaneously. The practical things to get right are the main RCCB rating (40A minimum for 10 kW three phase), earth leakage protection on every circuit, and dedicated circuits for each AC rather than sharing with lighting. An electrician who wants to put all your ACs on one circuit or skip earth leakage circuit breakers is cutting corners. Also insist on 4 sqmm copper wire on all AC circuits - the 2.5 sqmm wire used for light points is undersized for split AC current draw and will overheat under sustained use.', 'Standard specification for 3-4 BHK|Supports 2-3 ACs comfortably|Balanced three phase load|Future-ready for most appliances|Wide contractor knowledge', 'Not sufficient for EV charging and solar inverter simultaneously|Upgrade to 15kW needed for EV home charging|Higher connection fee than single phase', '10kW 3-phase. Standard for 3 BHK with 2-3 ACs. Lay EV conduit during construction. 4sqmm wire on AC circuits.', 'Active', 'None', 'AI') ON CONFLICT (component_id) DO NOTHING;
INSERT INTO components (component_id, category_name, subcategory_name, name, display_name, description, region, climate_zone, spectrum_position, sort_order, base_cost_per_sqft_inr, installation_cost_per_sqft_inr, cost_confidence, cost_last_updated, cost_source_notes, expected_lifespan_years, replacement_cost_factor, major_maintenance_cycle_years, major_maintenance_cost_factor, annual_minor_maint_factor, maintenance_complexity, lifecycle_source_notes, thermal_resistance_score, acoustic_score, durability_score, moisture_resistance, fire_rating, energy_impact_modifier, accessibility_score, thermal_source_notes, max_floors_supported, min_floors_required, max_span_supported_m, incompatible_with, compatible_with, requires_component, climate_restrictions, hard_block_rule, advisory_rule, advisory_message, advisory_severity, constraint_source_notes, ai_advisory_notes, pros, cons, tooltip_detail, status, verify_flags, data_filled_by) VALUES ('ELOAD-003', 'Systems', 'Electrical Load', 'load_15kw_three_phase_ev', '15 kW Three Phase + EV Ready', '15 kW three phase BESCOM/TNEB service connection with pre-provisioned EV charging circuit and conduit to parking. Future-ready specification for solar inverter, EV charging, home office equipment, and large ACs. Best long-term investment for 2024 construction.', 'South India', 'Warm-Humid|Hot-Dry|Temperate|Composite', 'Premium', 3, 22, 12, 'Medium', '2024-Q1', '15kW BESCOM connection; EV conduit and circuit provision; enhanced wiring; normalized per sqft', 25, 0.4, 10, 0.05, 0.003, 'Low', 'Electrical system lifespan 20-30 years; future-proof for EV and solar', 5, 5, 9, 'Medium', 'Class A', 0.1, 10, 'No thermal contribution.', 20, 1, 'N/A', 'None', 'All residential configurations|Solar grid-tied inverter|EV home charging|Home office equipment', '15kW three phase BESCOM meter|16-20 way distribution board|Dedicated EV circuit conduit to parking|4-6 sqmm copper wiring on power circuits|Bidirectional meter provision for solar', 'None', 'None', 'None', '', '', 'BESCOM/TNEB solar net metering regulations; IS 732', 'Fifteen kilowatts three phase with EV provisioning is the specification I am recommending to every new build client in 2024 and the reason is simply the trajectory of EV adoption. BESCOM statistics show that EV registrations in Bangalore grew by 80 percent in 2023. If you are building a house today that you plan to live in for 20 years there is a high probability that you will own an electric vehicle within that period. A 7.2 kW home EV charger draws 32A on a dedicated circuit - this cannot be accommodated on a 10 kW connection that is already carrying 2-3 ACs and household loads. The incremental cost of going from 10 kW to 15 kW at construction time is Rs 15000-20000 more. The cost of upgrading later is Rs 80000-120000 including BESCOM fees connection upgrade and wiring changes. The EV circuit conduit alone - just the plastic pipe from the DB to the parking - costs Rs 500 during construction and Rs 8000-12000 after plastering.', 'Future-ready for EV charging and solar inverter|Handles simultaneous high loads|BESCOM bidirectional meter provision for solar net metering|Best long-term value|Marginal cost premium over 10kW', 'Higher connection fee than 10kW|Slightly higher installation cost|Over-specified if no EV or solar planned|BESCOM approval time for 15kW may be longer', '15kW 3-phase + EV ready. Best future-proof specification for 2024 construction. EV conduit to parking costs Rs 500 now vs Rs 12000 later.', 'Active', 'None', 'AI') ON CONFLICT (component_id) DO NOTHING;
INSERT INTO components (component_id, category_name, subcategory_name, name, display_name, description, region, climate_zone, spectrum_position, sort_order, base_cost_per_sqft_inr, installation_cost_per_sqft_inr, cost_confidence, cost_last_updated, cost_source_notes, expected_lifespan_years, replacement_cost_factor, major_maintenance_cycle_years, major_maintenance_cost_factor, annual_minor_maint_factor, maintenance_complexity, lifecycle_source_notes, thermal_resistance_score, acoustic_score, durability_score, moisture_resistance, fire_rating, energy_impact_modifier, accessibility_score, thermal_source_notes, max_floors_supported, min_floors_required, max_span_supported_m, incompatible_with, compatible_with, requires_component, climate_restrictions, hard_block_rule, advisory_rule, advisory_message, advisory_severity, constraint_source_notes, ai_advisory_notes, pros, cons, tooltip_detail, status, verify_flags, data_filled_by) VALUES ('EPOINTS-001', 'Systems', 'Electrical Points', 'points_basic', 'Basic Point Density', 'Basic electrical outlet density. 1-2 power sockets per room, single light point per room, no dedicated data or USB points. Adequate for very minimal usage or rental construction. NBC minimum compliance.', 'South India', 'Warm-Humid|Hot-Dry|Temperate|Composite', 'Basic', 1, 4, 3, 'High', '2024-Q1', 'Electrical contractor per-point rate; basic density normalized per sqft', 20, 0.4, 10, 0.1, 0.01, 'Medium', 'Wiring lifespan 20-30 years; switch and socket replacement at 10 years', 5, 5, 6, 'Medium', 'Class A', 0, 7, 'No thermal contribution.', 20, 1, 'N/A', 'None', 'All residential configurations', 'Modular switches (Legrand/Anchor/Havells)|2.5 sqmm copper concealed wiring', 'None', 'None', 'Not recommended for owner-occupied homes - extension cords become permanent fixtures', 'Basic point density leads to permanent use of extension cords and power strips which are a fire risk. Adding points later requires wall chasing through finished plaster at Rs 2000-4000 per point.', 'Warning', 'IS 732; NBC 2016', 'Basic point density was adequate when a bedroom had a light a fan and a clock. In 2024 a typical South India bedroom has a phone charger tablet charger laptop AC unit TV point and reading lamp. Two sockets for all of this means permanent multi-socket extension cords which are the leading cause of residential electrical fires. I see this mistake repeatedly in rental construction where the landlord minimises upfront cost and the tenant lives with extension cord tangles for 10 years. Adding a socket point later requires chasing a channel in a plastered finished wall routing conduit connecting to the distribution board and replastering - total cost Rs 2500-4000 per point. Planning adequate points costs maybe Rs 500-800 per point during construction. The math is obvious.', 'Lowest electrical installation cost|Meets NBC minimum requirements', 'Insufficient for modern home usage|Leads to permanent extension cord use - fire risk|Adding points later costs 4-6x more|Not recommended for owner-occupied homes', 'Basic points - 1-2 sockets per room. Not recommended for owner-occupied homes. Extension cord dependency is a fire risk.', 'Active', 'None', 'AI') ON CONFLICT (component_id) DO NOTHING;
INSERT INTO components (component_id, category_name, subcategory_name, name, display_name, description, region, climate_zone, spectrum_position, sort_order, base_cost_per_sqft_inr, installation_cost_per_sqft_inr, cost_confidence, cost_last_updated, cost_source_notes, expected_lifespan_years, replacement_cost_factor, major_maintenance_cycle_years, major_maintenance_cost_factor, annual_minor_maint_factor, maintenance_complexity, lifecycle_source_notes, thermal_resistance_score, acoustic_score, durability_score, moisture_resistance, fire_rating, energy_impact_modifier, accessibility_score, thermal_source_notes, max_floors_supported, min_floors_required, max_span_supported_m, incompatible_with, compatible_with, requires_component, climate_restrictions, hard_block_rule, advisory_rule, advisory_message, advisory_severity, constraint_source_notes, ai_advisory_notes, pros, cons, tooltip_detail, status, verify_flags, data_filled_by) VALUES ('EPOINTS-002', 'Systems', 'Electrical Points', 'points_standard', 'Standard Point Density', 'Standard electrical outlet density for residential use. 3-4 power sockets per bedroom, TV point, 1 data/LAN point per room, dedicated kitchen appliance points, 2 sockets per bathroom. Adequate for comfortable modern residential use.', 'South India', 'Warm-Humid|Hot-Dry|Temperate|Composite', 'Intermediate', 2, 8, 5, 'High', '2024-Q1', 'Electrical contractor per-point rate; standard density normalized per sqft', 20, 0.4, 10, 0.08, 0.008, 'Low', 'Wiring lifespan 20-30 years', 5, 5, 7, 'Medium', 'Class A', 0, 9, 'No thermal contribution.', 20, 1, 'N/A', 'None', 'All residential configurations', 'Legrand/Havells/Anchor modular switches|2.5-4 sqmm copper wiring|LAN conduit in each room', 'None', 'None', 'None', '', '', 'IS 732; NBC 2016', 'Standard point density is the minimum I recommend for any owner-occupied home and it covers most needs without over-engineering. Three to four sockets per bedroom means you can have the AC phone charger bedside lamp and one additional device without extension cords. The LAN data point in each room is increasingly important even in an era of WiFi because wired connections are more reliable for work-from-home setups and smart TV streaming. Run cat6 conduit in every room even if you only connect data points in the study initially - the incremental cost of the conduit is trivial and it saves the disruption of adding it later. Include dedicated kitchen appliance circuits - microwave mixer grinder and dishwasher on separate circuits prevents tripping when multiple appliances run simultaneously.', 'Adequate for comfortable modern residential use|No extension cords needed|LAN points future-proof|Good balance of cost and functionality|Standard for most contractor quotations', 'Insufficient for home office or home automation|No USB charging points built in|Data conduit may be omitted if not specified clearly', 'Standard density - 3-4 sockets/room plus TV and LAN points. Best default for owner-occupied homes.', 'Active', 'None', 'AI') ON CONFLICT (component_id) DO NOTHING;
INSERT INTO components (component_id, category_name, subcategory_name, name, display_name, description, region, climate_zone, spectrum_position, sort_order, base_cost_per_sqft_inr, installation_cost_per_sqft_inr, cost_confidence, cost_last_updated, cost_source_notes, expected_lifespan_years, replacement_cost_factor, major_maintenance_cycle_years, major_maintenance_cost_factor, annual_minor_maint_factor, maintenance_complexity, lifecycle_source_notes, thermal_resistance_score, acoustic_score, durability_score, moisture_resistance, fire_rating, energy_impact_modifier, accessibility_score, thermal_source_notes, max_floors_supported, min_floors_required, max_span_supported_m, incompatible_with, compatible_with, requires_component, climate_restrictions, hard_block_rule, advisory_rule, advisory_message, advisory_severity, constraint_source_notes, ai_advisory_notes, pros, cons, tooltip_detail, status, verify_flags, data_filled_by) VALUES ('EPOINTS-003', 'Systems', 'Electrical Points', 'points_premium', 'Premium Point Density', 'Premium electrical outlet density with home automation provision. 5+ power sockets per room, USB charging outlets, LAN and TV points in all rooms, dedicated home office circuits, EV conduit to parking, provisions for home automation control switches, and outdoor weatherproof points.', 'South India', 'Warm-Humid|Hot-Dry|Temperate|Composite', 'Premium', 3, 16, 9, 'Medium', '2024-Q1', 'Premium point density electrician rates Bangalore 2024; Legrand Arteor/Schneider range; normalized per sqft', 20, 0.3, 10, 0.05, 0.005, 'Low', 'Premium modular switches 15-20 year lifespan; wiring 25+ years', 5, 5, 8, 'Medium', 'Class A', 0.05, 10, 'No thermal contribution.', 20, 1, 'N/A', 'None', 'All residential configurations|Home automation systems|Home office setups', 'Legrand Arteor or Schneider Vivace premium modular switches|Cat6 LAN outlets|USB charging outlets|Home automation conduit (4-way corrugated)|EV conduit to parking', 'None', 'None', 'Plan home automation conduit separately from power conduit for future KNX/Modbus control', 'If home automation is planned, route a separate 4-way corrugated conduit from each switch box back to a central control panel location. Mixing automation wiring in power conduit causes interference.', 'Warning', 'IS 732; KNX Association guidelines', 'Premium point density pays for itself in lifestyle quality and in the complete elimination of the wire management problem that plagues Indian homes. When every bedroom has 5-6 sockets plus built-in USB outlets plus a LAN point there is simply no need for extension cords anywhere and the visual cleanliness of the space is dramatically better. The home automation conduit provision is the element most commonly forgotten - if you ever want smart switches smart lighting or a KNX home automation system in the future you need a separate conduit from each switch position back to a central location for the control wiring. This conduit costs Rs 8000-12000 to lay during construction and Rs 80000+ to add later through finished walls. Even if you have no immediate plans for home automation lay the conduit - it costs almost nothing as part of the overall electrical work.', 'Maximum convenience - no extension cords anywhere|Future-ready for EV and home automation|USB outlets built in|Premium switch aesthetics|Home office and work-from-home ready|Best for premium construction', 'Highest electrical installation cost|Requires detailed planning before construction|Home automation conduit often forgotten - specify clearly|Over-specified for basic residential', 'Premium points - 5+ sockets/room plus USB, LAN, home automation conduit. Lay home automation conduit separately from power.', 'Active', 'None', 'AI') ON CONFLICT (component_id) DO NOTHING;
INSERT INTO components (component_id, category_name, subcategory_name, name, display_name, description, region, climate_zone, spectrum_position, sort_order, base_cost_per_sqft_inr, installation_cost_per_sqft_inr, cost_confidence, cost_last_updated, cost_source_notes, expected_lifespan_years, replacement_cost_factor, major_maintenance_cycle_years, major_maintenance_cost_factor, annual_minor_maint_factor, maintenance_complexity, lifecycle_source_notes, thermal_resistance_score, acoustic_score, durability_score, moisture_resistance, fire_rating, energy_impact_modifier, accessibility_score, thermal_source_notes, max_floors_supported, min_floors_required, max_span_supported_m, incompatible_with, compatible_with, requires_component, climate_restrictions, hard_block_rule, advisory_rule, advisory_message, advisory_severity, constraint_source_notes, ai_advisory_notes, pros, cons, tooltip_detail, status, verify_flags, data_filled_by) VALUES ('RWPL-001', 'Systems', 'Rainwater Plumbing', 'rainwater_plumbing_combined', 'Combined Roof + Waste Pipes', 'Single drainage system combining roof rainwater discharge with household wastewater. Simplest and cheapest plumbing approach. Cannot be used with rainwater harvesting systems as collected water would be contaminated with grey water.', 'South India', 'Warm-Humid|Hot-Dry|Temperate|Composite', 'Basic', 1, 2, 1, 'High', '2024-Q1', 'Combined drain plumbing normalized per sqft; Karnataka PWD SOR 2024-25 reference', 25, 0.5, 10, 0.08, 0.005, 'Low', 'SWR PVC pipe lifespan 25-30 years', 5, 5, 6, 'High', 'Non-Rated', 0, 10, 'No thermal contribution.', 20, 1, 'N/A', 'Rainwater harvesting systems (C6)|Grey water reuse', 'Plots without RWH requirement', 'SWR PVC pipes|Gully traps|Inspection chambers', 'Not acceptable for plots where BBMP mandates RWH (above 1200 sqft in most Bangalore layouts).', 'None', 'Not compatible with any rainwater harvesting system - incompatible with C6 RWH decisions', 'If you have selected a rainwater harvesting system (C6), you cannot use combined plumbing. Separate roof drain pipes are required to collect clean rainwater separately from grey water.', 'Warning', 'BBMP Rainwater Harvesting Bye-laws; TNPCB regulations', 'Combined plumbing made sense when rainwater harvesting was not mandatory and water was not scarce but that is no longer the situation in most South India cities. BBMP has made rainwater harvesting mandatory for all plots above 1200 sqft in Bangalore and a combined drainage system makes it technically impossible to implement RWH because the rooftop water is mixed with wastewater. If you know that you will eventually do RWH - and you should because the BBMP occupancy certificate increasingly requires it - then installing separate pipes from the start costs a few thousand rupees more whereas retrofitting separate downpipes after construction requires extensive work breaking out plastered walls. I recommend separate pipes for all new construction regardless of current RWH plans.', 'Lowest drainage cost|Simple installation|No maintenance of separate systems', 'Cannot be used with any RWH system|Not BBMP compliant for plots above 1200 sqft|Wastes rooftop rainwater to sewer|Retrofit is expensive and disruptive', 'Combined rainwater and waste pipes. Cheapest but incompatible with any rainwater harvesting. Not BBMP compliant for large plots.', 'Active', 'None', 'AI') ON CONFLICT (component_id) DO NOTHING;
INSERT INTO components (component_id, category_name, subcategory_name, name, display_name, description, region, climate_zone, spectrum_position, sort_order, base_cost_per_sqft_inr, installation_cost_per_sqft_inr, cost_confidence, cost_last_updated, cost_source_notes, expected_lifespan_years, replacement_cost_factor, major_maintenance_cycle_years, major_maintenance_cost_factor, annual_minor_maint_factor, maintenance_complexity, lifecycle_source_notes, thermal_resistance_score, acoustic_score, durability_score, moisture_resistance, fire_rating, energy_impact_modifier, accessibility_score, thermal_source_notes, max_floors_supported, min_floors_required, max_span_supported_m, incompatible_with, compatible_with, requires_component, climate_restrictions, hard_block_rule, advisory_rule, advisory_message, advisory_severity, constraint_source_notes, ai_advisory_notes, pros, cons, tooltip_detail, status, verify_flags, data_filled_by) VALUES ('RWPL-002', 'Systems', 'Rainwater Plumbing', 'rainwater_plumbing_separate', 'Separate Roof Drain Pipes', 'Dedicated SWR PVC downpipes from roof to ground for rainwater, completely separate from the household wastewater drainage system. Enables rainwater harvesting by routing clean roof water to sump or recharge pit. Standard specification for BBMP compliance.', 'South India', 'Warm-Humid|Hot-Dry|Temperate|Composite', 'Intermediate', 2, 5, 3, 'High', '2024-Q1', 'Separate SWR downpipe addition cost; Bangalore plumber rates 2024; normalized per sqft', 25, 0.5, 10, 0.06, 0.005, 'Low', 'SWR PVC pipe lifespan 25-30 years', 5, 5, 7, 'High', 'Non-Rated', 0.1, 10, 'No thermal contribution.', 20, 1, 'N/A', 'None', 'Rainwater harvesting systems (C6)|Recharge pit|Collection tank', '110-160mm SWR PVC downpipes|First flush diverter|Gutter or parapet spout at roof|Inspection chamber at base', 'In high rainfall areas above 1500mm annual size drainpipes adequately for peak monsoon flow.', 'None', 'First flush diverter mandatory to exclude initial dirty runoff from storage', 'The first 1-2mm of rainfall after a dry period washes dust, bird droppings and pollutants from the roof surface. A first flush diverter valve automatically discards this initial flow and then routes clean water to storage.', 'Warning', 'BBMP RWH Bye-laws; IS 15797', 'Separate downpipes are the standard I recommend for all new construction in Bangalore regardless of current RWH plans because once the plaster goes on adding separate downpipes requires breaking channel tracks in finished walls which is expensive and messy. The 110mm SWR pipes run from the roof outlets down the external wall face typically tucked into the plinth junction and terminate at an inspection chamber at ground level from where they go to the recharge pit or sump. The first flush diverter is a cheap but important accessory - it is a simple valve that diverts the first 20-30 litres of roof runoff to waste because this water contains the accumulated dust and bird droppings from the dry period. After the initial flush is diverted the valve closes and clean water flows to your storage. Without this the first heavy rain after summer puts a very dirty load into your sump.', 'BBMP compliant for plots above 1200 sqft|Enables rainwater harvesting|Clean water separation|Marginal cost over combined system|First flush diverter improves harvested water quality', 'Higher cost than combined system|Slightly more complex installation|Requires first flush diverter for clean harvesting|Separate inspection chambers needed', 'Separate roof drainpipes. Standard for BBMP compliance and RWH. Install first flush diverter. Do during construction not after.', 'Active', 'None', 'AI') ON CONFLICT (component_id) DO NOTHING;
INSERT INTO components (component_id, category_name, subcategory_name, name, display_name, description, region, climate_zone, spectrum_position, sort_order, base_cost_per_sqft_inr, installation_cost_per_sqft_inr, cost_confidence, cost_last_updated, cost_source_notes, expected_lifespan_years, replacement_cost_factor, major_maintenance_cycle_years, major_maintenance_cost_factor, annual_minor_maint_factor, maintenance_complexity, lifecycle_source_notes, thermal_resistance_score, acoustic_score, durability_score, moisture_resistance, fire_rating, energy_impact_modifier, accessibility_score, thermal_source_notes, max_floors_supported, min_floors_required, max_span_supported_m, incompatible_with, compatible_with, requires_component, climate_restrictions, hard_block_rule, advisory_rule, advisory_message, advisory_severity, constraint_source_notes, ai_advisory_notes, pros, cons, tooltip_detail, status, verify_flags, data_filled_by) VALUES ('RWPL-003', 'Systems', 'Rainwater Plumbing', 'rainwater_plumbing_dual_greywater', 'Dual System with Grey Water Reuse', 'Full dual-pipe drainage system separating roof rainwater, bathroom grey water (washbasin, shower), and blackwater (WC). Grey water is treated and reused for toilet flushing and garden irrigation. Full BBMP compliance. Maximum water conservation system.', 'South India', 'Warm-Humid|Hot-Dry|Temperate|Composite', 'Premium', 3, 12, 8, 'Medium', '2024-Q1', 'Dual drain system plus grey water treatment unit; South India specialist plumber rates 2024; normalized per sqft', 20, 0.6, 5, 0.15, 0.015, 'High', 'Grey water treatment system lifespan 15-20 years; pipe system 25 years', 5, 5, 7, 'High', 'Non-Rated', 0.2, 10, 'No thermal contribution.', 20, 1, 'N/A', 'None', 'Full RWH system (C6 RWH-004)|IGBC Green Homes compliance', 'Separate grey water collection pipes|Grey water treatment unit (biofilter or constructed wetland)|Treated water storage|Garden or flushing reuse connection|BBMP discharge approval', 'Most valuable in water-scarce cities (Bangalore, Hyderabad). Less critical in high-rainfall zones with abundant groundwater.', 'None', 'Grey water treatment system requires regular maintenance - not suitable for low-maintenance households', 'A grey water reuse system requires monthly maintenance of filter media and annual inspection of the treatment unit. This system is not suitable for households that cannot commit to this maintenance schedule.', 'Warning', 'BBMP grey water regulations; IS 16095; CPHEEO Manual', 'Dual drainage with grey water reuse is the gold standard for water conservation in South India and makes particularly good sense in Bangalore where water scarcity is acute and BWSSB has been rationing supply in many areas. A typical South India household generates 80-100 litres per person per day of grey water from showers washbasins and kitchen sinks. Treated and reused for toilet flushing and garden irrigation this eliminates 30-40 percent of total water demand. The system requires a grey water treatment unit - either a biofilter or a constructed wetland filter bed - and separate collection pipes that must be installed during construction since retrofitting is essentially impossible without major disruption. The ongoing maintenance requirement is real: the filter media needs cleaning and replacement every 3-6 months and the treatment unit needs an annual inspection. If your household will not commit to this maintenance the system will smell and fail within a year.', 'Maximum water conservation - 30-40% demand reduction|Full BBMP and IGBC compliance|Reduces BWSSB water bill significantly|Environmental responsibility|Good for water-scarce locations', 'Highest cost and complexity|Must be installed during construction - retrofitting not practical|Regular maintenance mandatory - monthly filter cleaning|Requires household commitment to maintenance|Complex plumbing requires specialist installer', 'Dual grey water reuse system. Maximum water saving but requires monthly maintenance commitment. Install during construction only.', 'Active', 'None', 'AI') ON CONFLICT (component_id) DO NOTHING;
INSERT INTO components (component_id, category_name, subcategory_name, name, display_name, description, region, climate_zone, spectrum_position, sort_order, base_cost_per_sqft_inr, installation_cost_per_sqft_inr, cost_confidence, cost_last_updated, cost_source_notes, expected_lifespan_years, replacement_cost_factor, major_maintenance_cycle_years, major_maintenance_cost_factor, annual_minor_maint_factor, maintenance_complexity, lifecycle_source_notes, thermal_resistance_score, acoustic_score, durability_score, moisture_resistance, fire_rating, energy_impact_modifier, accessibility_score, thermal_source_notes, max_floors_supported, min_floors_required, max_span_supported_m, incompatible_with, compatible_with, requires_component, climate_restrictions, hard_block_rule, advisory_rule, advisory_message, advisory_severity, constraint_source_notes, ai_advisory_notes, pros, cons, tooltip_detail, status, verify_flags, data_filled_by) VALUES ('WH-001', 'Systems', 'Water Heating', 'water_heating_electric_geyser', 'Electric Storage Geyser', 'Electric resistance water heater (storage geyser) of 15-25 litre capacity per bathroom. Most common water heating solution in India. Low upfront cost, high running cost. Energy efficiency depends on BEE star rating.', 'South India', 'Warm-Humid|Hot-Dry|Temperate|Composite', 'Basic', 1, 3, 2, 'High', '2024-Q1', 'Racold/Havells/AO Smith geyser market rate 2024; normalized per sqft built-up area', 8, 0.9, 3, 0.15, 0.02, 'Low', 'Geyser heating element lifespan 6-10 years; tank lifespan 10-15 years', 5, 5, 5, 'Medium', 'Non-Rated', -0.2, 10, '2-3 kWh electricity per day per bathroom. Highest energy consumption of all heating options.', 20, 1, 'N/A', 'None', 'All bathroom configurations', '15A socket with ISI mark|Separate MCB for each geyser|Earth leakage protection (ELCB/RCCB)', 'None', 'None', 'Mandatory ELCB (Earth Leakage Circuit Breaker) for all bathroom geyser circuits', 'Geyser without ELCB protection is a serious electrical safety risk in wet bathroom conditions. Every geyser circuit must have ELCB/RCCB protection. This is a legal requirement under NBC.', 'Strong-Warning', 'NBC 2016; IS 8884; BEE star rating', 'Electric geysers are the default because they are cheapest upfront and every electrician and plumber knows how to install them but the running cost story is poor. A 15-litre geyser draws 2 kW and takes 15-20 minutes to heat a tank - that is 0.5 kWh per hot bath. For a family of 4 taking daily hot baths that is 2 kWh per day or roughly Rs 12-16 per day at BESCOM rates totalling Rs 4500-5500 per year just for water heating. Over 20 years that is Rs 90000-110000 in electricity costs. A solar water heater at Rs 25000 upfront pays back in 4-5 years and then provides effectively free hot water for 20+ years. The only advantage of the electric geyser in South India is that it is the backup for cloudy monsoon periods. I recommend electric geysers only as backup to solar or heat pump systems not as the primary water heating choice.', 'Lowest upfront cost|Simple installation|Wide availability and service|No weather dependency|Instant hot water after heat-up period', 'Highest running cost of all options|2 kW power draw per unit|Safety risk without ELCB protection|8-10 year lifespan|Not suitable as primary heater for South India', 'Electric geyser. Lowest upfront cost, highest running cost. ELCB mandatory. Use as backup to solar, not primary heating.', 'Active', 'None', 'AI') ON CONFLICT (component_id) DO NOTHING;
INSERT INTO components (component_id, category_name, subcategory_name, name, display_name, description, region, climate_zone, spectrum_position, sort_order, base_cost_per_sqft_inr, installation_cost_per_sqft_inr, cost_confidence, cost_last_updated, cost_source_notes, expected_lifespan_years, replacement_cost_factor, major_maintenance_cycle_years, major_maintenance_cost_factor, annual_minor_maint_factor, maintenance_complexity, lifecycle_source_notes, thermal_resistance_score, acoustic_score, durability_score, moisture_resistance, fire_rating, energy_impact_modifier, accessibility_score, thermal_source_notes, max_floors_supported, min_floors_required, max_span_supported_m, incompatible_with, compatible_with, requires_component, climate_restrictions, hard_block_rule, advisory_rule, advisory_message, advisory_severity, constraint_source_notes, ai_advisory_notes, pros, cons, tooltip_detail, status, verify_flags, data_filled_by) VALUES ('WH-002', 'Systems', 'Water Heating', 'water_heating_gas_geyser', 'Gas Geyser (LPG/PNG)', 'Instantaneous gas water heater using LPG or Piped Natural Gas (PNG). Provides continuous hot water without storage. Lower running cost than electric geyser. Suitable where PNG connection is available (expanding in Bangalore and Chennai).', 'South India', 'Warm-Humid|Hot-Dry|Temperate|Composite', 'Intermediate', 2, 5, 3, 'Medium', '2024-Q1', 'Gas geyser market rate 2024; normalized per sqft', 12, 0.8, 5, 0.1, 0.01, 'Medium', 'Gas geyser heat exchanger lifespan 10-15 years', 5, 5, 6, 'Medium', 'Non-Rated', -0.1, 9, 'Lower carbon emission per unit heat than electric geyser where grid is coal-powered.', 20, 1, 'N/A', 'None', 'All bathroom configurations|PNG or LPG connection', 'PNG connection (preferred) or LPG cylinder|Gas pipe with ball valve|Flue vent to outside|CO detector', 'None', 'None', 'Gas geyser must be installed with external flue and never in an enclosed bathroom without ventilation', 'Gas geysers produce combustion gases including CO. Installation in an enclosed bathroom without proper external flue ventilation is a fatal risk. External wall installation with flue mandatory.', 'Strong-Warning', 'IS 6993; BIS gas appliance safety; NBC 2016', 'Gas geysers make sense in areas where Piped Natural Gas connection is available and the running cost advantage over electric is real - PNG at current rates gives hot water at roughly 40-50 percent the cost of electric heating. The PNG network is expanding in Bangalore through GAIL and in Chennai through IGL. The safety requirement that cannot be compromised is the external flue - gas combustion produces carbon monoxide and a gas geyser in an enclosed bathroom without a proper outside flue has killed people. The geyser must be mounted on an external wall with the flue pipe going directly outside. Never install in a bathroom with no external wall. Install a CO detector as well. For LPG operation the running cost advantage narrows considerably because LPG is significantly more expensive than PNG.', 'Lower running cost than electric (PNG)|Instant continuous hot water - no storage needed|No electricity dependency|Better than electric for large families|Faster flow rate', 'PNG connection required for cost advantage|Safety risk without external flue - fatal if incorrectly installed|CO detector mandatory|LPG variant loses cost advantage|Not suitable for enclosed bathrooms', 'Gas geyser. Lower cost with PNG. External flue and CO detector mandatory. Never install in enclosed bathroom.', 'Active', 'None', 'AI') ON CONFLICT (component_id) DO NOTHING;
INSERT INTO components (component_id, category_name, subcategory_name, name, display_name, description, region, climate_zone, spectrum_position, sort_order, base_cost_per_sqft_inr, installation_cost_per_sqft_inr, cost_confidence, cost_last_updated, cost_source_notes, expected_lifespan_years, replacement_cost_factor, major_maintenance_cycle_years, major_maintenance_cost_factor, annual_minor_maint_factor, maintenance_complexity, lifecycle_source_notes, thermal_resistance_score, acoustic_score, durability_score, moisture_resistance, fire_rating, energy_impact_modifier, accessibility_score, thermal_source_notes, max_floors_supported, min_floors_required, max_span_supported_m, incompatible_with, compatible_with, requires_component, climate_restrictions, hard_block_rule, advisory_rule, advisory_message, advisory_severity, constraint_source_notes, ai_advisory_notes, pros, cons, tooltip_detail, status, verify_flags, data_filled_by) VALUES ('WH-003', 'Systems', 'Water Heating', 'water_heating_solar', 'Solar Water Heater', 'Flat plate or evacuated tube solar water heater system. 100-200 litre capacity on rooftop. Best suited for South India where annual solar radiation is very high (5.5-6.5 kWh/sqm/day). 4-5 year payback, effective for 20+ years.', 'South India', 'Warm-Humid|Hot-Dry|Temperate', 'Performance', 3, 12, 6, 'High', '2024-Q1', 'Racold/AO Smith/V-Guard solar system market rate Bangalore/Chennai 2024; 150L ETC system; normalized per sqft', 20, 0.6, 5, 0.1, 0.005, 'Low', 'MNRE solar water heater performance data; 20-25 year system lifespan; collector 15 years', 5, 5, 8, 'High', 'Non-Rated', 0.2, 9, 'Provides 70-80% of annual water heating from solar. Backup geyser needed for monsoon months only.', 20, 1, 'N/A', 'None', 'All bathroom configurations|Backup electric geyser', 'Rooftop space (2-3 sqm per 100L)|Insulated storage tank|Backup electric element for monsoon|MNRE approved system', 'Best performance in Hot-Dry and Warm-Humid zones. Evacuated tube collector performs better in cloudy conditions than flat plate.', 'None', 'Use evacuated tube collector (ETC) not flat plate in high-humidity zones for better monsoon performance', 'In high-humidity zones like coastal Karnataka and Kerala evacuated tube collectors perform significantly better on partly cloudy days than flat plate collectors. Specify ETC type for coastal and high-rainfall locations.', 'Warning', 'MNRE JNNSM guidelines; IS 12933', 'Solar water heating is the best financial decision you can make for water heating in South India. Bangalore gets 300+ sunny days a year and solar radiation is excellent even in the so-called rainy season because it is rarely fully overcast for more than 2-3 consecutive days. A 150 litre ETC solar water heater system from Racold or AO Smith costs around Rs 18000-22000 installed and eliminates 70-80 percent of your water heating electricity bill. The payback is 4-5 years and then you have free hot water for 15-20 more years. The only maintenance needed is an annual cleaning of the collector tubes which takes 30 minutes. The backup electric element in the tank handles the monsoon cloudy periods. Get an MNRE approved system to be eligible for the BESCOM solar subsidy. Install it before your roof is finished because routing the pipes is much easier before the false ceiling is done.', '4-5 year payback then free hot water|Best for South India solar radiation|20 year system lifespan|70-80% energy saving|MNRE subsidy eligible|ECBC compliance pathway', 'Requires rooftop space and structural capacity|Performance reduced in cloudy monsoon periods (backup needed)|Roof plumbing must be planned early|Slightly less effective in very high rainfall zones', 'Solar water heater. Best choice for South India. 4-5 year payback. Use ETC type. Install before roof finishing.', 'Active', 'None', 'AI') ON CONFLICT (component_id) DO NOTHING;
INSERT INTO components (component_id, category_name, subcategory_name, name, display_name, description, region, climate_zone, spectrum_position, sort_order, base_cost_per_sqft_inr, installation_cost_per_sqft_inr, cost_confidence, cost_last_updated, cost_source_notes, expected_lifespan_years, replacement_cost_factor, major_maintenance_cycle_years, major_maintenance_cost_factor, annual_minor_maint_factor, maintenance_complexity, lifecycle_source_notes, thermal_resistance_score, acoustic_score, durability_score, moisture_resistance, fire_rating, energy_impact_modifier, accessibility_score, thermal_source_notes, max_floors_supported, min_floors_required, max_span_supported_m, incompatible_with, compatible_with, requires_component, climate_restrictions, hard_block_rule, advisory_rule, advisory_message, advisory_severity, constraint_source_notes, ai_advisory_notes, pros, cons, tooltip_detail, status, verify_flags, data_filled_by) VALUES ('WH-004', 'Systems', 'Water Heating', 'water_heating_heat_pump', 'Heat Pump Water Heater', 'Heat pump water heater using ambient air as heat source. COP (Coefficient of Performance) of 3-4 meaning 3-4 kWh of heat for every 1 kWh of electricity. 60-70% energy saving versus electric geyser. Premium upfront cost with 5-7 year payback.', 'South India', 'Warm-Humid|Hot-Dry|Temperate|Composite', 'Premium', 4, 20, 10, 'Medium', '2024-Q1', 'Daikin/Racold heat pump market rate South India 2024; normalized per sqft', 15, 0.7, 3, 0.12, 0.01, 'Medium', 'Heat pump compressor lifespan 12-18 years; tank 15-20 years', 5, 4, 7, 'Medium', 'Non-Rated', 0.3, 9, 'COP 3-4: delivers 3-4 kWh heat per kWh electricity consumed. 60-70% saving vs resistive geyser.', 20, 1, 'N/A', 'None', 'All bathroom configurations', 'Outdoor unit location with good air circulation|Condensate drain|15A dedicated circuit|Annual refrigerant check service', 'Performance reduces below 10°C ambient - not an issue for most South India locations. Best in warm humid conditions.', 'None', 'Install in location with good air circulation - enclosed spaces reduce performance significantly', 'Heat pump water heaters need good ambient air flow around the unit. Installing in an enclosed utility room or store restricts airflow and significantly reduces efficiency. Place in a ventilated external location.', 'Warning', 'IS 15195; heat pump manufacturer installation guidelines', 'Heat pump water heaters are the premium technology choice and they make particularly good sense in South India because the warm ambient temperatures year-round give the heat pump excellent operating conditions. A heat pump extracts heat from the ambient air and transfers it to water rather than generating heat from electricity directly - this gives a COP of 3 to 4 meaning you get 3 to 4 kilowatts of heat for every kilowatt of electricity. Compared to a 2 kW resistive geyser a heat pump does the same job using 500-700 watts. Over 20 years this difference pays back the premium cost approximately 5 times. The downside is that it requires annual maintenance of the refrigerant circuit - you need a trained HVAC technician similar to what you use for a split AC. Also the unit makes a sound similar to a small AC outdoor unit so it cannot be placed directly outside a bedroom window. For premium construction where energy efficiency is a priority and the owner wants to reduce both electricity bills and carbon footprint the heat pump is the clear choice.', '60-70% energy saving versus electric geyser|Best for warm South India ambient conditions|Works at all hours unlike solar|Premium eco-friendly choice|Long lifespan|ECBC compliance pathway', 'Highest upfront cost|Annual refrigerant maintenance needed|Makes noise like AC outdoor unit|Enclosed installation reduces performance|5-7 year payback longer than solar', 'Heat pump water heater. 60-70% energy saving. Place in ventilated location. Annual refrigerant service needed. 5-7 year payback.', 'Active', 'None', 'AI') ON CONFLICT (component_id) DO NOTHING;
INSERT INTO components (component_id, category_name, subcategory_name, name, display_name, description, region, climate_zone, spectrum_position, sort_order, base_cost_per_sqft_inr, installation_cost_per_sqft_inr, cost_confidence, cost_last_updated, cost_source_notes, expected_lifespan_years, replacement_cost_factor, major_maintenance_cycle_years, major_maintenance_cost_factor, annual_minor_maint_factor, maintenance_complexity, lifecycle_source_notes, thermal_resistance_score, acoustic_score, durability_score, moisture_resistance, fire_rating, energy_impact_modifier, accessibility_score, thermal_source_notes, max_floors_supported, min_floors_required, max_span_supported_m, incompatible_with, compatible_with, requires_component, climate_restrictions, hard_block_rule, advisory_rule, advisory_message, advisory_severity, constraint_source_notes, ai_advisory_notes, pros, cons, tooltip_detail, status, verify_flags, data_filled_by) VALUES ('UPS-001', 'Systems', 'UPS Provision', 'ups_no_provision', 'No UPS Provision', 'No dedicated inverter or UPS circuit wiring. All circuits powered from BESCOM/TNEB grid only. Only suitable for areas with fully reliable 24/7 power supply and no planned inverter or home battery system.', 'South India', 'Warm-Humid|Hot-Dry|Temperate|Composite', 'Basic', 1, 0, 0, 'High', '2024-Q1', 'No additional cost', 25, 0.5, 0, 0, 0, 'Low', 'No UPS wiring - standard electrical lifespan applies', 5, 5, 6, 'Medium', 'Class A', 0, 10, 'No thermal contribution.', 20, 1, 'N/A', 'Future inverter installation without rewiring', 'All electrical systems', 'None', 'None', 'None', 'Not recommended for most South India locations - power cuts of 2-6 hours common in many areas', 'Without UPS wiring provision any future inverter installation requires partial rewiring of the distribution board and dedicated circuit routing - adding Rs 15000-25000 to future installation cost.', 'Warning', 'BESCOM/TNEB outage data', 'No UPS provision made sense when inverters were expensive luxury items and South India power supply was more reliable. In 2024 Bangalore areas outside the CBD still experience 2-4 hour scheduled power cuts in summer and unscheduled outages during monsoon. Without any UPS wiring the inverter can only power the circuits it is hardwired to which requires partial rewiring of the distribution board after construction. The DB board rewiring alone costs Rs 8000-12000 and if separate UPS circuit conduits are needed through plastered walls the total can reach Rs 20000-30000. The pre-provision cost during construction is Rs 2000-3000 for an extra conduit and changeover switch position in the DB. This is a straightforward economic decision.', 'No upfront cost|Simplest electrical installation', 'No power backup for any circuit|Future inverter addition requires DB rewiring and conduit work|Not suitable for most South India locations with power cuts|Rs 15000-25000 additional cost to add later', 'No UPS wiring. Not recommended for most South India areas. Adding later costs Rs 15000-25000 in rewiring.', 'Active', 'None', 'AI') ON CONFLICT (component_id) DO NOTHING;
INSERT INTO components (component_id, category_name, subcategory_name, name, display_name, description, region, climate_zone, spectrum_position, sort_order, base_cost_per_sqft_inr, installation_cost_per_sqft_inr, cost_confidence, cost_last_updated, cost_source_notes, expected_lifespan_years, replacement_cost_factor, major_maintenance_cycle_years, major_maintenance_cost_factor, annual_minor_maint_factor, maintenance_complexity, lifecycle_source_notes, thermal_resistance_score, acoustic_score, durability_score, moisture_resistance, fire_rating, energy_impact_modifier, accessibility_score, thermal_source_notes, max_floors_supported, min_floors_required, max_span_supported_m, incompatible_with, compatible_with, requires_component, climate_restrictions, hard_block_rule, advisory_rule, advisory_message, advisory_severity, constraint_source_notes, ai_advisory_notes, pros, cons, tooltip_detail, status, verify_flags, data_filled_by) VALUES ('UPS-002', 'Systems', 'UPS Provision', 'ups_essentials_circuit', 'Essentials Circuit (Lights + Fans)', 'Dedicated UPS/inverter circuit for essential loads: all lights, ceiling fans, router, and one TV point per floor. Separate wiring from a changeover switch in the distribution board. Covers 80% of household inconvenience from power cuts at 20% of whole-house backup cost.', 'South India', 'Warm-Humid|Hot-Dry|Temperate|Composite', 'Intermediate', 2, 4, 3, 'High', '2024-Q1', 'Dedicated UPS circuit wiring + changeover switch; Bangalore electrician rates 2024; normalized per sqft', 20, 0.4, 5, 0.05, 0.005, 'Low', 'UPS circuit wiring lifespan 20-25 years; inverter battery replacement every 3-5 years (separate cost)', 5, 5, 7, 'Medium', 'Class A', 0, 10, 'No thermal contribution.', 20, 1, 'N/A', 'None', 'All residential configurations|Tubular/Li-ion inverter battery', 'Changeover switch or ATS in distribution board|Separate 2.5 sqmm copper circuit for lights and fans|Inverter battery space in utility area (minimum 1 sqm)', 'None', 'None', 'Reserve space for inverter battery (minimum 1sqm ventilated area) in utility or store room', 'Lead-acid inverter batteries must be placed in ventilated locations away from living areas as they emit hydrogen gas during charging. Lithium-ion batteries are safer but require adequate space and ventilation. Plan for this space.', 'Warning', 'IS 1651; inverter manufacturer installation guidelines', 'The essentials circuit with a 4-hour battery backup for lights fans and router covers 80 percent of the practical inconvenience from power cuts at 20 percent of the cost of a whole-house backup system. During a typical South India power cut what you actually need to be comfortable is functioning ceiling fans, lights to see by and a working internet router. The AC can wait - running fans makes a significant difference in comfort. The changeover switch in the distribution board is a simple manual or automatic transfer switch that takes 5 minutes to install during the electrical work and costs Rs 800-1500. The conduit for the separate UPS circuit needs to run parallel to the main circuit conduit. Plan the inverter battery location carefully - lead acid batteries emit hydrogen gas during charging and need ventilation away from sleeping areas. A small store room or utility area corner with a 1 sqm footprint is ideal.', 'Covers 80% of power cut inconvenience at low cost|Simple standard installation|All contractors understand this|Easy to scale up battery capacity later|Lights + fans + router - the essential comfort needs', 'Does not support AC or other high-power loads|Battery needs replacement every 3-5 years|Lead acid battery needs ventilated location|Cannot support EV charging', 'Essentials circuit for lights, fans, router. Best value UPS provision. Reserve ventilated 1sqm space for battery.', 'Active', 'None', 'AI') ON CONFLICT (component_id) DO NOTHING;
INSERT INTO components (component_id, category_name, subcategory_name, name, display_name, description, region, climate_zone, spectrum_position, sort_order, base_cost_per_sqft_inr, installation_cost_per_sqft_inr, cost_confidence, cost_last_updated, cost_source_notes, expected_lifespan_years, replacement_cost_factor, major_maintenance_cycle_years, major_maintenance_cost_factor, annual_minor_maint_factor, maintenance_complexity, lifecycle_source_notes, thermal_resistance_score, acoustic_score, durability_score, moisture_resistance, fire_rating, energy_impact_modifier, accessibility_score, thermal_source_notes, max_floors_supported, min_floors_required, max_span_supported_m, incompatible_with, compatible_with, requires_component, climate_restrictions, hard_block_rule, advisory_rule, advisory_message, advisory_severity, constraint_source_notes, ai_advisory_notes, pros, cons, tooltip_detail, status, verify_flags, data_filled_by) VALUES ('UPS-003', 'Systems', 'UPS Provision', 'ups_whole_house_backup', 'Whole-House Backup (All Circuits)', 'All household circuits connected to inverter/battery backup through automatic transfer switch. Includes AC circuits, kitchen appliances, and all power sockets. Premium lithium-ion battery system or large inverter bank. For areas with severe and frequent power cuts.', 'South India', 'Warm-Humid|Hot-Dry|Temperate|Composite', 'Premium', 3, 10, 7, 'Medium', '2024-Q1', 'Full ATS + high-capacity wiring + large battery system; Bangalore specialist rates 2024; normalized per sqft', 15, 0.7, 3, 0.2, 0.015, 'High', 'Li-ion battery 10-15 year lifespan; lead acid 5-7 years for high-cycle whole house use', 5, 5, 8, 'Medium', 'Class A', 0.05, 10, 'No thermal contribution.', 20, 1, 'N/A', 'None', 'All residential configurations|Solar grid-tied system|Li-ion home battery', 'High-capacity ATS or automatic changeover|Heavy gauge wiring for AC circuits|Lithium-ion battery system (preferred)|Dedicated battery room or large utility space|Annual inspection', 'None', 'None', 'Use lithium-ion battery for whole-house backup - lead acid loses capacity rapidly under AC load cycles', 'Whole-house backup with AC inclusion requires Li-ion batteries. Lead-acid batteries lose 30-40% capacity within 2 years when regularly discharged deeply by AC loads. The economics work only with Li-ion.', 'Warning', 'IS 1651; Li-ion battery safety standards; installer guidelines', 'Whole house backup makes genuine sense for plots in areas that have 4-6 hour cuts on a daily basis during summer particularly in some parts of Tamil Nadu and Andhra Pradesh where scheduled load shedding is still a reality. For Bangalore it is generally over-specified as grid reliability has improved significantly in most layouts. The critical technology decision is the battery. If you put lead-acid batteries in a whole-house backup system that regularly runs your 1.5 ton AC for 3-4 hours daily the batteries will be at 60 percent capacity within 18 months and need replacement within 3 years. Lithium-ion batteries handle deep cycling gracefully and last 10-15 years. The upfront cost is 3-4x more than lead acid but the lifecycle cost is lower. If you are also considering solar this system integrates naturally as a home battery storage system combining the backup benefit with solar self-consumption optimisation.', 'Complete backup including AC - no lifestyle change during cuts|Integrates with solar battery storage|Automatic transfer - no manual intervention|Li-ion system lasts 10-15 years', 'Highest cost|Li-ion battery essential (3-4x lead acid cost)|Requires dedicated battery space|Annual maintenance|Overkill for most Bangalore locations with good grid reliability', 'Whole-house backup including AC. Use Li-ion batteries only - lead acid fails rapidly under AC load. High cost but necessary for high-cut areas.', 'Active', 'None', 'AI') ON CONFLICT (component_id) DO NOTHING;
INSERT INTO components (component_id, category_name, subcategory_name, name, display_name, description, region, climate_zone, spectrum_position, sort_order, base_cost_per_sqft_inr, installation_cost_per_sqft_inr, cost_confidence, cost_last_updated, cost_source_notes, expected_lifespan_years, replacement_cost_factor, major_maintenance_cycle_years, major_maintenance_cost_factor, annual_minor_maint_factor, maintenance_complexity, lifecycle_source_notes, thermal_resistance_score, acoustic_score, durability_score, moisture_resistance, fire_rating, energy_impact_modifier, accessibility_score, thermal_source_notes, max_floors_supported, min_floors_required, max_span_supported_m, incompatible_with, compatible_with, requires_component, climate_restrictions, hard_block_rule, advisory_rule, advisory_message, advisory_severity, constraint_source_notes, ai_advisory_notes, pros, cons, tooltip_detail, status, verify_flags, data_filled_by) VALUES ('CWALL-001', 'External', 'Compound Wall', 'compound_wall_live_hedge', 'Live Hedge Boundary', 'Planted live hedge as boundary demarcation using species like Bougainvillea, Duranta, Ixora or Bamboo. Permeable, green, and low-cost. Requires regular trimming. Only provides soft boundary - not a security barrier.', 'South India', 'Warm-Humid|Hot-Dry|Temperate|Composite', 'Basic', 1, 5, 3, 'Medium', '2024-Q1', 'Nursery plant + soil preparation + labour; normalized per sqft of boundary length', 20, 0.4, 0, 0, 0.05, 'Medium', 'Live hedge requires annual trimming and periodic replacement of dead sections', 5, 5, 4, 'High', 'Non-Rated', 0.05, 10, 'Green hedge provides shade - minor thermal benefit on adjacent walls.', 20, 1, 'N/A', 'None', 'All residential configurations', 'Hardy hedge species selection|Irrigation provision|Trimming schedule', 'Select drought-tolerant species for Hot-Dry zones.', 'None', 'Not a security boundary - animals and people can pass through easily', 'A live hedge provides no meaningful security boundary. It is suitable only as an aesthetic demarcation for plots that rely on other security measures or where a formal wall is not required.', 'Warning', 'Local municipal building regulations', 'A live hedge is a beautiful boundary treatment that is common in bungalow layouts and civil station type residential areas but it is not a serious security boundary. It works best as a front garden demarcation combined with a vehicular gate where actual security is provided by the gate and the enclosed compound. For rear and side boundaries where security matters a hedge alone is inadequate. The maintenance requirement is real - an untrimmed Bougainvillea hedge becomes an impenetrable thorny mass that blocks the footpath and irritates neighbours. If you choose a hedge boundary plan for quarterly trimming and a person to do it. Bamboo is my favourite choice for side boundaries as it grows quickly creates a solid visual screen and is very low maintenance once established.', 'Most economical boundary|Green aesthetic - improves neighbourhood appearance|Permeable - allows air flow|Low initial cost|Environmental benefit', 'No security function|Requires regular trimming maintenance|Takes 2-3 years to fully establish|Dead sections need replacement|Cannot support security cameras or lights easily', 'Live hedge boundary. Green and economical. Not a security barrier. Quarterly trimming required.', 'Active', 'None', 'AI') ON CONFLICT (component_id) DO NOTHING;
INSERT INTO components (component_id, category_name, subcategory_name, name, display_name, description, region, climate_zone, spectrum_position, sort_order, base_cost_per_sqft_inr, installation_cost_per_sqft_inr, cost_confidence, cost_last_updated, cost_source_notes, expected_lifespan_years, replacement_cost_factor, major_maintenance_cycle_years, major_maintenance_cost_factor, annual_minor_maint_factor, maintenance_complexity, lifecycle_source_notes, thermal_resistance_score, acoustic_score, durability_score, moisture_resistance, fire_rating, energy_impact_modifier, accessibility_score, thermal_source_notes, max_floors_supported, min_floors_required, max_span_supported_m, incompatible_with, compatible_with, requires_component, climate_restrictions, hard_block_rule, advisory_rule, advisory_message, advisory_severity, constraint_source_notes, ai_advisory_notes, pros, cons, tooltip_detail, status, verify_flags, data_filled_by) VALUES ('CWALL-002', 'External', 'Compound Wall', 'compound_wall_metal_palisade', 'Metal Palisade / Grille Wall', 'Metal palisade or ornamental grille fabricated from MS or tubular steel sections, powder coated. Provides visual boundary and partial security while maintaining visibility. Good modern aesthetic for front boundaries of independent houses.', 'South India', 'Warm-Humid|Hot-Dry|Temperate|Composite', 'Intermediate', 2, 18, 8, 'Medium', '2024-Q1', 'MS palisade fabrication + powder coat; contractor rate Bangalore 2024; normalized per sqft', 15, 0.7, 5, 0.15, 0.02, 'Medium', 'MS palisade powder coat lifespan 8-12 years; repainting every 5-8 years', 5, 3, 6, 'Medium', 'Non-Rated', 0, 10, 'Open boundary - no thermal mass.', 20, 1, 'N/A', 'None', 'All residential configurations|RCC plinth beam base', 'RCC plinth beam as base (150mm minimum)|Post anchor bolts|Powder coat finish|Annual rust inspection', 'In coastal zones use hot-dip galvanised + powder coat or use SS instead of plain MS.', 'None', 'Mount on RCC plinth beam - never directly in soil', 'Metal palisade posts set directly in soil corrode at the buried section within 3-5 years. All posts must be mounted on a concrete plinth beam minimum 150mm above ground with proper anchor bolts.', 'Warning', 'IS 1161; NBC 2016', 'Metal palisade boundaries are popular for front-of-house aesthetics particularly combined with a solid gate because they give visibility and an open feel while still demarcating the property clearly. The corrosion issue is the main challenge - MS steel in South India humidity needs a good quality powder coat finish and in coastal areas you need hot-dip galvanising underneath the powder coat. Never allow the contractor to set palisade posts directly in soil because the buried section corrodes in 3-5 years leaving the posts wobbly and requiring expensive replacement. All posts must sit on a RCC plinth beam with anchor bolts. Budget for repainting every 5-8 years as a maintenance requirement.', 'Modern open aesthetic|Good visibility|Moderate cost|Deters casual trespassers|Allows natural air flow', 'Moderate security - can be climbed|Requires repainting every 5-8 years|Coastal corrosion risk without galvanising|Posts must be on RCC plinth - not in soil', 'Metal palisade. Mount on RCC plinth beam - never in soil. Repaint every 5-8 years. Galvanise before powder coat for coastal areas.', 'Active', 'None', 'AI') ON CONFLICT (component_id) DO NOTHING;
INSERT INTO components (component_id, category_name, subcategory_name, name, display_name, description, region, climate_zone, spectrum_position, sort_order, base_cost_per_sqft_inr, installation_cost_per_sqft_inr, cost_confidence, cost_last_updated, cost_source_notes, expected_lifespan_years, replacement_cost_factor, major_maintenance_cycle_years, major_maintenance_cost_factor, annual_minor_maint_factor, maintenance_complexity, lifecycle_source_notes, thermal_resistance_score, acoustic_score, durability_score, moisture_resistance, fire_rating, energy_impact_modifier, accessibility_score, thermal_source_notes, max_floors_supported, min_floors_required, max_span_supported_m, incompatible_with, compatible_with, requires_component, climate_restrictions, hard_block_rule, advisory_rule, advisory_message, advisory_severity, constraint_source_notes, ai_advisory_notes, pros, cons, tooltip_detail, status, verify_flags, data_filled_by) VALUES ('CWALL-003', 'External', 'Compound Wall', 'compound_wall_precast', 'Precast Concrete Panel Wall', 'Precast concrete compound wall panels installed between RCC columns. Faster construction than brick masonry. Consistent quality, good durability, and economical at scale. Growing adoption across South India residential and commercial.', 'South India', 'Warm-Humid|Hot-Dry|Temperate|Composite', 'Standard', 3, 25, 10, 'Medium', '2024-Q1', 'Precast panel supply and erection; South India precast manufacturer rates 2024; normalized per sqft', 30, 0.5, 15, 0.08, 0.005, 'Low', 'Precast concrete panel lifespan 25-35 years; painting every 10 years', 5, 6, 7, 'High', 'Class A', 0, 10, 'Concrete panels provide moderate thermal mass and privacy.', 20, 1, 'N/A', 'None', 'All residential configurations', 'RCC column posts at 2.5-3m centres|Foundation for columns|Panel transport and erection crane or manual', 'None', 'None', 'None', '', '', 'IS 15917; precast concrete specification', 'Precast concrete panel walls have become the go-to choice for compound walls in new layouts across Bangalore and Hyderabad because erection is fast - a 30-metre compound wall goes up in one day compared to a week for brick masonry and the quality is consistent because the panels are factory manufactured. The RCC column spacing determines the panel size - typically 2.5-3 metre spans. The aesthetic is clean and modern and can be painted in any colour. The main limitation is the relatively plain visual appearance compared to stone or brick which some clients find too industrial for a residential frontage.', 'Fast installation - 1-2 days for typical compound wall|Factory quality consistency|Good durability - 30 year lifespan|Economical|Maintenance-free except painting', 'Plain industrial aesthetic|Fixed panel sizes - less design flexibility|Requires crane or equipment for larger panels|Less premium appearance than stone or brick', 'Precast concrete panels. Fast installation. 30-year lifespan. Good economical choice with modern appearance.', 'Active', 'None', 'AI') ON CONFLICT (component_id) DO NOTHING;
INSERT INTO components (component_id, category_name, subcategory_name, name, display_name, description, region, climate_zone, spectrum_position, sort_order, base_cost_per_sqft_inr, installation_cost_per_sqft_inr, cost_confidence, cost_last_updated, cost_source_notes, expected_lifespan_years, replacement_cost_factor, major_maintenance_cycle_years, major_maintenance_cost_factor, annual_minor_maint_factor, maintenance_complexity, lifecycle_source_notes, thermal_resistance_score, acoustic_score, durability_score, moisture_resistance, fire_rating, energy_impact_modifier, accessibility_score, thermal_source_notes, max_floors_supported, min_floors_required, max_span_supported_m, incompatible_with, compatible_with, requires_component, climate_restrictions, hard_block_rule, advisory_rule, advisory_message, advisory_severity, constraint_source_notes, ai_advisory_notes, pros, cons, tooltip_detail, status, verify_flags, data_filled_by) VALUES ('CWALL-004', 'External', 'Compound Wall', 'compound_wall_stone', 'Random Rubble Stone Wall', 'Traditional compound wall built with locally sourced granite or laterite rubble stone. Distinctive vernacular aesthetic characteristic of South India. Moderate cost, good durability, and excellent visual character for heritage-style and architect-designed homes.', 'South India', 'Warm-Humid|Hot-Dry|Temperate|Composite', 'Performance', 4, 35, 18, 'Medium', '2024-Q1', 'Rubble stone supply + skilled mason rate; Karnataka 2024; normalized per sqft', 50, 0.3, 25, 0.05, 0.002, 'Low', 'Stone masonry lifespan 40-60 years with minimal maintenance', 5, 7, 8, 'High', 'Class A', 0, 10, 'High thermal mass stone wall. Good acoustic barrier.', 20, 1, 'N/A', 'None', 'All residential configurations|Heritage and architect-designed homes', 'Skilled stone mason|Local granite or laterite rubble|Cement mortar 1:4 for bedding|Coping stone at top', 'None', 'None', 'Skilled stone mason required - random rubble quality is very workmanship-dependent', 'Random rubble stone walling quality depends entirely on mason skill. Stones must be well-packed with minimal mortar joints for stability. Inspect ongoing work - poorly laid rubble with large mortar-filled voids is weak and ugly.', 'Warning', 'IS 1597 Part 1; NBC 2016', 'Rubble stone compound walls are my recommendation for any client who wants a house that looks like it belongs in South India rather than a generic apartment complex. Granite rubble laid by a skilled mason with Bangalore blue or Tumkur grey stone creates a wall that looks more beautiful as it ages and has genuine character. The skill requirement is real - random rubble walling done by an unskilled mason with oversized mortar beds and poorly fitting stones is both ugly and weak. Spend time to find a mason who has done good stone work before and look at examples of his prior jobs. The stone should be laid with minimal mortar at joints with good contact between stones. The top coping is critical - install a proper stone coping or RCC coping to prevent water from penetrating the wall through the top.', 'Most distinctive South India vernacular aesthetic|50-year lifespan with minimal maintenance|Good acoustic and thermal mass|Ages beautifully|Locally sourced materials', 'Higher cost than precast or metal|Skilled mason required - quality varies greatly|Slower construction than precast|Stone supply logistics from quarry', 'Rubble stone compound wall. Best aesthetic for South India homes. Skilled mason essential - inspect ongoing work for quality.', 'Active', 'None', 'AI') ON CONFLICT (component_id) DO NOTHING;
INSERT INTO components (component_id, category_name, subcategory_name, name, display_name, description, region, climate_zone, spectrum_position, sort_order, base_cost_per_sqft_inr, installation_cost_per_sqft_inr, cost_confidence, cost_last_updated, cost_source_notes, expected_lifespan_years, replacement_cost_factor, major_maintenance_cycle_years, major_maintenance_cost_factor, annual_minor_maint_factor, maintenance_complexity, lifecycle_source_notes, thermal_resistance_score, acoustic_score, durability_score, moisture_resistance, fire_rating, energy_impact_modifier, accessibility_score, thermal_source_notes, max_floors_supported, min_floors_required, max_span_supported_m, incompatible_with, compatible_with, requires_component, climate_restrictions, hard_block_rule, advisory_rule, advisory_message, advisory_severity, constraint_source_notes, ai_advisory_notes, pros, cons, tooltip_detail, status, verify_flags, data_filled_by) VALUES ('CWALL-005', 'External', 'Compound Wall', 'compound_wall_brick_masonry', 'Brick Masonry Compound Wall', 'Traditional brick masonry compound wall, typically 230mm (one brick) thick, plastered and painted. Standard specification across South India. Good security, privacy, and durability. Most widely built compound wall type.', 'South India', 'Warm-Humid|Hot-Dry|Temperate|Composite', 'Premium', 5, 45, 22, 'High', '2024-Q1', 'Karnataka PWD SOR 2024-25 brick masonry; plastering + painting; normalized per sqft', 40, 0.4, 10, 0.08, 0.008, 'Low', 'Brick masonry compound wall lifespan 35-50 years with periodic painting', 5, 8, 9, 'High', 'Class A', 0, 10, 'Solid brick wall provides good acoustic barrier and thermal mass.', 20, 1, 'N/A', 'None', 'All residential configurations', 'Wire cut or burnt clay brick|Cement mortar 1:4|Plaster coat|Exterior paint|Coping at top|Pilasters at 3m centres for walls above 1.5m', 'In high rainfall zones use water-repellent exterior paint.', 'None', 'Pilasters (vertical RCC columns) mandatory at 3m centres for compound walls above 1.5m height', 'Brick compound walls above 1.5m height without vertical pilasters are structurally unstable and can topple in storms or seismic events. Pilasters at 3m spacing are mandatory as per NBC 2016.', 'Strong-Warning', 'IS 1905; NBC 2016 Part 6', 'Brick masonry compound walls are the gold standard for South India residential construction and for good reason - they are strong durable private and adaptable for CCTV cameras and lighting attachments. The structural detail that is routinely skipped is the vertical pilaster or buttress at 3 metre intervals. A 2.2 metre high compound wall spanning 30 metres without pilasters is a long thin unreinforced panel that will develop cracks and can topple during strong winds or an earth tremor. The pilasters are 230mm x 230mm RCC columns anchored in the ground below and cast before the brick work begins. They add Rs 1500-2000 per pilaster to the wall cost but are non-negotiable structurally. The coping at the top of the wall is the other detail that gets skipped - without a coping tile or RCC coping the top course of bricks absorbs rain water and the cycle of wetting and drying destroys the mortar joint within 5-8 years.', 'Best security and privacy|40-year lifespan|Strong and durable|Easy to attach cameras, lights, and decorative elements|Standard South India specification|Good acoustic barrier', 'Highest cost compound wall|Slower construction|Requires pilasters for walls above 1.5m|Regular painting maintenance|Coping detail important', 'Brick masonry compound wall. Best security and durability. Pilasters at 3m centres mandatory for walls above 1.5m. Coping tile at top.', 'Active', 'None', 'AI') ON CONFLICT (component_id) DO NOTHING;
INSERT INTO components (component_id, category_name, subcategory_name, name, display_name, description, region, climate_zone, spectrum_position, sort_order, base_cost_per_sqft_inr, installation_cost_per_sqft_inr, cost_confidence, cost_last_updated, cost_source_notes, expected_lifespan_years, replacement_cost_factor, major_maintenance_cycle_years, major_maintenance_cost_factor, annual_minor_maint_factor, maintenance_complexity, lifecycle_source_notes, thermal_resistance_score, acoustic_score, durability_score, moisture_resistance, fire_rating, energy_impact_modifier, accessibility_score, thermal_source_notes, max_floors_supported, min_floors_required, max_span_supported_m, incompatible_with, compatible_with, requires_component, climate_restrictions, hard_block_rule, advisory_rule, advisory_message, advisory_severity, constraint_source_notes, ai_advisory_notes, pros, cons, tooltip_detail, status, verify_flags, data_filled_by) VALUES ('GATE-001', 'External', 'Gate & Entry', 'gate_wooden', 'Wooden Gate', 'Timber gate using teak, sal or engineered wood frame and panels. Traditional aesthetic. Requires termite treatment and regular oiling/painting. Highest maintenance of all gate types in South India conditions.', 'South India', 'Warm-Humid|Hot-Dry|Temperate|Composite', 'Basic', 1, 15, 8, 'Medium', '2024-Q1', 'Teak/sal gate market rate 2024; normalized per sqft', 15, 0.8, 3, 0.2, 0.03, 'High', 'Timber gate lifespan 12-20 years with regular treatment; less in high humidity', 5, 5, 5, 'Low', 'Class C', 0, 9, 'No thermal contribution.', 20, 1, 'N/A', 'None', 'All residential configurations', 'Pre-construction termite treatment|Annual teak oil application|Anti-rust hinges and hardware|Gate post in concrete', 'Not recommended in coastal zones (Mangalore, Kochi) due to extreme humidity accelerating wood decay.', 'None', 'Pre-treat with termicide before installation and apply teak oil annually', 'Untreated timber gates in South India develop termite infestation within 3-5 years and require full replacement. Pre-treatment and annual maintenance are mandatory for acceptable lifespan.', 'Warning', 'IS 6313 termite protection; IS 4873', 'Wooden gates have a traditional appeal and look beautiful when new but in South India conditions they require significant ongoing maintenance commitment. South India humidity is extremely aggressive on untreated timber - termites will find untreated wood within 5 years and high moisture causes warping and paint failure. A properly treated teak gate with annual oiling and 3-yearly painting can last 15+ years but requires this discipline. If the household will not maintain the gate it will look shabby within 5 years. For clients who want a warm natural material aesthetic I recommend teak with pre-bore termite treatment and a proper schedule of annual oiling. For clients who want low maintenance go to MS powder coat or aluminium.', 'Traditional warm aesthetic|Natural material feel|Customisable to any design|Repairable locally', 'Highest maintenance requirement|Termite risk without treatment|Warps in high humidity|Not recommended for coastal areas|Fire risk compared to metal', 'Wooden gate. Pre-treat for termites. Annual oiling mandatory. Not suitable for coastal areas or low-maintenance households.', 'Active', 'None', 'AI') ON CONFLICT (component_id) DO NOTHING;
INSERT INTO components (component_id, category_name, subcategory_name, name, display_name, description, region, climate_zone, spectrum_position, sort_order, base_cost_per_sqft_inr, installation_cost_per_sqft_inr, cost_confidence, cost_last_updated, cost_source_notes, expected_lifespan_years, replacement_cost_factor, major_maintenance_cycle_years, major_maintenance_cost_factor, annual_minor_maint_factor, maintenance_complexity, lifecycle_source_notes, thermal_resistance_score, acoustic_score, durability_score, moisture_resistance, fire_rating, energy_impact_modifier, accessibility_score, thermal_source_notes, max_floors_supported, min_floors_required, max_span_supported_m, incompatible_with, compatible_with, requires_component, climate_restrictions, hard_block_rule, advisory_rule, advisory_message, advisory_severity, constraint_source_notes, ai_advisory_notes, pros, cons, tooltip_detail, status, verify_flags, data_filled_by) VALUES ('GATE-002', 'External', 'Gate & Entry', 'gate_ms_fabricated', 'MS Fabricated Gate (Powder Coated)', 'Mild steel flat section or tube fabricated gate with powder coat finish. Most common residential gate in South India. Economical, strong, and can be designed in any pattern. Good balance of cost and durability.', 'South India', 'Warm-Humid|Hot-Dry|Temperate|Composite', 'Intermediate', 2, 25, 10, 'High', '2024-Q1', 'MS gate fabrication + powder coat; Bangalore/Chennai contractor rates 2024; normalized per sqft', 20, 0.7, 5, 0.1, 0.01, 'Low', 'Powder coat MS gate lifespan 15-25 years with repainting at 7-10 years', 5, 5, 7, 'Medium', 'Class A', 0, 10, 'No thermal contribution.', 20, 1, 'N/A', 'None', 'All residential configurations', 'Galvanised and powder coated finish|Stainless steel hinges for coastal areas|Gate post anchors in concrete|Gate closer for pedestrian gate', 'In coastal zones add hot-dip galvanising before powder coat or specify SS hinges and hardware.', 'None', 'Inspect hinge weld joints annually - weld failure at hinges is the most common MS gate failure', 'The weakest point of MS gates is the weld at the hinge connection. Inspect annually and repaint touch-up any rust spots before they spread. The hinge welds bear the full gate weight and movement stress.', 'Warning', 'IS 1161; NBC 2016', 'The MS powder coated gate is the standard for South India residential construction and it is the right default choice for 90 percent of residential properties. The design flexibility is good - any pattern from simple flat bars to ornamental scroll work can be fabricated to order by a local blacksmith. The quality control issue is the powder coat thickness and the hinge weld quality. Cheap fabricators use very thin powder coat that chips within 3 years exposing the MS to rusting. Insist on minimum 70 micron powder coat thickness and check by scraping a hidden corner. The hinge welds carry the full dynamic load of the gate swinging and must be properly welded and ground smooth - rough porous welds are a stress concentration point. For coastal locations within 10km of the sea the MS will rust through within 5-8 years without hot-dip galvanising under the powder coat - specify this explicitly.', 'Most economical durable gate|Widely available fabricators|Design flexibility|20-year lifespan with maintenance|Standard South India specification|Good security', 'Requires repainting every 7-10 years|Coastal corrosion without galvanising|Hinge welds require annual inspection|Heavy for manual operation in large gates', 'MS powder coat gate. Standard and economical. Galvanise before powder coat for coastal areas. Check 70+ micron coat thickness.', 'Active', 'None', 'AI') ON CONFLICT (component_id) DO NOTHING;
INSERT INTO components (component_id, category_name, subcategory_name, name, display_name, description, region, climate_zone, spectrum_position, sort_order, base_cost_per_sqft_inr, installation_cost_per_sqft_inr, cost_confidence, cost_last_updated, cost_source_notes, expected_lifespan_years, replacement_cost_factor, major_maintenance_cycle_years, major_maintenance_cost_factor, annual_minor_maint_factor, maintenance_complexity, lifecycle_source_notes, thermal_resistance_score, acoustic_score, durability_score, moisture_resistance, fire_rating, energy_impact_modifier, accessibility_score, thermal_source_notes, max_floors_supported, min_floors_required, max_span_supported_m, incompatible_with, compatible_with, requires_component, climate_restrictions, hard_block_rule, advisory_rule, advisory_message, advisory_severity, constraint_source_notes, ai_advisory_notes, pros, cons, tooltip_detail, status, verify_flags, data_filled_by) VALUES ('GATE-003', 'External', 'Gate & Entry', 'gate_aluminium', 'Aluminium Gate', 'Extruded aluminium section gate with anodised or powder coated finish. Rust-free, lightweight, and low maintenance. Higher upfront cost than MS but much lower lifecycle cost due to zero corrosion. Good for coastal areas.', 'South India', 'Warm-Humid|Hot-Dry|Temperate|Composite', 'Performance', 3, 35, 12, 'Medium', '2024-Q1', 'Aluminium gate fabrication + anodising; South India market 2024; normalized per sqft', 30, 0.5, 15, 0.05, 0.003, 'Low', 'Aluminium gate lifespan 25-40 years; anodising lasts entire life', 5, 5, 8, 'Very High', 'Class A', 0, 10, 'No thermal contribution.', 20, 1, 'N/A', 'None', 'All residential configurations|Coastal construction', '6063-T5 architectural aluminium sections|Anodised or powder coated finish|Aluminium-compatible fixings (not steel bolts)|Spring closer for pedestrian gate', 'Strongly recommended for coastal zones within 20km of sea. No corrosion regardless of proximity to sea.', 'None', 'Use aluminium-compatible stainless steel fixings - steel bolts cause galvanic corrosion at contact with aluminium', 'Steel bolts and fixings in contact with aluminium cause galvanic corrosion that damages both materials. All fixings, hinges and hardware must be stainless steel or aluminium alloy.', 'Warning', 'IS 733; aluminium design guides', 'Aluminium gates are my specification for any coastal property and increasingly my recommendation for premium residential construction because the zero-rust zero-maintenance story is compelling over a 20-30 year period. A good anodised aluminium gate on a coastal Mangalore or Kochi property will look new after 20 years while an equivalent MS gate will have been repainted 3 times and still show corrosion at welds and joints. The hardware specification is critical - if anyone installs mild steel hinges or steel bolts into an aluminium gate you get galvanic corrosion at every contact point that destroys both materials. Specify stainless steel or aluminium alloy hardware throughout. The lower weight compared to MS also means the gate is easier to open and puts less stress on the hinge posts.', 'Zero corrosion - excellent for coastal and humid zones|30-year lifespan with no painting|Lightweight and easy to operate|Zero maintenance once installed|Premium appearance', 'Higher upfront cost than MS|Fewer fabricators available|Must use compatible SS hardware - galvanic corrosion risk|Less design flexibility than MS for intricate patterns', 'Aluminium gate. Rust-free for 30 years. Best for coastal zones. Use SS hardware only - steel bolts cause galvanic corrosion.', 'Active', 'None', 'AI') ON CONFLICT (component_id) DO NOTHING;
INSERT INTO components (component_id, category_name, subcategory_name, name, display_name, description, region, climate_zone, spectrum_position, sort_order, base_cost_per_sqft_inr, installation_cost_per_sqft_inr, cost_confidence, cost_last_updated, cost_source_notes, expected_lifespan_years, replacement_cost_factor, major_maintenance_cycle_years, major_maintenance_cost_factor, annual_minor_maint_factor, maintenance_complexity, lifecycle_source_notes, thermal_resistance_score, acoustic_score, durability_score, moisture_resistance, fire_rating, energy_impact_modifier, accessibility_score, thermal_source_notes, max_floors_supported, min_floors_required, max_span_supported_m, incompatible_with, compatible_with, requires_component, climate_restrictions, hard_block_rule, advisory_rule, advisory_message, advisory_severity, constraint_source_notes, ai_advisory_notes, pros, cons, tooltip_detail, status, verify_flags, data_filled_by) VALUES ('GATE-004', 'External', 'Gate & Entry', 'gate_wrought_iron', 'Wrought Iron Gate', 'Traditional decorative wrought iron gate with scroll work and ornamental elements. Heavy, strong, and classically aesthetic. Higher maintenance requirement than MS powder coat. Preferred for heritage-style bungalows and traditional architecture.', 'South India', 'Warm-Humid|Hot-Dry|Temperate|Composite', 'Standard', 4, 45, 18, 'Medium', '2024-Q1', 'Wrought iron gate fabrication; specialist blacksmith rate Bangalore 2024; normalized per sqft', 40, 0.3, 5, 0.12, 0.02, 'High', 'Wrought iron lifespan 30-50 years with proper painting maintenance', 5, 5, 9, 'Medium', 'Class A', 0, 8, 'No thermal contribution.', 20, 1, 'N/A', 'None', 'Heritage and colonial-style homes|Traditional bungalows', 'Rust-inhibiting primer|Oil-based gloss paint|Solid gate post anchors in concrete|Heavy-duty hinges', 'Not recommended for coastal zones without excellent ongoing maintenance.', 'None', 'Repaint with rust-inhibiting primer every 3-5 years without exception', 'Wrought iron gates that miss even one maintenance cycle will show rust penetrating through the paint within 6-12 months of neglect. The repainting cycle of every 3-5 years with rust-inhibiting primer is non-negotiable for the South India climate.', 'Warning', 'IS 2932; painting standards', 'Wrought iron gates are the right choice for heritage bungalows and civil station type homes where the architectural character of the house calls for a traditional ornamental gate. There is no substitute for the aesthetic quality of good wrought iron scroll work - powder-coated MS looks thin and industrial by comparison. The weight is significant - a large double-leaf wrought iron gate can weigh 200-300 kg and the gate posts and hinges must be proportioned for this load. The maintenance commitment is real: the smallest nick in the paint film becomes a rust spot within one monsoon and the rust then works under the paint laterally. At every repaint (every 3-5 years) wire brush all rust spots back to bare metal and apply two coats of rust-inhibiting primer before the topcoat. For clients who maintain their homes well and have authentic traditional architecture this is a wonderful choice.', 'Exceptional traditional aesthetic|40-year lifespan with maintenance|Strong and heavy - good security|Highly decorative scroll work possible|Heritage character', 'Highest maintenance requirement - repainting every 3-5 years|Heavy - requires strong gate posts and hinges|Expensive specialist fabrication|Not for coastal zones|High weight', 'Wrought iron gate. Traditional aesthetic. Repaint with rust-inhibiting primer every 3-5 years. Heavy - size gate posts accordingly.', 'Active', 'None', 'AI') ON CONFLICT (component_id) DO NOTHING;
INSERT INTO components (component_id, category_name, subcategory_name, name, display_name, description, region, climate_zone, spectrum_position, sort_order, base_cost_per_sqft_inr, installation_cost_per_sqft_inr, cost_confidence, cost_last_updated, cost_source_notes, expected_lifespan_years, replacement_cost_factor, major_maintenance_cycle_years, major_maintenance_cost_factor, annual_minor_maint_factor, maintenance_complexity, lifecycle_source_notes, thermal_resistance_score, acoustic_score, durability_score, moisture_resistance, fire_rating, energy_impact_modifier, accessibility_score, thermal_source_notes, max_floors_supported, min_floors_required, max_span_supported_m, incompatible_with, compatible_with, requires_component, climate_restrictions, hard_block_rule, advisory_rule, advisory_message, advisory_severity, constraint_source_notes, ai_advisory_notes, pros, cons, tooltip_detail, status, verify_flags, data_filled_by) VALUES ('GATE-005', 'External', 'Gate & Entry', 'gate_automated_sliding', 'Automated Sliding Gate', 'Motor-driven sliding gate on ground track with remote control and optional intercom. Premium convenience for vehicle access. MS or aluminium gate leaf on galvanised steel track. Standard for premium residential construction.', 'South India', 'Warm-Humid|Hot-Dry|Temperate|Composite', 'Premium', 5, 80, 30, 'Medium', '2024-Q1', 'Gate motor + track + gate leaf + intercom; standard residential; Bangalore 2024; normalized per sqft', 15, 0.7, 3, 0.2, 0.02, 'High', 'Gate motor lifespan 8-15 years; gate leaf 20+ years; track 20+ years', 5, 5, 7, 'Medium', 'Class A', 0, 10, 'No thermal contribution.', 20, 1, 'N/A', 'None', 'All residential configurations', 'Gate motor (CAME/BFT/Nice brand preferred)|Ground track (galvanised steel)|Manual release mechanism for power failure|Remote controls|Intercom|UPS for gate motor', 'Track drainage must be maintained in high-rainfall zones to prevent motor flooding.', 'None', 'Manual release mechanism mandatory for power failure operation', 'An automated gate without a manual release mechanism traps vehicles inside during power failure. A manual release key override mechanism on the motor is mandatory.', 'Strong-Warning', 'Gate motor manufacturer safety requirements', 'Automated sliding gates are the premium specification that makes genuine practical sense for households where the car comes and goes multiple times per day. The convenience of pressing a remote and having the gate open is significant. The specification points that matter most are the motor brand and the manual release. Cheap motors from unknown brands fail within 3-5 years in South India heat and humidity. Specify a CAME BFT or Nice motor which are European brands with genuine service network in Bangalore Chennai and Hyderabad. The manual release is non-negotiable safety equipment - a gate that will not open manually when the power is out has trapped many cars in Indian layouts during load shedding. Also specify a UPS specifically for the gate motor so power cuts do not affect gate operation. Maintain the ground track quarterly - monsoon silt accumulation in the track causes the gate to jam and damages the motor.', 'Maximum convenience - remote operation|No manual effort for vehicle entry|Integration with CCTV and intercom|Prestigious appearance|Good for households with frequent vehicle movement', 'Highest cost|Motor requires annual maintenance|Manual release mandatory|Motor lifespan 8-15 years|Track maintenance in monsoon|UPS needed for power cut operation', 'Automated sliding gate. Manual release mandatory. Use CAME/BFT/Nice motor. UPS for gate motor. Quarterly track cleaning.', 'Active', 'None', 'AI') ON CONFLICT (component_id) DO NOTHING;
INSERT INTO components (component_id, category_name, subcategory_name, name, display_name, description, region, climate_zone, spectrum_position, sort_order, base_cost_per_sqft_inr, installation_cost_per_sqft_inr, cost_confidence, cost_last_updated, cost_source_notes, expected_lifespan_years, replacement_cost_factor, major_maintenance_cycle_years, major_maintenance_cost_factor, annual_minor_maint_factor, maintenance_complexity, lifecycle_source_notes, thermal_resistance_score, acoustic_score, durability_score, moisture_resistance, fire_rating, energy_impact_modifier, accessibility_score, thermal_source_notes, max_floors_supported, min_floors_required, max_span_supported_m, incompatible_with, compatible_with, requires_component, climate_restrictions, hard_block_rule, advisory_rule, advisory_message, advisory_severity, constraint_source_notes, ai_advisory_notes, pros, cons, tooltip_detail, status, verify_flags, data_filled_by) VALUES ('DRIVE-001', 'External', 'Driveway Paving', 'driveway_gravel', 'Gravel / Crushed Stone Driveway', 'Loose gravel or crushed granite chips as driveway surface. Permeable, lowest cost, and quick to install. Requires periodic top-up as material disperses. Suitable for secondary access paths and low-use driveways.', 'South India', 'Warm-Humid|Hot-Dry|Temperate|Composite', 'Basic', 1, 5, 2, 'High', '2024-Q1', 'Crushed granite chips supply + spreading; Karnataka 2024; normalized per sqft', 5, 0.8, 2, 0.3, 0.05, 'Low', 'Gravel top-up needed every 2-3 years as material disperses', 5, 5, 3, 'Very High', 'Non-Rated', 0.05, 6, 'Permeable - no heat island effect.', 20, 1, 'N/A', 'Wheelchair or walker access', 'Car driveways|Garden paths|Secondary access', 'Geotextile membrane below gravel|Edging restraint on sides', 'None', 'None', 'Geotextile fabric below gravel prevents mixing with soil and extends life', 'Without geotextile fabric below gravel the stone mixes with soil within 1-2 monsoons creating a muddy surface. Lay geotextile before spreading gravel.', 'Warning', 'None', 'Gravel driveways are practical for secondary access and garden paths but they have real limitations for a primary vehicle driveway in South India conditions. The main issue is that the gravel migrates over time especially during heavy monsoon runoff and needs annual or biannual top-up. The other limitation is wheel track ruts - vehicle tyres compress and displace gravel creating ruts that collect water. For a car driveway used daily the PCC or paver option is significantly more practical. Gravel works well as a permeable filler between paving sections and for garden paths where foot traffic rather than vehicle load is the concern.', 'Lowest cost|Fully permeable - excellent drainage|Quick installation|Easy to add or top up|No heat island effect', 'Needs top-up every 2-3 years|Disperses to garden and street|Not suitable for wheelchair access|Ruts under vehicle tyres|Muddy without geotextile base', 'Gravel driveway. Permeable and cheapest. Lay geotextile underneath. Needs top-up every 2-3 years.', 'Active', 'None', 'AI') ON CONFLICT (component_id) DO NOTHING;
INSERT INTO components (component_id, category_name, subcategory_name, name, display_name, description, region, climate_zone, spectrum_position, sort_order, base_cost_per_sqft_inr, installation_cost_per_sqft_inr, cost_confidence, cost_last_updated, cost_source_notes, expected_lifespan_years, replacement_cost_factor, major_maintenance_cycle_years, major_maintenance_cost_factor, annual_minor_maint_factor, maintenance_complexity, lifecycle_source_notes, thermal_resistance_score, acoustic_score, durability_score, moisture_resistance, fire_rating, energy_impact_modifier, accessibility_score, thermal_source_notes, max_floors_supported, min_floors_required, max_span_supported_m, incompatible_with, compatible_with, requires_component, climate_restrictions, hard_block_rule, advisory_rule, advisory_message, advisory_severity, constraint_source_notes, ai_advisory_notes, pros, cons, tooltip_detail, status, verify_flags, data_filled_by) VALUES ('DRIVE-002', 'External', 'Driveway Paving', 'driveway_pcc', 'Plain Cement Concrete (PCC) Driveway', 'M20 grade plain cement concrete driveway slab, typically 100-125mm thick. Durable, low maintenance, and handles heavy vehicle loads. Standard residential driveway in South India. Better vehicle handling than gravel or pavers.', 'South India', 'Warm-Humid|Hot-Dry|Temperate|Composite', 'Intermediate', 2, 18, 8, 'High', '2024-Q1', 'M20 PCC driveway slab; Karnataka PWD SOR 2024-25; normalized per sqft', 25, 0.6, 10, 0.08, 0.005, 'Low', 'PCC driveway lifespan 20-30 years with expansion joints', 5, 5, 8, 'High', 'Class A', -0.05, 10, 'Impermeable surface - contributes to heat island. Light colour reduces this.', 20, 1, 'N/A', 'None', 'All vehicle types|Wheelchair access', 'M20 concrete|Expansion joints at 3m centres|Textured broom finish for non-slip|Steel mesh for reinforcement of vehicle area', 'In high rainfall areas slope minimum 1:80 for drainage.', 'None', 'Expansion joints at 3m centres mandatory to prevent slab cracking', 'PCC driveway without expansion joints will crack at irregular intervals within 3-5 years due to thermal expansion and contraction. Saw-cut or insert expansion joints at maximum 3m centres.', 'Warning', 'IS 456; NBC 2016', 'PCC driveways are the standard because they are durable maintenance-free and handle any vehicle including heavy trucks and tankers. The expansion joint is the detail that separates a good PCC driveway from one that cracks within a few years. The joint must be at maximum 3 metre centres in both directions - for a typical 10 metre long driveway that means at least 3 joints. They can be saw-cut after the concrete has cured for 24-48 hours or formed with a plastic insert before casting. Also insist on a broom finish rather than steel trowel smooth - smooth concrete becomes dangerously slippery when wet which is a safety hazard in a driveway. Minimum 1:80 slope toward the street or a drain to prevent water ponding.', 'Durable 25-year lifespan|Low maintenance|Handles all vehicle loads|Smooth for wheelchair|Widely understood by contractors', 'Impermeable - no groundwater recharge|Heat island contribution|Cracks without proper expansion joints|Monolithic - localised repairs visible|Slippery if over-trowelled', 'PCC driveway. Expansion joints at 3m centres mandatory. Broom finish for non-slip. Slope 1:80 for drainage.', 'Active', 'None', 'AI') ON CONFLICT (component_id) DO NOTHING;
INSERT INTO components (component_id, category_name, subcategory_name, name, display_name, description, region, climate_zone, spectrum_position, sort_order, base_cost_per_sqft_inr, installation_cost_per_sqft_inr, cost_confidence, cost_last_updated, cost_source_notes, expected_lifespan_years, replacement_cost_factor, major_maintenance_cycle_years, major_maintenance_cost_factor, annual_minor_maint_factor, maintenance_complexity, lifecycle_source_notes, thermal_resistance_score, acoustic_score, durability_score, moisture_resistance, fire_rating, energy_impact_modifier, accessibility_score, thermal_source_notes, max_floors_supported, min_floors_required, max_span_supported_m, incompatible_with, compatible_with, requires_component, climate_restrictions, hard_block_rule, advisory_rule, advisory_message, advisory_severity, constraint_source_notes, ai_advisory_notes, pros, cons, tooltip_detail, status, verify_flags, data_filled_by) VALUES ('DRIVE-003', 'External', 'Driveway Paving', 'driveway_interlocking_pavers', 'Interlocking Paver Blocks', 'Concrete interlocking paver blocks (60-80mm thick) on compacted sand bed. Permeable through joints, individually replaceable, attractive range of patterns and colours. Popular for premium residential driveways and pathways in South India.', 'South India', 'Warm-Humid|Hot-Dry|Temperate|Composite', 'Performance', 3, 28, 12, 'High', '2024-Q1', 'Paver blocks + sand bed + compaction; Bangalore/Chennai contractor rates 2024; normalized per sqft', 30, 0.5, 10, 0.05, 0.005, 'Low', 'Paver block lifespan 30+ years; individual blocks replaceable', 5, 5, 8, 'High', 'Class A', 0.05, 9, 'Permeable joints allow partial groundwater recharge. Less heat island than solid PCC.', 20, 1, 'N/A', 'None', 'All vehicle types|Attractive garden areas|Premium residential driveways', '80mm thick paver blocks (10N/mm2 minimum)|50mm compacted sand bed|Geotextile below sand|Edge restraint kerb|Plate compactor for settlement', 'In high-rainfall areas use jointing sand stabilised with polymer additive to prevent washout.', 'None', 'Edge kerb restraint mandatory - pavers migrate laterally without restraint', 'Interlocking pavers without a rigid edge kerb or restraint will spread laterally over time leaving gaps at edges. A concrete kerb or steel edge restraint is mandatory around the perimeter.', 'Warning', 'IS 15658; IS 1237; paver block specification', 'Interlocking paver blocks are my recommendation for premium residential driveways because the result looks beautiful and they have a significant practical advantage over monolithic PCC - individual blocks can be lifted and reset to access underground pipes without cutting or patching concrete. The permeable joints also allow meaningful groundwater recharge which is increasingly important in Bangalore where groundwater is being depleted. The installation quality matters significantly - the sand bed must be precisely 50mm thick and plate compacted before paving begins. The edge kerb is mandatory because without a restraint the pavers migrate outward at the edges within one monsoon season. In high rainfall areas use polymer stabilised jointing sand rather than plain sand which washes out of the joints repeatedly.', 'Permeable - groundwater recharge|Individual blocks replaceable for plumbing access|Attractive patterns and colours|30-year lifespan|Premium aesthetic', 'Higher cost than PCC|Edge restraint mandatory|Jointing sand needs polymer stabiliser in high rainfall|Settlement if sand bed not properly compacted|Slightly uneven surface for wheelchairs', 'Interlocking paver blocks. 30-year lifespan. Edge kerb restraint mandatory. Use polymer jointing sand in high rainfall areas.', 'Active', 'None', 'AI') ON CONFLICT (component_id) DO NOTHING;
INSERT INTO components (component_id, category_name, subcategory_name, name, display_name, description, region, climate_zone, spectrum_position, sort_order, base_cost_per_sqft_inr, installation_cost_per_sqft_inr, cost_confidence, cost_last_updated, cost_source_notes, expected_lifespan_years, replacement_cost_factor, major_maintenance_cycle_years, major_maintenance_cost_factor, annual_minor_maint_factor, maintenance_complexity, lifecycle_source_notes, thermal_resistance_score, acoustic_score, durability_score, moisture_resistance, fire_rating, energy_impact_modifier, accessibility_score, thermal_source_notes, max_floors_supported, min_floors_required, max_span_supported_m, incompatible_with, compatible_with, requires_component, climate_restrictions, hard_block_rule, advisory_rule, advisory_message, advisory_severity, constraint_source_notes, ai_advisory_notes, pros, cons, tooltip_detail, status, verify_flags, data_filled_by) VALUES ('DRIVE-004', 'External', 'Driveway Paving', 'driveway_exposed_aggregate', 'Exposed Aggregate Concrete', 'Concrete driveway with surface aggregate exposed by washing before full cure. Creates textured non-slip surface with decorative appearance. Combination of durability of PCC with improved aesthetics. Good for premium entrance driveways.', 'South India', 'Warm-Humid|Hot-Dry|Temperate|Composite', 'Premium', 4, 35, 15, 'Medium', '2024-Q1', 'Exposed aggregate concrete; specialist contractor Bangalore 2024; normalized per sqft', 25, 0.6, 10, 0.06, 0.003, 'Low', 'Exposed aggregate lifespan same as PCC base; surface texture wears gradually', 5, 5, 8, 'High', 'Class A', -0.03, 9, 'Textured surface - slight reduction in heat absorption vs smooth PCC.', 20, 1, 'N/A', 'None', 'Premium residential driveways|Entrance plaza areas', 'Selected aggregate for surface (pea gravel or crushed granite)|Surface retarder application|Water washing 4-8 hours after pour|Expansion joints|Sealer after 28-day cure', 'None', 'None', 'Timing of wash is critical - wash too early loses aggregate retention, too late aggregate cannot be removed', 'The surface wash that exposes aggregate must be done 4-8 hours after concrete pour when the retarder has softened the surface cement but the base concrete is still firm. Timing depends on temperature and humidity. Test a small corner before washing entire area.', 'Warning', 'ACI 308; concrete finishing practice', 'Exposed aggregate concrete is the premium choice for a distinctive entrance driveway that has more visual character than plain PCC while maintaining the same structural durability. The technique involves applying a surface retarder chemical that prevents the top few millimetres of cement from curing, then washing with water 4-8 hours later to expose the aggregate below. The timing is the most critical skill element - in South India summer at 35 degrees the retarder works faster than in cool monsoon conditions and the contractor must test a corner before washing the whole area. The aggregate selection is a design choice - red Bangalore granite chips give a traditional appearance while river pebble aggregate gives a contemporary look. Apply a penetrating sealer after 28 days of curing to protect the surface and deepen the colour.', 'Best aesthetic of all concrete driveways|Non-slip texture - safety advantage|Same durability as PCC base|Distinctive premium appearance|Design flexibility in aggregate choice', 'Specialist contractor required - timing is critical|Higher cost than plain PCC|Timing failure ruins entire pour|Must be sealed after curing|Impermeable like PCC', 'Exposed aggregate concrete. Best-looking driveway option. Timing of wash is critical - use specialist contractor.', 'Active', 'None', 'AI') ON CONFLICT (component_id) DO NOTHING;
INSERT INTO components (component_id, category_name, subcategory_name, name, display_name, description, region, climate_zone, spectrum_position, sort_order, base_cost_per_sqft_inr, installation_cost_per_sqft_inr, cost_confidence, cost_last_updated, cost_source_notes, expected_lifespan_years, replacement_cost_factor, major_maintenance_cycle_years, major_maintenance_cost_factor, annual_minor_maint_factor, maintenance_complexity, lifecycle_source_notes, thermal_resistance_score, acoustic_score, durability_score, moisture_resistance, fire_rating, energy_impact_modifier, accessibility_score, thermal_source_notes, max_floors_supported, min_floors_required, max_span_supported_m, incompatible_with, compatible_with, requires_component, climate_restrictions, hard_block_rule, advisory_rule, advisory_message, advisory_severity, constraint_source_notes, ai_advisory_notes, pros, cons, tooltip_detail, status, verify_flags, data_filled_by) VALUES ('GARD-001', 'External', 'Garden Landscape', 'garden_no_landscaping', 'No Landscaping (Full Hardscape)', 'No planted garden areas. All external space is paved, concreted, or gravelled. Minimal maintenance. Preferred where domestic help is not available for garden upkeep or where full car parking coverage is the priority.', 'South India', 'Warm-Humid|Hot-Dry|Temperate|Composite', 'Basic', 1, 0, 0, 'High', '2024-Q1', 'No landscaping cost', 0, 0, 0, 0, 0, 'Low', 'No landscape - no lifecycle', 2, 3, 10, 'High', 'Non-Rated', -0.1, 10, 'Full hardscape maximum heat island effect. Increases ambient temperature around building 1-2 degrees.', 20, 1, 'N/A', 'None', 'All residential configurations', 'None', 'None', 'None', 'Full hardscape increases ambient temperature and AC load - consider at least 20% soft landscaping', 'A fully paved external area increases the ambient temperature around the building by 1-2°C due to heat island effect. This increases cooling loads. Even a 20% soft landscape area significantly reduces this.', 'Warning', 'ECBC 2017; heat island effect literature', 'Full hardscape is a legitimate choice for plots where maintenance help is not available or where the site is used predominantly for vehicle parking. The thermal consequence is real - a fully paved external area in Bangalore summer can reach 55-60 degrees at noon and radiates this heat to the adjacent walls increasing cooling loads meaningfully. Even a single large shade tree or a 3-4 metre planted strip can reduce this significantly. If maintenance is the concern consider planting a few large shade trees in the setback area - mature trees require almost no maintenance and provide genuinely significant cooling through shade and evapotranspiration.', 'Zero maintenance|Maximum parking area|No irrigation needed|Clean minimal aesthetic', 'Maximum heat island effect - increases cooling loads|No biodiversity benefit|Reduced rainwater infiltration|Reduces neighbourhood greenery|Bare industrial appearance', 'Full hardscape. Zero maintenance but increases cooling loads. Even one large tree makes a significant difference.', 'Active', 'None', 'AI') ON CONFLICT (component_id) DO NOTHING;
INSERT INTO components (component_id, category_name, subcategory_name, name, display_name, description, region, climate_zone, spectrum_position, sort_order, base_cost_per_sqft_inr, installation_cost_per_sqft_inr, cost_confidence, cost_last_updated, cost_source_notes, expected_lifespan_years, replacement_cost_factor, major_maintenance_cycle_years, major_maintenance_cost_factor, annual_minor_maint_factor, maintenance_complexity, lifecycle_source_notes, thermal_resistance_score, acoustic_score, durability_score, moisture_resistance, fire_rating, energy_impact_modifier, accessibility_score, thermal_source_notes, max_floors_supported, min_floors_required, max_span_supported_m, incompatible_with, compatible_with, requires_component, climate_restrictions, hard_block_rule, advisory_rule, advisory_message, advisory_severity, constraint_source_notes, ai_advisory_notes, pros, cons, tooltip_detail, status, verify_flags, data_filled_by) VALUES ('GARD-002', 'External', 'Garden Landscape', 'garden_basic_lawn', 'Basic Lawn + Border Planting', 'Simple lawn grass (Doob/Korea/Manila grass) with border planting of seasonal flowers and shrubs. Low-cost, pleasant appearance, and easy maintenance. Most common residential garden in South India.', 'South India', 'Warm-Humid|Hot-Dry|Temperate|Composite', 'Intermediate', 2, 8, 4, 'High', '2024-Q1', 'Lawn grass sodding + border plant material; Bangalore nursery rates 2024; normalized per sqft', 20, 0.4, 5, 0.15, 0.03, 'Medium', 'Lawn requires ongoing maintenance - mowing irrigation weeding', 5, 5, 6, 'Medium', 'Non-Rated', 0.05, 9, 'Lawn reduces heat island versus hardscape. Evapotranspiration cools surrounding air by 1-2 degrees.', 20, 1, 'N/A', 'None', 'All residential configurations', 'Korea or Manila grass (lower water requirement than Doob)|Drip irrigation provision|Lawn mower|Seasonal planting budget', 'Korea grass recommended over Doob for Hot-Dry zones as lower water requirement.', 'None', 'Provide drip irrigation from the start - watering by hose wastes 3x more water', 'Hand watering or hose watering of lawn uses 3-4 times more water than drip or sprinkler irrigation. Install irrigation system during construction when pipes can be laid under the lawn.', 'Warning', 'None', 'A simple lawn and border garden is the right choice for most South India residential plots and the key to getting it right is water management. A Doob grass lawn in Bangalore summer needs watering every day without drip irrigation which is time consuming and wasteful. Switch to Korea or Manila grass which are significantly more drought tolerant and can skip a day of watering. Better still install a simple drip irrigation or pop-up sprinkler system during construction when the ground is open - running the pipe under the lawn afterwards requires digging through established grass. The border planting with seasonal flowers like marigold, portulaca and bougainvillea gives continuous colour with minimal effort and the bougainvillea can double as a natural security barrier on the boundary.', 'Pleasant green environment|Reduces heat island vs hardscape|Low cost to establish|Flexible - can be changed over time|Good for children to play on', 'Weekly lawn mowing required|Regular watering needed|Weed management|Seasonal plants need replacement|Dog or heavy foot traffic damages lawn', 'Basic lawn and borders. Install drip irrigation during construction. Korea grass better than Doob for drought tolerance.', 'Active', 'None', 'AI') ON CONFLICT (component_id) DO NOTHING;
INSERT INTO components (component_id, category_name, subcategory_name, name, display_name, description, region, climate_zone, spectrum_position, sort_order, base_cost_per_sqft_inr, installation_cost_per_sqft_inr, cost_confidence, cost_last_updated, cost_source_notes, expected_lifespan_years, replacement_cost_factor, major_maintenance_cycle_years, major_maintenance_cost_factor, annual_minor_maint_factor, maintenance_complexity, lifecycle_source_notes, thermal_resistance_score, acoustic_score, durability_score, moisture_resistance, fire_rating, energy_impact_modifier, accessibility_score, thermal_source_notes, max_floors_supported, min_floors_required, max_span_supported_m, incompatible_with, compatible_with, requires_component, climate_restrictions, hard_block_rule, advisory_rule, advisory_message, advisory_severity, constraint_source_notes, ai_advisory_notes, pros, cons, tooltip_detail, status, verify_flags, data_filled_by) VALUES ('GARD-003', 'External', 'Garden Landscape', 'garden_designed_landscape', 'Designed Landscape with Shade Trees', 'Professionally designed landscape with shade trees, feature planting, paved paths, and lawn areas. Includes large-canopy shade trees (Raintree, Neem, Jamun, Pongamia) for long-term cooling benefit. Trees reduce AC load more effectively than most insulation options over 20+ years.', 'South India', 'Warm-Humid|Hot-Dry|Temperate|Composite', 'Performance', 3, 20, 10, 'Medium', '2024-Q1', 'Landscape design fee + plant material + planting; Bangalore landscape contractor 2024; normalized per sqft', 30, 0.3, 10, 0.1, 0.03, 'Medium', 'Mature trees provide increasing benefit over 20-30 year period; low maintenance once established', 7, 6, 7, 'Medium', 'Non-Rated', 0.15, 8, 'Mature shade tree canopy reduces solar radiation on walls and roof by 30-60%. Better long-term cooling than most insulation.', 20, 1, 'N/A', 'None', 'All residential configurations|Energy-efficient homes|IGBC Green Homes compliance', 'Landscape architect plan|Shade tree species selected for climate (Neem, Pongamia, Jamun)|Drip irrigation|Soil improvement for tree planting pits', 'None', 'None', 'Plant shade trees in first year of occupancy - 10-year establishment time for effective shade', 'Shade trees take 8-15 years to provide effective canopy coverage. Plant them in the first year of occupancy for cooling benefits within the first decade of living in the house.', 'Warning', 'GRIHA landscape guidelines; urban forestry literature', 'A properly designed landscape with shade trees is the most effective passive cooling investment you can make for a South India house and the most chronically undervalued. A mature Neem or Pongamia tree with a 10-metre canopy casting shade on your west wall from 2pm to sunset reduces the solar radiation hitting that wall by 60-80 percent. Compare this to the 25-35 percent reduction a cavity wall gives you. Trees win and they get better every year. The critical point is timing - you must plant trees in the first year of occupancy because they need 8-15 years to provide meaningful shade. A 40-foot Neem tree that a previous resident planted on a Bangalore plot is worth lakhs in cooling benefit. Choose native South India species: Neem, Pongamia, Jamun, and Raintree are all fast growing, provide excellent shade, and are completely adapted to the climate requiring minimal water once established.', 'Best long-term cooling benefit of any external investment|Increasing benefit over 20-30 years|Biodiversity and bird habitat|Good acoustic buffer from street noise|Improves property aesthetics and value|Low maintenance once established', '10-15 year establishment time before full benefit|Initial professional landscape cost|Root systems can affect foundations if planted too close|Some trees drop leaves and fruit requiring sweeping|Professional landscape plan cost', 'Designed landscape with shade trees. Best long-term cooling investment. Plant trees in first year. Neem, Pongamia, Jamun recommended.', 'Active', 'None', 'AI') ON CONFLICT (component_id) DO NOTHING;
INSERT INTO components (component_id, category_name, subcategory_name, name, display_name, description, region, climate_zone, spectrum_position, sort_order, base_cost_per_sqft_inr, installation_cost_per_sqft_inr, cost_confidence, cost_last_updated, cost_source_notes, expected_lifespan_years, replacement_cost_factor, major_maintenance_cycle_years, major_maintenance_cost_factor, annual_minor_maint_factor, maintenance_complexity, lifecycle_source_notes, thermal_resistance_score, acoustic_score, durability_score, moisture_resistance, fire_rating, energy_impact_modifier, accessibility_score, thermal_source_notes, max_floors_supported, min_floors_required, max_span_supported_m, incompatible_with, compatible_with, requires_component, climate_restrictions, hard_block_rule, advisory_rule, advisory_message, advisory_severity, constraint_source_notes, ai_advisory_notes, pros, cons, tooltip_detail, status, verify_flags, data_filled_by) VALUES ('GARD-004', 'External', 'Garden Landscape', 'garden_terrace_rooftop', 'Terrace / Rooftop Garden', 'Green roof or rooftop garden on flat RCC roof using lightweight growing medium, waterproof root barrier membrane, and appropriate drought-tolerant plants. Reduces roof surface temperature by 15-25°C, improves waterproofing protection, and provides productive or ornamental garden space.', 'South India', 'Warm-Humid|Hot-Dry|Temperate|Composite', 'Premium', 4, 35, 18, 'Medium', '2024-Q1', 'Root barrier membrane + lightweight substrate + plants + drip irrigation; Bangalore 2024; normalized per sqft of roof area', 20, 0.6, 5, 0.15, 0.04, 'High', 'Root barrier 20-25 years; plant material ongoing; substrate top-up every 5 years', 8, 7, 7, 'Very High', 'Non-Rated', 0.2, 7, 'Green roof reduces roof surface temperature by 15-25 degrees C. Reduces heat transfer into building significantly.', 20, 1, 'N/A', 'None', 'Flat RCC roof|IGBC Green Homes compliance|Urban agriculture', 'Root barrier and waterproof membrane (torch-applied APP)|Drainage layer (drainage cells)|Lightweight growing substrate (perlite mix)|Drip irrigation|Structural engineer check for additional load|Access staircase', 'None', 'None', 'Structural engineer must confirm roof slab can carry additional loading (50-100 kg/sqm) before terrace garden', 'A terrace garden with growing medium adds 50-100 kg per sqm to the roof slab load. The structural engineer must confirm the slab design can accommodate this before proceeding. Overloading causes slab cracking.', 'Strong-Warning', 'IS 456 structural loading; green roof specifications', 'Terrace gardens are one of the most effective thermal interventions available for a South India flat-roof house. An unprotected RCC roof slab in Bangalore peaks at 65-70 degrees on a May afternoon and radiates this heat downward into the top floor living space all evening. A terrace garden with even 100-150mm of growing medium and dense plant coverage keeps the roof surface below 30-35 degrees because the plants shade the membrane and the evapotranspiration provides cooling. This translates directly into cooler top-floor bedrooms and lower AC run hours. The root barrier and waterproofing must be done correctly - a quality torch-applied APP membrane with a root-resistant barrier is essential before any substrate goes down because plant roots will find and penetrate any weakness in the waterproofing. Have the structural engineer confirm the slab design before loading the roof - a typical South India 125mm RCC slab is designed for 200 kg/sqm imposed load and 100mm of substrate adds about 80 kg/sqm which is within capacity but must be verified.', 'Reduces roof temperature by 15-25 degrees - significant cooling benefit|Improves waterproofing protection life|Productive space for kitchen garden or ornamental plants|Urban biodiversity|Stormwater management|IGBC compliance', 'Structural load check mandatory|Waterproofing root barrier installation quality critical|High maintenance - regular watering weeding|Limited weight means shallow substrate|Professional installation required', 'Terrace/rooftop garden. Structural engineer check for load capacity mandatory. Root barrier waterproofing critical. Reduces top floor temperature significantly.', 'Active', 'None', 'AI') ON CONFLICT (component_id) DO NOTHING;